INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(1, 'Kej', 'Genesis', 1, 1, 'In the beginning when God created the heavens and the earth,', 'en', 'NRSV-CE', 'Six Days of Creation and the Sabbath'),
(1, 'Kej', 'Genesis', 1, 2, 'the earth was a formless void and darkness covered the face of the deep, while a wind from God swept over the face of the waters.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 1, 3, 'Then God said, "Let there be light"; and there was light.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 1, 4, 'And God saw that the light was good; and God separated the light from the darkness.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 1, 5, 'God called the light Day, and the darkness he called Night. And there was evening and there was morning, the first day.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 1, 6, 'And God said, "Let there be a dome in the midst of the waters, and let it separate the waters from the waters."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 1, 7, 'So God made the dome and separated the waters that were under the dome from the waters that were above the dome. And it was so.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 1, 8, 'God called the dome Sky. And there was evening and there was morning, the second day.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 1, 9, 'And God said, "Let the waters under the sky be gathered together into one place, and let the dry land appear." And it was so.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 1, 10, 'God called the dry land Earth, and the waters that were gathered together he called Seas. And God saw that it was good.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 1, 11, 'Then God said, "Let the earth put forth vegetation: plants yielding seed, and fruit trees of every kind on earth that bear fruit with the seed in it." And it was so.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 1, 12, 'The earth brought forth vegetation: plants yielding seed of every kind, and trees of every kind bearing fruit with the seed in it. And God saw that it was good.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 1, 13, 'And there was evening and there was morning, the third day.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 1, 14, 'And God said, "Let there be lights in the dome of the sky to separate the day from the night; and let them be for signs and for seasons and for days and years,', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 1, 15, 'and let them be lights in the dome of the sky to give light upon the earth." And it was so.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 1, 16, 'God made the two great lights--the greater light to rule the day and the lesser light to rule the night--and the stars.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 1, 17, 'God set them in the dome of the sky to give light upon the earth,', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 1, 18, 'to rule over the day and over the night, and to separate the light from the darkness. And God saw that it was good.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 1, 19, 'And there was evening and there was morning, the fourth day.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 1, 20, 'And God said, "Let the waters bring forth swarms of living creatures, and let birds fly above the earth across the dome of the sky."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 1, 21, 'So God created the great sea monsters and every living creature that moves, of every kind, with which the waters swarm, and every winged bird of every kind. And God saw that it was good.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 1, 22, 'God blessed them, saying, "Be fruitful and multiply and fill the waters in the seas, and let birds multiply on the earth."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 1, 23, 'And there was evening and there was morning, the fifth day.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 1, 24, 'And God said, "Let the earth bring forth living creatures of every kind: cattle and creeping things and wild animals of the earth of every kind." And it was so.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 1, 25, 'God made the wild animals of the earth of every kind, and the cattle of every kind, and everything that creeps upon the ground of every kind. And God saw that it was good.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 1, 26, 'Then God said, "Let us make humankind in our image, according to our likeness; and let them have dominion over the fish of the sea, and over the birds of the air, and over the cattle, and over all the wild animals of the earth, and over every creeping thing that creeps upon the earth."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 1, 27, 'So God created humankind in his image,  
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(1, 'Kej', 'Genesis', 2, 1, 'Thus the heavens and the earth were finished, and all their multitude.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 2, 2, 'And on the seventh day God finished the work that he had done, and he rested on the seventh day from all the work that he had done.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 2, 3, 'So God blessed the seventh day and hallowed it, because on it God rested from all the work that he had done in creation.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 2, 4, 'These are the generations of the heavens and the earth when they were created.
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(1, 'Kej', 'Genesis', 3, 1, 'Now the serpent was more crafty than any other wild animal that the LORD God had made. He said to the woman, "Did God say, "You shall not eat from any tree in the garden"?"', 'en', 'NRSV-CE', 'The First Sin and Its Punishment'),
(1, 'Kej', 'Genesis', 3, 2, 'The woman said to the serpent, "We may eat of the fruit of the trees in the garden;', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 3, 3, 'but God said, "You shall not eat of the fruit of the tree that is in the middle of the garden, nor shall you touch it, or you shall die.""', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 3, 4, 'But the serpent said to the woman, "You will not die;', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 3, 5, 'for God knows that when you eat of it your eyes will be opened, and you will be like God, knowing good and evil."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 3, 6, 'So when the woman saw that the tree was good for food, and that it was a delight to the eyes, and that the tree was to be desired to make one wise, she took of its fruit and ate; and she also gave some to her husband, who was with her, and he ate.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 3, 7, 'Then the eyes of both were opened, and they knew that they were naked; and they sewed fig leaves together and made loincloths for themselves.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 3, 8, 'They heard the sound of the LORD God walking in the garden at the time of the evening breeze, and the man and his wife hid themselves from the presence of the LORD God among the trees of the garden.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 3, 9, 'But the LORD God called to the man, and said to him, "Where are you?"', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 3, 10, 'He said, "I heard the sound of you in the garden, and I was afraid, because I was naked; and I hid myself."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 3, 11, 'He said, "Who told you that you were naked? Have you eaten from the tree of which I commanded you not to eat?"', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 3, 12, 'The man said, "The woman whom you gave to be with me, she gave me fruit from the tree, and I ate."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 3, 13, 'Then the LORD God said to the woman, "What is this that you have done?" The woman said, "The serpent tricked me, and I ate."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 3, 14, 'The LORD God said to the serpent,
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(1, 'Kej', 'Genesis', 4, 1, 'Now the man knew his wife Eve, and she conceived and bore Cain, saying, "I have produced a man with the help of the LORD."', 'en', 'NRSV-CE', 'Cain Murders Abel'),
(1, 'Kej', 'Genesis', 4, 2, 'Next she bore his brother Abel. Now Abel was a keeper of sheep, and Cain a tiller of the ground.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 4, 3, 'In the course of time Cain brought to the LORD an offering of the fruit of the ground,', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 4, 4, 'and Abel for his part brought of the firstlings of his flock, their fat portions. And the LORD had regard for Abel and his offering,', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 4, 5, 'but for Cain and his offering he had no regard. So Cain was very angry, and his countenance fell.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 4, 6, 'The LORD said to Cain, "Why are you angry, and why has your countenance fallen?', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 4, 7, 'If you do well, will you not be accepted? And if you do not do well, sin is lurking at the door; its desire is for you, but you must master it."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 4, 8, 'Cain said to his brother Abel, "Let us go out to the field." And when they were in the field, Cain rose up against his brother Abel, and killed him.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 4, 9, 'Then the LORD said to Cain, "Where is your brother Abel?" He said, "I do not know; am I my brother"s keeper?"', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 4, 10, 'And the LORD said, "What have you done? Listen; your brother"s blood is crying out to me from the ground!', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 4, 11, 'And now you are cursed from the ground, which has opened its mouth to receive your brother"s blood from your hand.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 4, 12, 'When you till the ground, it will no longer yield to you its strength; you will be a fugitive and a wanderer on the earth."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 4, 13, 'Cain said to the LORD, "My punishment is greater than I can bear!', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 4, 14, 'Today you have driven me away from the soil, and I shall be hidden from your face; I shall be a fugitive and a wanderer on the earth, and anyone who meets me may kill me."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 4, 15, 'Then the LORD said to him, "Not so! Whoever kills Cain will suffer a sevenfold vengeance." And the LORD put a mark on Cain, so that no one who came upon him would kill him.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 4, 16, 'Then Cain went away from the presence of the LORD, and settled in the land of Nod, east of Eden.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 4, 17, 'Cain knew his wife, and she conceived and bore Enoch; and he built a city, and named it Enoch after his son Enoch.', 'en', 'NRSV-CE', 'Beginnings of Civilization'),
(1, 'Kej', 'Genesis', 4, 18, 'To Enoch was born Irad; and Irad was the father of Mehujael, and Mehujael the father of Methushael, and Methushael the father of Lamech.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 4, 19, 'Lamech took two wives; the name of the one was Adah, and the name of the other Zillah.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 4, 20, 'Adah bore Jabal; he was the ancestor of those who live in tents and have livestock.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 4, 21, 'His brother"s name was Jubal; he was the ancestor of all those who play the lyre and pipe.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 4, 22, 'Zillah bore Tubal-cain, who made all kinds of bronze and iron tools. The sister of Tubal-cain was Naamah.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 4, 23, 'Lamech said to his wives:
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(1, 'Kej', 'Genesis', 5, 1, 'This is the list of the descendants of Adam. When God created humankind, he made them in the likeness of God.', 'en', 'NRSV-CE', 'Adam"s Descendants to Noah and His Sons'),
(1, 'Kej', 'Genesis', 5, 2, 'Male and female he created them, and he blessed them and named them "Humankind" when they were created.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 5, 3, 'When Adam had lived one hundred thirty years, he became the father of a son in his likeness, according to his image, and named him Seth.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 5, 4, 'The days of Adam after he became the father of Seth were eight hundred years; and he had other sons and daughters.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 5, 5, 'Thus all the days that Adam lived were nine hundred thirty years; and he died.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 5, 6, 'When Seth had lived one hundred five years, he became the father of Enosh.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 5, 7, 'Seth lived after the birth of Enosh eight hundred seven years, and had other sons and daughters.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 5, 8, 'Thus all the days of Seth were nine hundred twelve years; and he died.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 5, 9, 'When Enosh had lived ninety years, he became the father of Kenan.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 5, 10, 'Enosh lived after the birth of Kenan eight hundred fifteen years, and had other sons and daughters.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 5, 11, 'Thus all the days of Enosh were nine hundred five years; and he died.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 5, 12, 'When Kenan had lived seventy years, he became the father of Mahalalel.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 5, 13, 'Kenan lived after the birth of Mahalalel eight hundred and forty years, and had other sons and daughters.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 5, 14, 'Thus all the days of Kenan were nine hundred and ten years; and he died.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 5, 15, 'When Mahalalel had lived sixty-five years, he became the father of Jared.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 5, 16, 'Mahalalel lived after the birth of Jared eight hundred thirty years, and had other sons and daughters.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 5, 17, 'Thus all the days of Mahalalel were eight hundred ninety-five years; and he died.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 5, 18, 'When Jared had lived one hundred sixty-two years he became the father of Enoch.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 5, 19, 'Jared lived after the birth of Enoch eight hundred years, and had other sons and daughters.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 5, 20, 'Thus all the days of Jared were nine hundred sixty-two years; and he died.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 5, 21, 'When Enoch had lived sixty-five years, he became the father of Methuselah.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 5, 22, 'Enoch walked with God after the birth of Methuselah three hundred years, and had other sons and daughters.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 5, 23, 'Thus all the days of Enoch were three hundred sixty-five years.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 5, 24, 'Enoch walked with God; then he was no more, because God took him.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 5, 25, 'When Methuselah had lived one hundred eighty-seven years, he became the father of Lamech.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 5, 26, 'Methuselah lived after the birth of Lamech seven hundred eighty-two years, and had other sons and daughters.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 5, 27, 'Thus all the days of Methuselah were nine hundred sixty-nine years; and he died.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 5, 28, 'When Lamech had lived one hundred eighty-two years, he became the father of a son;', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 5, 29, 'he named him Noah, saying, "Out of the ground that the LORD has cursed this one shall bring us relief from our work and from the toil of our hands."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 5, 30, 'Lamech lived after the birth of Noah five hundred ninety-five years, and had other sons and daughters.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 5, 31, 'Thus all the days of Lamech were seven hundred seventy-seven years; and he died.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 5, 32, 'After Noah was five hundred years old, Noah became the father of Shem, Ham, and Japheth.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(1, 'Kej', 'Genesis', 6, 1, 'When people began to multiply on the face of the ground, and daughters were born to them,', 'en', 'NRSV-CE', 'The Wickedness of Humankind'),
(1, 'Kej', 'Genesis', 6, 2, 'the sons of God saw that they were fair; and they took wives for themselves of all that they chose.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 6, 3, 'Then the LORD said, "My spirit shall not abide in mortals forever, for they are flesh; their days shall be one hundred twenty years."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 6, 4, 'The Nephilim were on the earth in those days--and also afterward--when the sons of God went in to the daughters of humans, who bore children to them. These were the heroes that were of old, warriors of renown.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 6, 5, 'The LORD saw that the wickedness of humankind was great in the earth, and that every inclination of the thoughts of their hearts was only evil continually.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 6, 6, 'And the LORD was sorry that he had made humankind on the earth, and it grieved him to his heart.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 6, 7, 'So the LORD said, "I will blot out from the earth the human beings I have created--people together with animals and creeping things and birds of the air, for I am sorry that I have made them."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 6, 8, 'But Noah found favor in the sight of the LORD.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 6, 9, 'These are the descendants of Noah. Noah was a righteous man, blameless in his generation; Noah walked with God.', 'en', 'NRSV-CE', 'Noah Pleases God'),
(1, 'Kej', 'Genesis', 6, 10, 'And Noah had three sons, Shem, Ham, and Japheth.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 6, 11, 'Now the earth was corrupt in God"s sight, and the earth was filled with violence.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 6, 12, 'And God saw that the earth was corrupt; for all flesh had corrupted its ways upon the earth.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 6, 13, 'And God said to Noah, "I have determined to make an end of all flesh, for the earth is filled with violence because of them; now I am going to destroy them along with the earth.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 6, 14, 'Make yourself an ark of cypress wood; make rooms in the ark, and cover it inside and out with pitch.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 6, 15, 'This is how you are to make it: the length of the ark three hundred cubits, its width fifty cubits, and its height thirty cubits.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 6, 16, 'Make a roof for the ark, and finish it to a cubit above; and put the door of the ark in its side; make it with lower, second, and third decks.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 6, 17, 'For my part, I am going to bring a flood of waters on the earth, to destroy from under heaven all flesh in which is the breath of life; everything that is on the earth shall die.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 6, 18, 'But I will establish my covenant with you; and you shall come into the ark, you, your sons, your wife, and your sons" wives with you.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 6, 19, 'And of every living thing, of all flesh, you shall bring two of every kind into the ark, to keep them alive with you; they shall be male and female.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 6, 20, 'Of the birds according to their kinds, and of the animals according to their kinds, of every creeping thing of the ground according to its kind, two of every kind shall come in to you, to keep them alive.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 6, 21, 'Also take with you every kind of food that is eaten, and store it up; and it shall serve as food for you and for them."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 6, 22, 'Noah did this; he did all that God commanded him.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(1, 'Kej', 'Genesis', 7, 1, 'Then the LORD said to Noah, "Go into the ark, you and all your household, for I have seen that you alone are righteous before me in this generation.', 'en', 'NRSV-CE', 'The Great Flood'),
(1, 'Kej', 'Genesis', 7, 2, 'Take with you seven pairs of all clean animals, the male and its mate; and a pair of the animals that are not clean, the male and its mate;', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 7, 3, 'and seven pairs of the birds of the air also, male and female, to keep their kind alive on the face of all the earth.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 7, 4, 'For in seven days I will send rain on the earth for forty days and forty nights; and every living thing that I have made I will blot out from the face of the ground."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 7, 5, 'And Noah did all that the LORD had commanded him.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 7, 6, 'Noah was six hundred years old when the flood of waters came on the earth.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 7, 7, 'And Noah with his sons and his wife and his sons" wives went into the ark to escape the waters of the flood.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 7, 8, 'Of clean animals, and of animals that are not clean, and of birds, and of everything that creeps on the ground,', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 7, 9, 'two and two, male and female, went into the ark with Noah, as God had commanded Noah.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 7, 10, 'And after seven days the waters of the flood came on the earth.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 7, 11, 'In the six hundredth year of Noah"s life, in the second month, on the seventeenth day of the month, on that day all the fountains of the great deep burst forth, and the windows of the heavens were opened.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 7, 12, 'The rain fell on the earth forty days and forty nights.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 7, 13, 'On the very same day Noah with his sons, Shem and Ham and Japheth, and Noah"s wife and the three wives of his sons entered the ark,', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 7, 14, 'they and every wild animal of every kind, and all domestic animals of every kind, and every creeping thing that creeps on the earth, and every bird of every kind--every bird, every winged creature.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 7, 15, 'They went into the ark with Noah, two and two of all flesh in which there was the breath of life.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 7, 16, 'And those that entered, male and female of all flesh, went in as God had commanded him; and the LORD shut him in.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 7, 17, 'The flood continued forty days on the earth; and the waters increased, and bore up the ark, and it rose high above the earth.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 7, 18, 'The waters swelled and increased greatly on the earth; and the ark floated on the face of the waters.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 7, 19, 'The waters swelled so mightily on the earth that all the high mountains under the whole heaven were covered;', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 7, 20, 'the waters swelled above the mountains, covering them fifteen cubits deep.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 7, 21, 'And all flesh died that moved on the earth, birds, domestic animals, wild animals, all swarming creatures that swarm on the earth, and all human beings;', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 7, 22, 'everything on dry land in whose nostrils was the breath of life died.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 7, 23, 'He blotted out every living thing that was on the face of the ground, human beings and animals and creeping things and birds of the air; they were blotted out from the earth. Only Noah was left, and those that were with him in the ark.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 7, 24, 'And the waters swelled on the earth for one hundred fifty days.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(1, 'Kej', 'Genesis', 8, 1, 'But God remembered Noah and all the wild animals and all the domestic animals that were with him in the ark. And God made a wind blow over the earth, and the waters subsided;', 'en', 'NRSV-CE', 'The Flood Subsides'),
(1, 'Kej', 'Genesis', 8, 2, 'the fountains of the deep and the windows of the heavens were closed, the rain from the heavens was restrained,', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 8, 3, 'and the waters gradually receded from the earth. At the end of one hundred fifty days the waters had abated;', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 8, 4, 'and in the seventh month, on the seventeenth day of the month, the ark came to rest on the mountains of Ararat.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 8, 5, 'The waters continued to abate until the tenth month; in the tenth month, on the first day of the month, the tops of the mountains appeared.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 8, 6, 'At the end of forty days Noah opened the window of the ark that he had made', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 8, 7, 'and sent out the raven; and it went to and fro until the waters were dried up from the earth.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 8, 8, 'Then he sent out the dove from him, to see if the waters had subsided from the face of the ground;', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 8, 9, 'but the dove found no place to set its foot, and it returned to him to the ark, for the waters were still on the face of the whole earth. So he put out his hand and took it and brought it into the ark with him.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 8, 10, 'He waited another seven days, and again he sent out the dove from the ark;', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 8, 11, 'and the dove came back to him in the evening, and there in its beak was a freshly plucked olive leaf; so Noah knew that the waters had subsided from the earth.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 8, 12, 'Then he waited another seven days, and sent out the dove; and it did not return to him any more.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 8, 13, 'In the six hundred first year, in the first month, on the first day of the month, the waters were dried up from the earth; and Noah removed the covering of the ark, and looked, and saw that the face of the ground was drying.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 8, 14, 'In the second month, on the twenty-seventh day of the month, the earth was dry.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 8, 15, 'Then God said to Noah,', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 8, 16, '"Go out of the ark, you and your wife, and your sons and your sons" wives with you.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 8, 17, 'Bring out with you every living thing that is with you of all flesh--birds and animals and every creeping thing that creeps on the earth--so that they may abound on the earth, and be fruitful and multiply on the earth."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 8, 18, 'So Noah went out with his sons and his wife and his sons" wives.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 8, 19, 'And every animal, every creeping thing, and every bird, everything that moves on the earth, went out of the ark by families.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 8, 20, 'Then Noah built an altar to the LORD, and took of every clean animal and of every clean bird, and offered burnt offerings on the altar.', 'en', 'NRSV-CE', 'God"s Promise to Noah'),
(1, 'Kej', 'Genesis', 8, 21, 'And when the LORD smelled the pleasing odor, the LORD said in his heart, "I will never again curse the ground because of humankind, for the inclination of the human heart is evil from youth; nor will I ever again destroy every living creature as I have done.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 8, 22, 'As long as the earth endures,  
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(1, 'Kej', 'Genesis', 9, 1, 'God blessed Noah and his sons, and said to them, "Be fruitful and multiply, and fill the earth.', 'en', 'NRSV-CE', 'The Covenant with Noah'),
(1, 'Kej', 'Genesis', 9, 2, 'The fear and dread of you shall rest on every animal of the earth, and on every bird of the air, on everything that creeps on the ground, and on all the fish of the sea; into your hand they are delivered.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 9, 3, 'Every moving thing that lives shall be food for you; and just as I gave you the green plants, I give you everything.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 9, 4, 'Only, you shall not eat flesh with its life, that is, its blood.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 9, 5, 'For your own lifeblood I will surely require a reckoning: from every animal I will require it and from human beings, each one for the blood of another, I will require a reckoning for human life.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 9, 6, 'Whoever sheds the blood of a human,  
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(1, 'Kej', 'Genesis', 10, 1, 'These are the descendants of Noah"s sons, Shem, Ham, and Japheth; children were born to them after the flood.', 'en', 'NRSV-CE', 'Nations Descended from Noah'),
(1, 'Kej', 'Genesis', 10, 2, 'The descendants of Japheth: Gomer, Magog, Madai, Javan, Tubal, Meshech, and Tiras.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 10, 3, 'The descendants of Gomer: Ashkenaz, Riphath, and Togarmah.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 10, 4, 'The descendants of Javan: Elishah, Tarshish, Kittim, and Rodanim.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 10, 5, 'From these the coastland peoples spread. These are the descendants of Japheth in their lands, with their own language, by their families, in their nations.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 10, 6, 'The descendants of Ham: Cush, Egypt, Put, and Canaan.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 10, 7, 'The descendants of Cush: Seba, Havilah, Sabtah, Raamah, and Sabteca. The descendants of Raamah: Sheba and Dedan.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 10, 8, 'Cush became the father of Nimrod; he was the first on earth to become a mighty warrior.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 10, 9, 'He was a mighty hunter before the LORD; therefore it is said, "Like Nimrod a mighty hunter before the LORD."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 10, 10, 'The beginning of his kingdom was Babel, Erech, and Accad, all of them in the land of Shinar.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 10, 11, 'From that land he went into Assyria, and built Nineveh, Rehoboth-ir, Calah, and', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 10, 12, 'Resen between Nineveh and Calah; that is the great city.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 10, 13, 'Egypt became the father of Ludim, Anamim, Lehabim, Naphtuhim,', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 10, 14, 'Pathrusim, Casluhim, and Caphtorim, from which the Philistines come.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 10, 15, 'Canaan became the father of Sidon his firstborn, and Heth,', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 10, 16, 'and the Jebusites, the Amorites, the Girgashites,', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 10, 17, 'the Hivites, the Arkites, the Sinites,', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 10, 18, 'the Arvadites, the Zemarites, and the Hamathites. Afterward the families of the Canaanites spread abroad.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 10, 19, 'And the territory of the Canaanites extended from Sidon, in the direction of Gerar, as far as Gaza, and in the direction of Sodom, Gomorrah, Admah, and Zeboiim, as far as Lasha.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 10, 20, 'These are the descendants of Ham, by their families, their languages, their lands, and their nations.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 10, 21, 'To Shem also, the father of all the children of Eber, the elder brother of Japheth, children were born.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 10, 22, 'The descendants of Shem: Elam, Asshur, Arpachshad, Lud, and Aram.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 10, 23, 'The descendants of Aram: Uz, Hul, Gether, and Mash.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 10, 24, 'Arpachshad became the father of Shelah; and Shelah became the father of Eber.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 10, 25, 'To Eber were born two sons: the name of the one was Peleg, for in his days the earth was divided, and his brother"s name was Joktan.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 10, 26, 'Joktan became the father of Almodad, Sheleph, Hazarmaveth, Jerah,', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 10, 27, 'Hadoram, Uzal, Diklah,', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 10, 28, 'Obal, Abimael, Sheba,', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 10, 29, 'Ophir, Havilah, and Jobab; all these were the descendants of Joktan.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 10, 30, 'The territory in which they lived extended from Mesha in the direction of Sephar, the hill country of the east.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 10, 31, 'These are the descendants of Shem, by their families, their languages, their lands, and their nations.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 10, 32, 'These are the families of Noah"s sons, according to their genealogies, in their nations; and from these the nations spread abroad on the earth after the flood.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(1, 'Kej', 'Genesis', 11, 1, 'Now the whole earth had one language and the same words.', 'en', 'NRSV-CE', 'The Tower of Babel'),
(1, 'Kej', 'Genesis', 11, 2, 'And as they migrated from the east, they came upon a plain in the land of Shinar and settled there.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 11, 3, 'And they said to one another, "Come, let us make bricks, and burn them thoroughly." And they had brick for stone, and bitumen for mortar.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 11, 4, 'Then they said, "Come, let us build ourselves a city, and a tower with its top in the heavens, and let us make a name for ourselves; otherwise we shall be scattered abroad upon the face of the whole earth."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 11, 5, 'The LORD came down to see the city and the tower, which mortals had built.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 11, 6, 'And the LORD said, "Look, they are one people, and they have all one language; and this is only the beginning of what they will do; nothing that they propose to do will now be impossible for them.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 11, 7, 'Come, let us go down, and confuse their language there, so that they will not understand one another"s speech."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 11, 8, 'So the LORD scattered them abroad from there over the face of all the earth, and they left off building the city.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 11, 9, 'Therefore it was called Babel, because there the LORD confused the language of all the earth; and from there the LORD scattered them abroad over the face of all the earth.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 11, 10, 'These are the descendants of Shem. When Shem was one hundred years old, he became the father of Arpachshad two years after the flood;', 'en', 'NRSV-CE', 'Descendants of Shem'),
(1, 'Kej', 'Genesis', 11, 11, 'and Shem lived after the birth of Arpachshad five hundred years, and had other sons and daughters.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 11, 12, 'When Arpachshad had lived thirty-five years, he became the father of Shelah;', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 11, 13, 'and Arpachshad lived after the birth of Shelah four hundred three years, and had other sons and daughters.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 11, 14, 'When Shelah had lived thirty years, he became the father of Eber;', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 11, 15, 'and Shelah lived after the birth of Eber four hundred three years, and had other sons and daughters.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 11, 16, 'When Eber had lived thirty-four years, he became the father of Peleg;', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 11, 17, 'and Eber lived after the birth of Peleg four hundred thirty years, and had other sons and daughters.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 11, 18, 'When Peleg had lived thirty years, he became the father of Reu;', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 11, 19, 'and Peleg lived after the birth of Reu two hundred nine years, and had other sons and daughters.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 11, 20, 'When Reu had lived thirty-two years, he became the father of Serug;', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 11, 21, 'and Reu lived after the birth of Serug two hundred seven years, and had other sons and daughters.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 11, 22, 'When Serug had lived thirty years, he became the father of Nahor;', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 11, 23, 'and Serug lived after the birth of Nahor two hundred years, and had other sons and daughters.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 11, 24, 'When Nahor had lived twenty-nine years, he became the father of Terah;', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 11, 25, 'and Nahor lived after the birth of Terah one hundred nineteen years, and had other sons and daughters.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 11, 26, 'When Terah had lived seventy years, he became the father of Abram, Nahor, and Haran.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 11, 27, 'Now these are the descendants of Terah. Terah was the father of Abram, Nahor, and Haran; and Haran was the father of Lot.', 'en', 'NRSV-CE', 'Descendants of Terah'),
(1, 'Kej', 'Genesis', 11, 28, 'Haran died before his father Terah in the land of his birth, in Ur of the Chaldeans.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 11, 29, 'Abram and Nahor took wives; the name of Abram"s wife was Sarai, and the name of Nahor"s wife was Milcah. She was the daughter of Haran the father of Milcah and Iscah.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 11, 30, 'Now Sarai was barren; she had no child.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 11, 31, 'Terah took his son Abram and his grandson Lot son of Haran, and his daughter-in-law Sarai, his son Abram"s wife, and they went out together from Ur of the Chaldeans to go into the land of Canaan; but when they came to Haran, they settled there.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 11, 32, 'The days of Terah were two hundred five years; and Terah died in Haran.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(1, 'Kej', 'Genesis', 12, 1, 'Now the LORD said to Abram, "Go from your country and your kindred and your father"s house to the land that I will show you.', 'en', 'NRSV-CE', 'The Call of Abram'),
(1, 'Kej', 'Genesis', 12, 2, 'I will make of you a great nation, and I will bless you, and make your name great, so that you will be a blessing.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 12, 3, 'I will bless those who bless you, and the one who curses you I will curse; and in you all the families of the earth shall be blessed."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 12, 4, 'So Abram went, as the LORD had told him; and Lot went with him. Abram was seventy-five years old when he departed from Haran.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 12, 5, 'Abram took his wife Sarai and his brother"s son Lot, and all the possessions that they had gathered, and the persons whom they had acquired in Haran; and they set forth to go to the land of Canaan. When they had come to the land of Canaan,', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 12, 6, 'Abram passed through the land to the place at Shechem, to the oak of Moreh. At that time the Canaanites were in the land.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 12, 7, 'Then the LORD appeared to Abram, and said, "To your offspring I will give this land." So he built there an altar to the LORD, who had appeared to him.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 12, 8, 'From there he moved on to the hill country on the east of Bethel, and pitched his tent, with Bethel on the west and Ai on the east; and there he built an altar to the LORD and invoked the name of the LORD.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 12, 9, 'And Abram journeyed on by stages toward the Negeb.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 12, 10, 'Now there was a famine in the land. So Abram went down to Egypt to reside there as an alien, for the famine was severe in the land.', 'en', 'NRSV-CE', 'Abram and Sarai in Egypt'),
(1, 'Kej', 'Genesis', 12, 11, 'When he was about to enter Egypt, he said to his wife Sarai, "I know well that you are a woman beautiful in appearance;', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 12, 12, 'and when the Egyptians see you, they will say, "This is his wife"; then they will kill me, but they will let you live.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 12, 13, 'Say you are my sister, so that it may go well with me because of you, and that my life may be spared on your account."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 12, 14, 'When Abram entered Egypt the Egyptians saw that the woman was very beautiful.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 12, 15, 'When the officials of Pharaoh saw her, they praised her to Pharaoh. And the woman was taken into Pharaoh"s house.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 12, 16, 'And for her sake he dealt well with Abram; and he had sheep, oxen, male donkeys, male and female slaves, female donkeys, and camels.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 12, 17, 'But the LORD afflicted Pharaoh and his house with great plagues because of Sarai, Abram"s wife.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 12, 18, 'So Pharaoh called Abram, and said, "What is this you have done to me? Why did you not tell me that she was your wife?', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 12, 19, 'Why did you say, "She is my sister," so that I took her for my wife? Now then, here is your wife, take her, and be gone."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 12, 20, 'And Pharaoh gave his men orders concerning him; and they set him on the way, with his wife and all that he had.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(1, 'Kej', 'Genesis', 13, 1, 'So Abram went up from Egypt, he and his wife, and all that he had, and Lot with him, into the Negeb.', 'en', 'NRSV-CE', 'Abram and Lot Separate'),
(1, 'Kej', 'Genesis', 13, 2, 'Now Abram was very rich in livestock, in silver, and in gold.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 13, 3, 'He journeyed on by stages from the Negeb as far as Bethel, to the place where his tent had been at the beginning, between Bethel and Ai,', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 13, 4, 'to the place where he had made an altar at the first; and there Abram called on the name of the LORD.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 13, 5, 'Now Lot, who went with Abram, also had flocks and herds and tents,', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 13, 6, 'so that the land could not support both of them living together; for their possessions were so great that they could not live together,', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 13, 7, 'and there was strife between the herders of Abram"s livestock and the herders of Lot"s livestock. At that time the Canaanites and the Perizzites lived in the land.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 13, 8, 'Then Abram said to Lot, "Let there be no strife between you and me, and between your herders and my herders; for we are kindred.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 13, 9, 'Is not the whole land before you? Separate yourself from me. If you take the left hand, then I will go to the right; or if you take the right hand, then I will go to the left."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 13, 10, 'Lot looked about him, and saw that the plain of the Jordan was well watered everywhere like the garden of the LORD, like the land of Egypt, in the direction of Zoar; this was before the LORD had destroyed Sodom and Gomorrah.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 13, 11, 'So Lot chose for himself all the plain of the Jordan, and Lot journeyed eastward; thus they separated from each other.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 13, 12, 'Abram settled in the land of Canaan, while Lot settled among the cities of the Plain and moved his tent as far as Sodom.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 13, 13, 'Now the people of Sodom were wicked, great sinners against the LORD.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 13, 14, 'The LORD said to Abram, after Lot had separated from him, "Raise your eyes now, and look from the place where you are, northward and southward and eastward and westward;', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 13, 15, 'for all the land that you see I will give to you and to your offspring forever.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 13, 16, 'I will make your offspring like the dust of the earth; so that if one can count the dust of the earth, your offspring also can be counted.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 13, 17, 'Rise up, walk through the length and the breadth of the land, for I will give it to you."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 13, 18, 'So Abram moved his tent, and came and settled by the oaks of Mamre, which are at Hebron; and there he built an altar to the LORD.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(1, 'Kej', 'Genesis', 14, 1, 'In the days of King Amraphel of Shinar, King Arioch of Ellasar, King Chedorlaomer of Elam, and King Tidal of Goiim,', 'en', 'NRSV-CE', 'Lot"s Captivity and Rescue'),
(1, 'Kej', 'Genesis', 14, 2, 'these kings made war with King Bera of Sodom, King Birsha of Gomorrah, King Shinab of Admah, King Shemeber of Zeboiim, and the king of Bela (that is, Zoar).', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 14, 3, 'All these joined forces in the Valley of Siddim (that is, the Dead Sea).', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 14, 4, 'Twelve years they had served Chedorlaomer, but in the thirteenth year they rebelled.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 14, 5, 'In the fourteenth year Chedorlaomer and the kings who were with him came and subdued the Rephaim in Ashteroth-karnaim, the Zuzim in Ham, the Emim in Shaveh-kiriathaim,', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 14, 6, 'and the Horites in the hill country of Seir as far as El-paran on the edge of the wilderness;', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 14, 7, 'then they turned back and came to En-mishpat (that is, Kadesh), and subdued all the country of the Amalekites, and also the Amorites who lived in Hazazon-tamar.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 14, 8, 'Then the king of Sodom, the king of Gomorrah, the king of Admah, the king of Zeboiim, and the king of Bela (that is, Zoar) went out, and they joined battle in the Valley of Siddim', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 14, 9, 'with King Chedorlaomer of Elam, King Tidal of Goiim, King Amraphel of Shinar, and King Arioch of Ellasar, four kings against five.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 14, 10, 'Now the Valley of Siddim was full of bitumen pits; and as the kings of Sodom and Gomorrah fled, some fell into them, and the rest fled to the hill country.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 14, 11, 'So the enemy took all the goods of Sodom and Gomorrah, and all their provisions, and went their way;', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 14, 12, 'they also took Lot, the son of Abram"s brother, who lived in Sodom, and his goods, and departed.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 14, 13, 'Then one who had escaped came and told Abram the Hebrew, who was living by the oaks of Mamre the Amorite, brother of Eshcol and of Aner; these were allies of Abram.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 14, 14, 'When Abram heard that his nephew had been taken captive, he led forth his trained men, born in his house, three hundred eighteen of them, and went in pursuit as far as Dan.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 14, 15, 'He divided his forces against them by night, he and his servants, and routed them and pursued them to Hobah, north of Damascus.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 14, 16, 'Then he brought back all the goods, and also brought back his nephew Lot with his goods, and the women and the people.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 14, 17, 'After his return from the defeat of Chedorlaomer and the kings who were with him, the king of Sodom went out to meet him at the Valley of Shaveh (that is, the King"s Valley).', 'en', 'NRSV-CE', 'Abram Blessed by Melchizedek'),
(1, 'Kej', 'Genesis', 14, 18, 'And King Melchizedek of Salem brought out bread and wine; he was priest of God Most High.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 14, 19, 'He blessed him and said,
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(1, 'Kej', 'Genesis', 15, 1, 'After these things the word of the LORD came to Abram in a vision, "Do not be afraid, Abram, I am your shield; your reward shall be very great."', 'en', 'NRSV-CE', 'God"s Covenant with Abram'),
(1, 'Kej', 'Genesis', 15, 2, 'But Abram said, "O Lord God, what will you give me, for I continue childless, and the heir of my house is Eliezer of Damascus?"', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 15, 3, 'And Abram said, "You have given me no offspring, and so a slave born in my house is to be my heir."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 15, 4, 'But the word of the LORD came to him, "This man shall not be your heir; no one but your very own issue shall be your heir."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 15, 5, 'He brought him outside and said, "Look toward heaven and count the stars, if you are able to count them." Then he said to him, "So shall your descendants be."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 15, 6, 'And he believed the LORD; and the LORD reckoned it to him as righteousness.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 15, 7, 'Then he said to him, "I am the LORD who brought you from Ur of the Chaldeans, to give you this land to possess."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 15, 8, 'But he said, "O Lord God, how am I to know that I shall possess it?"', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 15, 9, 'He said to him, "Bring me a heifer three years old, a female goat three years old, a ram three years old, a turtledove, and a young pigeon."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 15, 10, 'He brought him all these and cut them in two, laying each half over against the other; but he did not cut the birds in two.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 15, 11, 'And when birds of prey came down on the carcasses, Abram drove them away.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 15, 12, 'As the sun was going down, a deep sleep fell upon Abram, and a deep and terrifying darkness descended upon him.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 15, 13, 'Then the LORD said to Abram, "Know this for certain, that your offspring shall be aliens in a land that is not theirs, and shall be slaves there, and they shall be oppressed for four hundred years;', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 15, 14, 'but I will bring judgment on the nation that they serve, and afterward they shall come out with great possessions.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 15, 15, 'As for yourself, you shall go to your ancestors in peace; you shall be buried in a good old age.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 15, 16, 'And they shall come back here in the fourth generation; for the iniquity of the Amorites is not yet complete."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 15, 17, 'When the sun had gone down and it was dark, a smoking fire pot and a flaming torch passed between these pieces.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 15, 18, 'On that day the LORD made a covenant with Abram, saying, "To your descendants I give this land, from the river of Egypt to the great river, the river Euphrates,', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 15, 19, 'the land of the Kenites, the Kenizzites, the Kadmonites,', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 15, 20, 'the Hittites, the Perizzites, the Rephaim,', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 15, 21, 'the Amorites, the Canaanites, the Girgashites, and the Jebusites."', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(1, 'Kej', 'Genesis', 16, 1, 'Now Sarai, Abram"s wife, bore him no children. She had an Egyptian slave-girl whose name was Hagar,', 'en', 'NRSV-CE', 'The Birth of Ishmael'),
(1, 'Kej', 'Genesis', 16, 2, 'and Sarai said to Abram, "You see that the LORD has prevented me from bearing children; go in to my slave-girl; it may be that I shall obtain children by her." And Abram listened to the voice of Sarai.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 16, 3, 'So, after Abram had lived ten years in the land of Canaan, Sarai, Abram"s wife, took Hagar the Egyptian, her slave-girl, and gave her to her husband Abram as a wife.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 16, 4, 'He went in to Hagar, and she conceived; and when she saw that she had conceived, she looked with contempt on her mistress.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 16, 5, 'Then Sarai said to Abram, "May the wrong done to me be on you! I gave my slave-girl to your embrace, and when she saw that she had conceived, she looked on me with contempt. May the LORD judge between you and me!"', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 16, 6, 'But Abram said to Sarai, "Your slave-girl is in your power; do to her as you please." Then Sarai dealt harshly with her, and she ran away from her.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 16, 7, 'The angel of the LORD found her by a spring of water in the wilderness, the spring on the way to Shur.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 16, 8, 'And he said, "Hagar, slave-girl of Sarai, where have you come from and where are you going?" She said, "I am running away from my mistress Sarai."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 16, 9, 'The angel of the LORD said to her, "Return to your mistress, and submit to her."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 16, 10, 'The angel of the LORD also said to her, "I will so greatly multiply your offspring that they cannot be counted for multitude."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 16, 11, 'And the angel of the LORD said to her,
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(1, 'Kej', 'Genesis', 17, 1, 'When Abram was ninety-nine years old, the LORD appeared to Abram, and said to him, "I am God Almighty; walk before me, and be blameless.', 'en', 'NRSV-CE', 'The Sign of the Covenant'),
(1, 'Kej', 'Genesis', 17, 2, 'And I will make my covenant between me and you, and will make you exceedingly numerous."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 17, 3, 'Then Abram fell on his face; and God said to him,', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 17, 4, '"As for me, this is my covenant with you: You shall be the ancestor of a multitude of nations.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 17, 5, 'No longer shall your name be Abram, but your name shall be Abraham; for I have made you the ancestor of a multitude of nations.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 17, 6, 'I will make you exceedingly fruitful; and I will make nations of you, and kings shall come from you.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 17, 7, 'I will establish my covenant between me and you, and your offspring after you throughout their generations, for an everlasting covenant, to be God to you and to your offspring after you.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 17, 8, 'And I will give to you, and to your offspring after you, the land where you are now an alien, all the land of Canaan, for a perpetual holding; and I will be their God."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 17, 9, 'God said to Abraham, "As for you, you shall keep my covenant, you and your offspring after you throughout their generations.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 17, 10, 'This is my covenant, which you shall keep, between me and you and your offspring after you: Every male among you shall be circumcised.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 17, 11, 'You shall circumcise the flesh of your foreskins, and it shall be a sign of the covenant between me and you.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 17, 12, 'Throughout your generations every male among you shall be circumcised when he is eight days old, including the slave born in your house and the one bought with your money from any foreigner who is not of your offspring.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 17, 13, 'Both the slave born in your house and the one bought with your money must be circumcised. So shall my covenant be in your flesh an everlasting covenant.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 17, 14, 'Any uncircumcised male who is not circumcised in the flesh of his foreskin shall be cut off from his people; he has broken my covenant."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 17, 15, 'God said to Abraham, "As for Sarai your wife, you shall not call her Sarai, but Sarah shall be her name.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 17, 16, 'I will bless her, and moreover I will give you a son by her. I will bless her, and she shall give rise to nations; kings of peoples shall come from her."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 17, 17, 'Then Abraham fell on his face and laughed, and said to himself, "Can a child be born to a man who is a hundred years old? Can Sarah, who is ninety years old, bear a child?"', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 17, 18, 'And Abraham said to God, "O that Ishmael might live in your sight!"', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 17, 19, 'God said, "No, but your wife Sarah shall bear you a son, and you shall name him Isaac. I will establish my covenant with him as an everlasting covenant for his offspring after him.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 17, 20, 'As for Ishmael, I have heard you; I will bless him and make him fruitful and exceedingly numerous; he shall be the father of twelve princes, and I will make him a great nation.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 17, 21, 'But my covenant I will establish with Isaac, whom Sarah shall bear to you at this season next year."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 17, 22, 'And when he had finished talking with him, God went up from Abraham.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 17, 23, 'Then Abraham took his son Ishmael and all the slaves born in his house or bought with his money, every male among the men of Abraham"s house, and he circumcised the flesh of their foreskins that very day, as God had said to him.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 17, 24, 'Abraham was ninety-nine years old when he was circumcised in the flesh of his foreskin.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 17, 25, 'And his son Ishmael was thirteen years old when he was circumcised in the flesh of his foreskin.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 17, 26, 'That very day Abraham and his son Ishmael were circumcised;', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 17, 27, 'and all the men of his house, slaves born in the house and those bought with money from a foreigner, were circumcised with him.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(1, 'Kej', 'Genesis', 18, 1, 'The LORD appeared to Abraham by the oaks of Mamre, as he sat at the entrance of his tent in the heat of the day.', 'en', 'NRSV-CE', 'A Son Promised to Abraham and Sarah'),
(1, 'Kej', 'Genesis', 18, 2, 'He looked up and saw three men standing near him. When he saw them, he ran from the tent entrance to meet them, and bowed down to the ground.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 18, 3, 'He said, "My lord, if I find favor with you, do not pass by your servant.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 18, 4, 'Let a little water be brought, and wash your feet, and rest yourselves under the tree.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 18, 5, 'Let me bring a little bread, that you may refresh yourselves, and after that you may pass on--since you have come to your servant." So they said, "Do as you have said."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 18, 6, 'And Abraham hastened into the tent to Sarah, and said, "Make ready quickly three measures of choice flour, knead it, and make cakes."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 18, 7, 'Abraham ran to the herd, and took a calf, tender and good, and gave it to the servant, who hastened to prepare it.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 18, 8, 'Then he took curds and milk and the calf that he had prepared, and set it before them; and he stood by them under the tree while they ate.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 18, 9, 'They said to him, "Where is your wife Sarah?" And he said, "There, in the tent."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 18, 10, 'Then one said, "I will surely return to you in due season, and your wife Sarah shall have a son." And Sarah was listening at the tent entrance behind him.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 18, 11, 'Now Abraham and Sarah were old, advanced in age; it had ceased to be with Sarah after the manner of women.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 18, 12, 'So Sarah laughed to herself, saying, "After I have grown old, and my husband is old, shall I have pleasure?"', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 18, 13, 'The LORD said to Abraham, "Why did Sarah laugh, and say, "Shall I indeed bear a child, now that I am old?"', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 18, 14, 'Is anything too wonderful for the LORD? At the set time I will return to you, in due season, and Sarah shall have a son."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 18, 15, 'But Sarah denied, saying, "I did not laugh"; for she was afraid. He said, "Oh yes, you did laugh."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 18, 16, 'Then the men set out from there, and they looked toward Sodom; and Abraham went with them to set them on their way.', 'en', 'NRSV-CE', 'Judgment Pronounced on Sodom'),
(1, 'Kej', 'Genesis', 18, 17, 'The LORD said, "Shall I hide from Abraham what I am about to do,', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 18, 18, 'seeing that Abraham shall become a great and mighty nation, and all the nations of the earth shall be blessed in him?', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 18, 19, 'No, for I have chosen him, that he may charge his children and his household after him to keep the way of the LORD by doing righteousness and justice; so that the LORD may bring about for Abraham what he has promised him."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 18, 20, 'Then the LORD said, "How great is the outcry against Sodom and Gomorrah and how very grave their sin!', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 18, 21, 'I must go down and see whether they have done altogether according to the outcry that has come to me; and if not, I will know."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 18, 22, 'So the men turned from there, and went toward Sodom, while Abraham remained standing before the LORD.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 18, 23, 'Then Abraham came near and said, "Will you indeed sweep away the righteous with the wicked?', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 18, 24, 'Suppose there are fifty righteous within the city; will you then sweep away the place and not forgive it for the fifty righteous who are in it?', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 18, 25, 'Far be it from you to do such a thing, to slay the righteous with the wicked, so that the righteous fare as the wicked! Far be that from you! Shall not the Judge of all the earth do what is just?"', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 18, 26, 'And the LORD said, "If I find at Sodom fifty righteous in the city, I will forgive the whole place for their sake."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 18, 27, 'Abraham answered, "Let me take it upon myself to speak to the Lord, I who am but dust and ashes.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 18, 28, 'Suppose five of the fifty righteous are lacking? Will you destroy the whole city for lack of five?" And he said, "I will not destroy it if I find forty-five there."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 18, 29, 'Again he spoke to him, "Suppose forty are found there." He answered, "For the sake of forty I will not do it."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 18, 30, 'Then he said, "Oh do not let the Lord be angry if I speak. Suppose thirty are found there." He answered, "I will not do it, if I find thirty there."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 18, 31, 'He said, "Let me take it upon myself to speak to the Lord. Suppose twenty are found there." He answered, "For the sake of twenty I will not destroy it."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 18, 32, 'Then he said, "Oh do not let the Lord be angry if I speak just once more. Suppose ten are found there." He answered, "For the sake of ten I will not destroy it."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 18, 33, 'And the LORD went his way, when he had finished speaking to Abraham; and Abraham returned to his place.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(1, 'Kej', 'Genesis', 19, 1, 'The two angels came to Sodom in the evening, and Lot was sitting in the gateway of Sodom. When Lot saw them, he rose to meet them, and bowed down with his face to the ground.', 'en', 'NRSV-CE', 'The Depravity of Sodom'),
(1, 'Kej', 'Genesis', 19, 2, 'He said, "Please, my lords, turn aside to your servant"s house and spend the night, and wash your feet; then you can rise early and go on your way." They said, "No; we will spend the night in the square."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 19, 3, 'But he urged them strongly; so they turned aside to him and entered his house; and he made them a feast, and baked unleavened bread, and they ate.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 19, 4, 'But before they lay down, the men of the city, the men of Sodom, both young and old, all the people to the last man, surrounded the house;', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 19, 5, 'and they called to Lot, "Where are the men who came to you tonight? Bring them out to us, so that we may know them."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 19, 6, 'Lot went out of the door to the men, shut the door after him,', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 19, 7, 'and said, "I beg you, my brothers, do not act so wickedly.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 19, 8, 'Look, I have two daughters who have not known a man; let me bring them out to you, and do to them as you please; only do nothing to these men, for they have come under the shelter of my roof."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 19, 9, 'But they replied, "Stand back!" And they said, "This fellow came here as an alien, and he would play the judge! Now we will deal worse with you than with them." Then they pressed hard against the man Lot, and came near the door to break it down.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 19, 10, 'But the men inside reached out their hands and brought Lot into the house with them, and shut the door.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 19, 11, 'And they struck with blindness the men who were at the door of the house, both small and great, so that they were unable to find the door.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 19, 12, 'Then the men said to Lot, "Have you anyone else here? Sons-in-law, sons, daughters, or anyone you have in the city--bring them out of the place.', 'en', 'NRSV-CE', 'Sodom and Gomorrah Destroyed'),
(1, 'Kej', 'Genesis', 19, 13, 'For we are about to destroy this place, because the outcry against its people has become great before the LORD, and the LORD has sent us to destroy it."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 19, 14, 'So Lot went out and said to his sons-in-law, who were to marry his daughters, "Up, get out of this place; for the LORD is about to destroy the city." But he seemed to his sons-in-law to be jesting.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 19, 15, 'When morning dawned, the angels urged Lot, saying, "Get up, take your wife and your two daughters who are here, or else you will be consumed in the punishment of the city."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 19, 16, 'But he lingered; so the men seized him and his wife and his two daughters by the hand, the LORD being merciful to him, and they brought him out and left him outside the city.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 19, 17, 'When they had brought them outside, they said, "Flee for your life; do not look back or stop anywhere in the Plain; flee to the hills, or else you will be consumed."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 19, 18, 'And Lot said to them, "Oh, no, my lords;', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 19, 19, 'your servant has found favor with you, and you have shown me great kindness in saving my life; but I cannot flee to the hills, for fear the disaster will overtake me and I die.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 19, 20, 'Look, that city is near enough to flee to, and it is a little one. Let me escape there--is it not a little one?--and my life will be saved!"', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 19, 21, 'He said to him, "Very well, I grant you this favor too, and will not overthrow the city of which you have spoken.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 19, 22, 'Hurry, escape there, for I can do nothing until you arrive there." Therefore the city was called Zoar.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 19, 23, 'The sun had risen on the earth when Lot came to Zoar.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 19, 24, 'Then the LORD rained on Sodom and Gomorrah sulfur and fire from the LORD out of heaven;', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 19, 25, 'and he overthrew those cities, and all the Plain, and all the inhabitants of the cities, and what grew on the ground.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 19, 26, 'But Lot"s wife, behind him, looked back, and she became a pillar of salt.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 19, 27, 'Abraham went early in the morning to the place where he had stood before the LORD;', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 19, 28, 'and he looked down toward Sodom and Gomorrah and toward all the land of the Plain and saw the smoke of the land going up like the smoke of a furnace.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 19, 29, 'So it was that, when God destroyed the cities of the Plain, God remembered Abraham, and sent Lot out of the midst of the overthrow, when he overthrew the cities in which Lot had settled.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 19, 30, 'Now Lot went up out of Zoar and settled in the hills with his two daughters, for he was afraid to stay in Zoar; so he lived in a cave with his two daughters.', 'en', 'NRSV-CE', 'The Shameful Origin of Moab and Ammon'),
(1, 'Kej', 'Genesis', 19, 31, 'And the firstborn said to the younger, "Our father is old, and there is not a man on earth to come in to us after the manner of all the world.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 19, 32, 'Come, let us make our father drink wine, and we will lie with him, so that we may preserve offspring through our father."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 19, 33, 'So they made their father drink wine that night; and the firstborn went in, and lay with her father; he did not know when she lay down or when she rose.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 19, 34, 'On the next day, the firstborn said to the younger, "Look, I lay last night with my father; let us make him drink wine tonight also; then you go in and lie with him, so that we may preserve offspring through our father."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 19, 35, 'So they made their father drink wine that night also; and the younger rose, and lay with him; and he did not know when she lay down or when she rose.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 19, 36, 'Thus both the daughters of Lot became pregnant by their father.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 19, 37, 'The firstborn bore a son, and named him Moab; he is the ancestor of the Moabites to this day.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 19, 38, 'The younger also bore a son and named him Ben-ammi; he is the ancestor of the Ammonites to this day.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(1, 'Kej', 'Genesis', 20, 1, 'From there Abraham journeyed toward the region of the Negeb, and settled between Kadesh and Shur. While residing in Gerar as an alien,', 'en', 'NRSV-CE', 'Abraham and Sarah at Gerar'),
(1, 'Kej', 'Genesis', 20, 2, 'Abraham said of his wife Sarah, "She is my sister." And King Abimelech of Gerar sent and took Sarah.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 20, 3, 'But God came to Abimelech in a dream by night, and said to him, "You are about to die because of the woman whom you have taken; for she is a married woman."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 20, 4, 'Now Abimelech had not approached her; so he said, "Lord, will you destroy an innocent people?', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 20, 5, 'Did he not himself say to me, "She is my sister"? And she herself said, "He is my brother." I did this in the integrity of my heart and the innocence of my hands."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 20, 6, 'Then God said to him in the dream, "Yes, I know that you did this in the integrity of your heart; furthermore it was I who kept you from sinning against me. Therefore I did not let you touch her.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 20, 7, 'Now then, return the man"s wife; for he is a prophet, and he will pray for you and you shall live. But if you do not restore her, know that you shall surely die, you and all that are yours."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 20, 8, 'So Abimelech rose early in the morning, and called all his servants and told them all these things; and the men were very much afraid.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 20, 9, 'Then Abimelech called Abraham, and said to him, "What have you done to us? How have I sinned against you, that you have brought such great guilt on me and my kingdom? You have done things to me that ought not to be done."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 20, 10, 'And Abimelech said to Abraham, "What were you thinking of, that you did this thing?"', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 20, 11, 'Abraham said, "I did it because I thought, There is no fear of God at all in this place, and they will kill me because of my wife.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 20, 12, 'Besides, she is indeed my sister, the daughter of my father but not the daughter of my mother; and she became my wife.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 20, 13, 'And when God caused me to wander from my father"s house, I said to her, "This is the kindness you must do me: at every place to which we come, say of me, He is my brother.""', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 20, 14, 'Then Abimelech took sheep and oxen, and male and female slaves, and gave them to Abraham, and restored his wife Sarah to him.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 20, 15, 'Abimelech said, "My land is before you; settle where it pleases you."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 20, 16, 'To Sarah he said, "Look, I have given your brother a thousand pieces of silver; it is your exoneration before all who are with you; you are completely vindicated."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 20, 17, 'Then Abraham prayed to God; and God healed Abimelech, and also healed his wife and female slaves so that they bore children.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 20, 18, 'For the LORD had closed fast all the wombs of the house of Abimelech because of Sarah, Abraham"s wife.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(1, 'Kej', 'Genesis', 21, 1, 'The LORD dealt with Sarah as he had said, and the LORD did for Sarah as he had promised.', 'en', 'NRSV-CE', 'The Birth of Isaac'),
(1, 'Kej', 'Genesis', 21, 2, 'Sarah conceived and bore Abraham a son in his old age, at the time of which God had spoken to him.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 21, 3, 'Abraham gave the name Isaac to his son whom Sarah bore him.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 21, 4, 'And Abraham circumcised his son Isaac when he was eight days old, as God had commanded him.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 21, 5, 'Abraham was a hundred years old when his son Isaac was born to him.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 21, 6, 'Now Sarah said, "God has brought laughter for me; everyone who hears will laugh with me."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 21, 7, 'And she said, "Who would ever have said to Abraham that Sarah would nurse children? Yet I have borne him a son in his old age."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 21, 8, 'The child grew, and was weaned; and Abraham made a great feast on the day that Isaac was weaned.', 'en', 'NRSV-CE', 'Hagar and Ishmael Sent Away'),
(1, 'Kej', 'Genesis', 21, 9, 'But Sarah saw the son of Hagar the Egyptian, whom she had borne to Abraham, playing with her son Isaac.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 21, 10, 'So she said to Abraham, "Cast out this slave woman with her son; for the son of this slave woman shall not inherit along with my son Isaac."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 21, 11, 'The matter was very distressing to Abraham on account of his son.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 21, 12, 'But God said to Abraham, "Do not be distressed because of the boy and because of your slave woman; whatever Sarah says to you, do as she tells you, for it is through Isaac that offspring shall be named for you.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 21, 13, 'As for the son of the slave woman, I will make a nation of him also, because he is your offspring."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 21, 14, 'So Abraham rose early in the morning, and took bread and a skin of water, and gave it to Hagar, putting it on her shoulder, along with the child, and sent her away. And she departed, and wandered about in the wilderness of Beer-sheba.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 21, 15, 'When the water in the skin was gone, she cast the child under one of the bushes.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 21, 16, 'Then she went and sat down opposite him a good way off, about the distance of a bowshot; for she said, "Do not let me look on the death of the child." And as she sat opposite him, she lifted up her voice and wept.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 21, 17, 'And God heard the voice of the boy; and the angel of God called to Hagar from heaven, and said to her, "What troubles you, Hagar? Do not be afraid; for God has heard the voice of the boy where he is.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 21, 18, 'Come, lift up the boy and hold him fast with your hand, for I will make a great nation of him."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 21, 19, 'Then God opened her eyes and she saw a well of water. She went, and filled the skin with water, and gave the boy a drink.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 21, 20, 'God was with the boy, and he grew up; he lived in the wilderness, and became an expert with the bow.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 21, 21, 'He lived in the wilderness of Paran; and his mother got a wife for him from the land of Egypt.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 21, 22, 'At that time Abimelech, with Phicol the commander of his army, said to Abraham, "God is with you in all that you do;', 'en', 'NRSV-CE', 'Abraham and Abimelech Make a Covenant'),
(1, 'Kej', 'Genesis', 21, 23, 'now therefore swear to me here by God that you will not deal falsely with me or with my offspring or with my posterity, but as I have dealt loyally with you, you will deal with me and with the land where you have resided as an alien."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 21, 24, 'And Abraham said, "I swear it."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 21, 25, 'When Abraham complained to Abimelech about a well of water that Abimelech"s servants had seized,', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 21, 26, 'Abimelech said, "I do not know who has done this; you did not tell me, and I have not heard of it until today."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 21, 27, 'So Abraham took sheep and oxen and gave them to Abimelech, and the two men made a covenant.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 21, 28, 'Abraham set apart seven ewe lambs of the flock.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 21, 29, 'And Abimelech said to Abraham, "What is the meaning of these seven ewe lambs that you have set apart?"', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 21, 30, 'He said, "These seven ewe lambs you shall accept from my hand, in order that you may be a witness for me that I dug this well."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 21, 31, 'Therefore that place was called Beer-sheba; because there both of them swore an oath.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 21, 32, 'When they had made a covenant at Beer-sheba, Abimelech, with Phicol the commander of his army, left and returned to the land of the Philistines.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 21, 33, 'Abraham planted a tamarisk tree in Beer-sheba, and called there on the name of the LORD, the Everlasting God.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 21, 34, 'And Abraham resided as an alien many days in the land of the Philistines.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(1, 'Kej', 'Genesis', 22, 1, 'After these things God tested Abraham. He said to him, "Abraham!" And he said, "Here I am."', 'en', 'NRSV-CE', 'The Command to Sacrifice Isaac'),
(1, 'Kej', 'Genesis', 22, 2, 'He said, "Take your son, your only son Isaac, whom you love, and go to the land of Moriah, and offer him there as a burnt offering on one of the mountains that I shall show you."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 22, 3, 'So Abraham rose early in the morning, saddled his donkey, and took two of his young men with him, and his son Isaac; he cut the wood for the burnt offering, and set out and went to the place in the distance that God had shown him.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 22, 4, 'On the third day Abraham looked up and saw the place far away.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 22, 5, 'Then Abraham said to his young men, "Stay here with the donkey; the boy and I will go over there; we will worship, and then we will come back to you."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 22, 6, 'Abraham took the wood of the burnt offering and laid it on his son Isaac, and he himself carried the fire and the knife. So the two of them walked on together.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 22, 7, 'Isaac said to his father Abraham, "Father!" And he said, "Here I am, my son." He said, "The fire and the wood are here, but where is the lamb for a burnt offering?"', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 22, 8, 'Abraham said, "God himself will provide the lamb for a burnt offering, my son." So the two of them walked on together.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 22, 9, 'When they came to the place that God had shown him, Abraham built an altar there and laid the wood in order. He bound his son Isaac, and laid him on the altar, on top of the wood.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 22, 10, 'Then Abraham reached out his hand and took the knife to kill his son.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 22, 11, 'But the angel of the LORD called to him from heaven, and said, "Abraham, Abraham!" And he said, "Here I am."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 22, 12, 'He said, "Do not lay your hand on the boy or do anything to him; for now I know that you fear God, since you have not withheld your son, your only son, from me."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 22, 13, 'And Abraham looked up and saw a ram, caught in a thicket by its horns. Abraham went and took the ram and offered it up as a burnt offering instead of his son.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 22, 14, 'So Abraham called that place "The LORD will provide"; as it is said to this day, "On the mount of the LORD it shall be provided."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 22, 15, 'The angel of the LORD called to Abraham a second time from heaven,', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 22, 16, 'and said, "By myself I have sworn, says the LORD: Because you have done this, and have not withheld your son, your only son,', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 22, 17, 'I will indeed bless you, and I will make your offspring as numerous as the stars of heaven and as the sand that is on the seashore. And your offspring shall possess the gate of their enemies,', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 22, 18, 'and by your offspring shall all the nations of the earth gain blessing for themselves, because you have obeyed my voice."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 22, 19, 'So Abraham returned to his young men, and they arose and went together to Beer-sheba; and Abraham lived at Beer-sheba.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 22, 20, 'Now after these things it was told Abraham, "Milcah also has borne children, to your brother Nahor:', 'en', 'NRSV-CE', 'The Children of Nahor'),
(1, 'Kej', 'Genesis', 22, 21, 'Uz the firstborn, Buz his brother, Kemuel the father of Aram,', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 22, 22, 'Chesed, Hazo, Pildash, Jidlaph, and Bethuel."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 22, 23, 'Bethuel became the father of Rebekah. These eight Milcah bore to Nahor, Abraham"s brother.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 22, 24, 'Moreover, his concubine, whose name was Reumah, bore Tebah, Gaham, Tahash, and Maacah.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(1, 'Kej', 'Genesis', 23, 1, 'Sarah lived one hundred twenty-seven years; this was the length of Sarah"s life.', 'en', 'NRSV-CE', 'Sarah"s Death and Burial'),
(1, 'Kej', 'Genesis', 23, 2, 'And Sarah died at Kiriath-arba (that is, Hebron) in the land of Canaan; and Abraham went in to mourn for Sarah and to weep for her.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 23, 3, 'Abraham rose up from beside his dead, and said to the Hittites,', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 23, 4, '"I am a stranger and an alien residing among you; give me property among you for a burying place, so that I may bury my dead out of my sight."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 23, 5, 'The Hittites answered Abraham,', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 23, 6, '"Hear us, my lord; you are a mighty prince among us. Bury your dead in the choicest of our burial places; none of us will withhold from you any burial ground for burying your dead."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 23, 7, 'Abraham rose and bowed to the Hittites, the people of the land.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 23, 8, 'He said to them, "If you are willing that I should bury my dead out of my sight, hear me, and entreat for me Ephron son of Zohar,', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 23, 9, 'so that he may give me the cave of Machpelah, which he owns; it is at the end of his field. For the full price let him give it to me in your presence as a possession for a burying place."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 23, 10, 'Now Ephron was sitting among the Hittites; and Ephron the Hittite answered Abraham in the hearing of the Hittites, of all who went in at the gate of his city,', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 23, 11, '"No, my lord, hear me; I give you the field, and I give you the cave that is in it; in the presence of my people I give it to you; bury your dead."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 23, 12, 'Then Abraham bowed down before the people of the land.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 23, 13, 'He said to Ephron in the hearing of the people of the land, "If you only will listen to me! I will give the price of the field; accept it from me, so that I may bury my dead there."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 23, 14, 'Ephron answered Abraham,', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 23, 15, '"My lord, listen to me; a piece of land worth four hundred shekels of silver--what is that between you and me? Bury your dead."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 23, 16, 'Abraham agreed with Ephron; and Abraham weighed out for Ephron the silver that he had named in the hearing of the Hittites, four hundred shekels of silver, according to the weights current among the merchants.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 23, 17, 'So the field of Ephron in Machpelah, which was to the east of Mamre, the field with the cave that was in it and all the trees that were in the field, throughout its whole area, passed', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 23, 18, 'to Abraham as a possession in the presence of the Hittites, in the presence of all who went in at the gate of his city.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 23, 19, 'After this, Abraham buried Sarah his wife in the cave of the field of Machpelah facing Mamre (that is, Hebron) in the land of Canaan.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 23, 20, 'The field and the cave that is in it passed from the Hittites into Abraham"s possession as a burying place.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(1, 'Kej', 'Genesis', 24, 1, 'Now Abraham was old, well advanced in years; and the LORD had blessed Abraham in all things.', 'en', 'NRSV-CE', 'The Marriage of Isaac and Rebekah'),
(1, 'Kej', 'Genesis', 24, 2, 'Abraham said to his servant, the oldest of his house, who had charge of all that he had, "Put your hand under my thigh', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 24, 3, 'and I will make you swear by the LORD, the God of heaven and earth, that you will not get a wife for my son from the daughters of the Canaanites, among whom I live,', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 24, 4, 'but will go to my country and to my kindred and get a wife for my son Isaac."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 24, 5, 'The servant said to him, "Perhaps the woman may not be willing to follow me to this land; must I then take your son back to the land from which you came?"', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 24, 6, 'Abraham said to him, "See to it that you do not take my son back there.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 24, 7, 'The LORD, the God of heaven, who took me from my father"s house and from the land of my birth, and who spoke to me and swore to me, "To your offspring I will give this land," he will send his angel before you, and you shall take a wife for my son from there.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 24, 8, 'But if the woman is not willing to follow you, then you will be free from this oath of mine; only you must not take my son back there."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 24, 9, 'So the servant put his hand under the thigh of Abraham his master and swore to him concerning this matter.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 24, 10, 'Then the servant took ten of his master"s camels and departed, taking all kinds of choice gifts from his master; and he set out and went to Aram-naharaim, to the city of Nahor.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 24, 11, 'He made the camels kneel down outside the city by the well of water; it was toward evening, the time when women go out to draw water.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 24, 12, 'And he said, "O LORD, God of my master Abraham, please grant me success today and show steadfast love to my master Abraham.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 24, 13, 'I am standing here by the spring of water, and the daughters of the townspeople are coming out to draw water.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 24, 14, 'Let the girl to whom I shall say, "Please offer your jar that I may drink," and who shall say, "Drink, and I will water your camels"--let her be the one whom you have appointed for your servant Isaac. By this I shall know that you have shown steadfast love to my master."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 24, 15, 'Before he had finished speaking, there was Rebekah, who was born to Bethuel son of Milcah, the wife of Nahor, Abraham"s brother, coming out with her water jar on her shoulder.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 24, 16, 'The girl was very fair to look upon, a virgin, whom no man had known. She went down to the spring, filled her jar, and came up.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 24, 17, 'Then the servant ran to meet her and said, "Please let me sip a little water from your jar."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 24, 18, '"Drink, my lord," she said, and quickly lowered her jar upon her hand and gave him a drink.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 24, 19, 'When she had finished giving him a drink, she said, "I will draw for your camels also, until they have finished drinking."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 24, 20, 'So she quickly emptied her jar into the trough and ran again to the well to draw, and she drew for all his camels.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 24, 21, 'The man gazed at her in silence to learn whether or not the LORD had made his journey successful.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 24, 22, 'When the camels had finished drinking, the man took a gold nose-ring weighing a half shekel, and two bracelets for her arms weighing ten gold shekels,', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 24, 23, 'and said, "Tell me whose daughter you are. Is there room in your father"s house for us to spend the night?"', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 24, 24, 'She said to him, "I am the daughter of Bethuel son of Milcah, whom she bore to Nahor."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 24, 25, 'She added, "We have plenty of straw and fodder and a place to spend the night."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 24, 26, 'The man bowed his head and worshiped the LORD', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 24, 27, 'and said, "Blessed be the LORD, the God of my master Abraham, who has not forsaken his steadfast love and his faithfulness toward my master. As for me, the LORD has led me on the way to the house of my master"s kin."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 24, 28, 'Then the girl ran and told her mother"s household about these things.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 24, 29, 'Rebekah had a brother whose name was Laban; and Laban ran out to the man, to the spring.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 24, 30, 'As soon as he had seen the nose-ring, and the bracelets on his sister"s arms, and when he heard the words of his sister Rebekah, "Thus the man spoke to me," he went to the man; and there he was, standing by the camels at the spring.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 24, 31, 'He said, "Come in, O blessed of the LORD. Why do you stand outside when I have prepared the house and a place for the camels?"', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 24, 32, 'So the man came into the house; and Laban unloaded the camels, and gave him straw and fodder for the camels, and water to wash his feet and the feet of the men who were with him.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 24, 33, 'Then food was set before him to eat; but he said, "I will not eat until I have told my errand." He said, "Speak on."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 24, 34, 'So he said, "I am Abraham"s servant.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 24, 35, 'The LORD has greatly blessed my master, and he has become wealthy; he has given him flocks and herds, silver and gold, male and female slaves, camels and donkeys.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 24, 36, 'And Sarah my master"s wife bore a son to my master when she was old; and he has given him all that he has.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 24, 37, 'My master made me swear, saying, "You shall not take a wife for my son from the daughters of the Canaanites, in whose land I live;', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 24, 38, 'but you shall go to my father"s house, to my kindred, and get a wife for my son."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 24, 39, 'I said to my master, "Perhaps the woman will not follow me."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 24, 40, 'But he said to me, "The LORD, before whom I walk, will send his angel with you and make your way successful. You shall get a wife for my son from my kindred, from my father"s house.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 24, 41, 'Then you will be free from my oath, when you come to my kindred; even if they will not give her to you, you will be free from my oath."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 24, 42, '"I came today to the spring, and said, "O LORD, the God of my master Abraham, if now you will only make successful the way I am going!', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 24, 43, 'I am standing here by the spring of water; let the young woman who comes out to draw, to whom I shall say, "Please give me a little water from your jar to drink,"', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 24, 44, 'and who will say to me, "Drink, and I will draw for your camels also"--let her be the woman whom the LORD has appointed for my master"s son."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 24, 45, '"Before I had finished speaking in my heart, there was Rebekah coming out with her water jar on her shoulder; and she went down to the spring, and drew. I said to her, "Please let me drink."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 24, 46, 'She quickly let down her jar from her shoulder, and said, "Drink, and I will also water your camels." So I drank, and she also watered the camels.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 24, 47, 'Then I asked her, "Whose daughter are you?" She said, "The daughter of Bethuel, Nahor"s son, whom Milcah bore to him." So I put the ring on her nose, and the bracelets on her arms.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 24, 48, 'Then I bowed my head and worshiped the LORD, and blessed the LORD, the God of my master Abraham, who had led me by the right way to obtain the daughter of my master"s kinsman for his son.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 24, 49, 'Now then, if you will deal loyally and truly with my master, tell me; and if not, tell me, so that I may turn either to the right hand or to the left."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 24, 50, 'Then Laban and Bethuel answered, "The thing comes from the LORD; we cannot speak to you anything bad or good.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 24, 51, 'Look, Rebekah is before you, take her and go, and let her be the wife of your master"s son, as the LORD has spoken."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 24, 52, 'When Abraham"s servant heard their words, he bowed himself to the ground before the LORD.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 24, 53, 'And the servant brought out jewelry of silver and of gold, and garments, and gave them to Rebekah; he also gave to her brother and to her mother costly ornaments.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 24, 54, 'Then he and the men who were with him ate and drank, and they spent the night there. When they rose in the morning, he said, "Send me back to my master."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 24, 55, 'Her brother and her mother said, "Let the girl remain with us a while, at least ten days; after that she may go."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 24, 56, 'But he said to them, "Do not delay me, since the LORD has made my journey successful; let me go that I may go to my master."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 24, 57, 'They said, "We will call the girl, and ask her."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 24, 58, 'And they called Rebekah, and said to her, "Will you go with this man?" She said, "I will."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 24, 59, 'So they sent away their sister Rebekah and her nurse along with Abraham"s servant and his men.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 24, 60, 'And they blessed Rebekah and said to her,
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(1, 'Kej', 'Genesis', 25, 1, 'Abraham took another wife, whose name was Keturah.', 'en', 'NRSV-CE', 'Abraham Marries Keturah'),
(1, 'Kej', 'Genesis', 25, 2, 'She bore him Zimran, Jokshan, Medan, Midian, Ishbak, and Shuah.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 25, 3, 'Jokshan was the father of Sheba and Dedan. The sons of Dedan were Asshurim, Letushim, and Leummim.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 25, 4, 'The sons of Midian were Ephah, Epher, Hanoch, Abida, and Eldaah. All these were the children of Keturah.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 25, 5, 'Abraham gave all he had to Isaac.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 25, 6, 'But to the sons of his concubines Abraham gave gifts, while he was still living, and he sent them away from his son Isaac, eastward to the east country.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 25, 7, 'This is the length of Abraham"s life, one hundred seventy-five years.', 'en', 'NRSV-CE', 'The Death of Abraham'),
(1, 'Kej', 'Genesis', 25, 8, 'Abraham breathed his last and died in a good old age, an old man and full of years, and was gathered to his people.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 25, 9, 'His sons Isaac and Ishmael buried him in the cave of Machpelah, in the field of Ephron son of Zohar the Hittite, east of Mamre,', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 25, 10, 'the field that Abraham purchased from the Hittites. There Abraham was buried, with his wife Sarah.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 25, 11, 'After the death of Abraham God blessed his son Isaac. And Isaac settled at Beer-lahai-roi.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 25, 12, 'These are the descendants of Ishmael, Abraham"s son, whom Hagar the Egyptian, Sarah"s slave-girl, bore to Abraham.', 'en', 'NRSV-CE', 'Ishmael"s Descendants'),
(1, 'Kej', 'Genesis', 25, 13, 'These are the names of the sons of Ishmael, named in the order of their birth: Nebaioth, the firstborn of Ishmael; and Kedar, Adbeel, Mibsam,', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 25, 14, 'Mishma, Dumah, Massa,', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 25, 15, 'Hadad, Tema, Jetur, Naphish, and Kedemah.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 25, 16, 'These are the sons of Ishmael and these are their names, by their villages and by their encampments, twelve princes according to their tribes.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 25, 17, '(This is the length of the life of Ishmael, one hundred thirty-seven years; he breathed his last and died, and was gathered to his people.)', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 25, 18, 'They settled from Havilah to Shur, which is opposite Egypt in the direction of Assyria; he settled down alongside of all his people.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 25, 19, 'These are the descendants of Isaac, Abraham"s son: Abraham was the father of Isaac,', 'en', 'NRSV-CE', 'The Birth and Youth of Esau and Jacob'),
(1, 'Kej', 'Genesis', 25, 20, 'and Isaac was forty years old when he married Rebekah, daughter of Bethuel the Aramean of Paddan-aram, sister of Laban the Aramean.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 25, 21, 'Isaac prayed to the LORD for his wife, because she was barren; and the LORD granted his prayer, and his wife Rebekah conceived.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 25, 22, 'The children struggled together within her; and she said, "If it is to be this way, why do I live?" So she went to inquire of the LORD.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 25, 23, 'And the LORD said to her,
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(1, 'Kej', 'Genesis', 26, 1, 'Now there was a famine in the land, besides the former famine that had occurred in the days of Abraham. And Isaac went to Gerar, to King Abimelech of the Philistines.', 'en', 'NRSV-CE', 'Isaac and Abimelech'),
(1, 'Kej', 'Genesis', 26, 2, 'The LORD appeared to Isaac and said, "Do not go down to Egypt; settle in the land that I shall show you.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 26, 3, 'Reside in this land as an alien, and I will be with you, and will bless you; for to you and to your descendants I will give all these lands, and I will fulfill the oath that I swore to your father Abraham.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 26, 4, 'I will make your offspring as numerous as the stars of heaven, and will give to your offspring all these lands; and all the nations of the earth shall gain blessing for themselves through your offspring,', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 26, 5, 'because Abraham obeyed my voice and kept my charge, my commandments, my statutes, and my laws."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 26, 6, 'So Isaac settled in Gerar.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 26, 7, 'When the men of the place asked him about his wife, he said, "She is my sister"; for he was afraid to say, "My wife," thinking, "or else the men of the place might kill me for the sake of Rebekah, because she is attractive in appearance."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 26, 8, 'When Isaac had been there a long time, King Abimelech of the Philistines looked out of a window and saw him fondling his wife Rebekah.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 26, 9, 'So Abimelech called for Isaac, and said, "So she is your wife! Why then did you say, "She is my sister"?" Isaac said to him, "Because I thought I might die because of her."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 26, 10, 'Abimelech said, "What is this you have done to us? One of the people might easily have lain with your wife, and you would have brought guilt upon us."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 26, 11, 'So Abimelech warned all the people, saying, "Whoever touches this man or his wife shall be put to death."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 26, 12, 'Isaac sowed seed in that land, and in the same year reaped a hundredfold. The LORD blessed him,', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 26, 13, 'and the man became rich; he prospered more and more until he became very wealthy.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 26, 14, 'He had possessions of flocks and herds, and a great household, so that the Philistines envied him.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 26, 15, '(Now the Philistines had stopped up and filled with earth all the wells that his father"s servants had dug in the days of his father Abraham.)', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 26, 16, 'And Abimelech said to Isaac, "Go away from us; you have become too powerful for us."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 26, 17, 'So Isaac departed from there and camped in the valley of Gerar and settled there.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 26, 18, 'Isaac dug again the wells of water that had been dug in the days of his father Abraham; for the Philistines had stopped them up after the death of Abraham; and he gave them the names that his father had given them.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 26, 19, 'But when Isaac"s servants dug in the valley and found there a well of spring water,', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 26, 20, 'the herders of Gerar quarreled with Isaac"s herders, saying, "The water is ours." So he called the well Esek, because they contended with him.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 26, 21, 'Then they dug another well, and they quarreled over that one also; so he called it Sitnah.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 26, 22, 'He moved from there and dug another well, and they did not quarrel over it; so he called it Rehoboth, saying, "Now the LORD has made room for us, and we shall be fruitful in the land."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 26, 23, 'From there he went up to Beer-sheba.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 26, 24, 'And that very night the LORD appeared to him and said, "I am the God of your father Abraham; do not be afraid, for I am with you and will bless you and make your offspring numerous for my servant Abraham"s sake."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 26, 25, 'So he built an altar there, called on the name of the LORD, and pitched his tent there. And there Isaac"s servants dug a well.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 26, 26, 'Then Abimelech went to him from Gerar, with Ahuzzath his adviser and Phicol the commander of his army.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 26, 27, 'Isaac said to them, "Why have you come to me, seeing that you hate me and have sent me away from you?"', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 26, 28, 'They said, "We see plainly that the LORD has been with you; so we say, let there be an oath between you and us, and let us make a covenant with you', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 26, 29, 'so that you will do us no harm, just as we have not touched you and have done to you nothing but good and have sent you away in peace. You are now the blessed of the LORD."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 26, 30, 'So he made them a feast, and they ate and drank.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 26, 31, 'In the morning they rose early and exchanged oaths; and Isaac set them on their way, and they departed from him in peace.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 26, 32, 'That same day Isaac"s servants came and told him about the well that they had dug, and said to him, "We have found water!"', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 26, 33, 'He called it Shibah; therefore the name of the city is Beer-sheba to this day.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 26, 34, 'When Esau was forty years old, he married Judith daughter of Beeri the Hittite, and Basemath daughter of Elon the Hittite;', 'en', 'NRSV-CE', 'Esau"s Hittite Wives'),
(1, 'Kej', 'Genesis', 26, 35, 'and they made life bitter for Isaac and Rebekah.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(1, 'Kej', 'Genesis', 27, 1, 'When Isaac was old and his eyes were dim so that he could not see, he called his elder son Esau and said to him, "My son"; and he answered, "Here I am."', 'en', 'NRSV-CE', 'Isaac Blesses Jacob'),
(1, 'Kej', 'Genesis', 27, 2, 'He said, "See, I am old; I do not know the day of my death.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 27, 3, 'Now then, take your weapons, your quiver and your bow, and go out to the field, and hunt game for me.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 27, 4, 'Then prepare for me savory food, such as I like, and bring it to me to eat, so that I may bless you before I die."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 27, 5, 'Now Rebekah was listening when Isaac spoke to his son Esau. So when Esau went to the field to hunt for game and bring it,', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 27, 6, 'Rebekah said to her son Jacob, "I heard your father say to your brother Esau,', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 27, 7, '"Bring me game, and prepare for me savory food to eat, that I may bless you before the LORD before I die."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 27, 8, 'Now therefore, my son, obey my word as I command you.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 27, 9, 'Go to the flock, and get me two choice kids, so that I may prepare from them savory food for your father, such as he likes;', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 27, 10, 'and you shall take it to your father to eat, so that he may bless you before he dies."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 27, 11, 'But Jacob said to his mother Rebekah, "Look, my brother Esau is a hairy man, and I am a man of smooth skin.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 27, 12, 'Perhaps my father will feel me, and I shall seem to be mocking him, and bring a curse on myself and not a blessing."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 27, 13, 'His mother said to him, "Let your curse be on me, my son; only obey my word, and go, get them for me."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 27, 14, 'So he went and got them and brought them to his mother; and his mother prepared savory food, such as his father loved.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 27, 15, 'Then Rebekah took the best garments of her elder son Esau, which were with her in the house, and put them on her younger son Jacob;', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 27, 16, 'and she put the skins of the kids on his hands and on the smooth part of his neck.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 27, 17, 'Then she handed the savory food, and the bread that she had prepared, to her son Jacob.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 27, 18, 'So he went in to his father, and said, "My father"; and he said, "Here I am; who are you, my son?"', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 27, 19, 'Jacob said to his father, "I am Esau your firstborn. I have done as you told me; now sit up and eat of my game, so that you may bless me."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 27, 20, 'But Isaac said to his son, "How is it that you have found it so quickly, my son?" He answered, "Because the LORD your God granted me success."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 27, 21, 'Then Isaac said to Jacob, "Come near, that I may feel you, my son, to know whether you are really my son Esau or not."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 27, 22, 'So Jacob went up to his father Isaac, who felt him and said, "The voice is Jacob"s voice, but the hands are the hands of Esau."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 27, 23, 'He did not recognize him, because his hands were hairy like his brother Esau"s hands; so he blessed him.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 27, 24, 'He said, "Are you really my son Esau?" He answered, "I am."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 27, 25, 'Then he said, "Bring it to me, that I may eat of my son"s game and bless you." So he brought it to him, and he ate; and he brought him wine, and he drank.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 27, 26, 'Then his father Isaac said to him, "Come near and kiss me, my son."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 27, 27, 'So he came near and kissed him; and he smelled the smell of his garments, and blessed him, and said,
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(1, 'Kej', 'Genesis', 28, 1, 'Then Isaac called Jacob and blessed him, and charged him, "You shall not marry one of the Canaanite women.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 28, 2, 'Go at once to Paddan-aram to the house of Bethuel, your mother"s father; and take as wife from there one of the daughters of Laban, your mother"s brother.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 28, 3, 'May God Almighty bless you and make you fruitful and numerous, that you may become a company of peoples.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 28, 4, 'May he give to you the blessing of Abraham, to you and to your offspring with you, so that you may take possession of the land where you now live as an alien--land that God gave to Abraham."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 28, 5, 'Thus Isaac sent Jacob away; and he went to Paddan-aram, to Laban son of Bethuel the Aramean, the brother of Rebekah, Jacob"s and Esau"s mother.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 28, 6, 'Now Esau saw that Isaac had blessed Jacob and sent him away to Paddan-aram to take a wife from there, and that as he blessed him he charged him, "You shall not marry one of the Canaanite women,"', 'en', 'NRSV-CE', 'Esau Marries Ishmael"s Daughter'),
(1, 'Kej', 'Genesis', 28, 7, 'and that Jacob had obeyed his father and his mother and gone to Paddan-aram.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 28, 8, 'So when Esau saw that the Canaanite women did not please his father Isaac,', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 28, 9, 'Esau went to Ishmael and took Mahalath daughter of Abraham"s son Ishmael, and sister of Nebaioth, to be his wife in addition to the wives he had.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 28, 10, 'Jacob left Beer-sheba and went toward Haran.', 'en', 'NRSV-CE', 'Jacob"s Dream at Bethel'),
(1, 'Kej', 'Genesis', 28, 11, 'He came to a certain place and stayed there for the night, because the sun had set. Taking one of the stones of the place, he put it under his head and lay down in that place.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 28, 12, 'And he dreamed that there was a ladder set up on the earth, the top of it reaching to heaven; and the angels of God were ascending and descending on it.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 28, 13, 'And the LORD stood beside him and said, "I am the LORD, the God of Abraham your father and the God of Isaac; the land on which you lie I will give to you and to your offspring;', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 28, 14, 'and your offspring shall be like the dust of the earth, and you shall spread abroad to the west and to the east and to the north and to the south; and all the families of the earth shall be blessed in you and in your offspring.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 28, 15, 'Know that I am with you and will keep you wherever you go, and will bring you back to this land; for I will not leave you until I have done what I have promised you."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 28, 16, 'Then Jacob woke from his sleep and said, "Surely the LORD is in this place--and I did not know it!"', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 28, 17, 'And he was afraid, and said, "How awesome is this place! This is none other than the house of God, and this is the gate of heaven."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 28, 18, 'So Jacob rose early in the morning, and he took the stone that he had put under his head and set it up for a pillar and poured oil on the top of it.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 28, 19, 'He called that place Bethel; but the name of the city was Luz at the first.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 28, 20, 'Then Jacob made a vow, saying, "If God will be with me, and will keep me in this way that I go, and will give me bread to eat and clothing to wear,', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 28, 21, 'so that I come again to my father"s house in peace, then the LORD shall be my God,', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 28, 22, 'and this stone, which I have set up for a pillar, shall be God"s house; and of all that you give me I will surely give one-tenth to you."', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(1, 'Kej', 'Genesis', 29, 1, 'Then Jacob went on his journey, and came to the land of the people of the east.', 'en', 'NRSV-CE', 'Jacob Meets Rachel'),
(1, 'Kej', 'Genesis', 29, 2, 'As he looked, he saw a well in the field and three flocks of sheep lying there beside it; for out of that well the flocks were watered. The stone on the well"s mouth was large,', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 29, 3, 'and when all the flocks were gathered there, the shepherds would roll the stone from the mouth of the well, and water the sheep, and put the stone back in its place on the mouth of the well.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 29, 4, 'Jacob said to them, "My brothers, where do you come from?" They said, "We are from Haran."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 29, 5, 'He said to them, "Do you know Laban son of Nahor?" They said, "We do."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 29, 6, 'He said to them, "Is it well with him?" "Yes," they replied, "and here is his daughter Rachel, coming with the sheep."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 29, 7, 'He said, "Look, it is still broad daylight; it is not time for the animals to be gathered together. Water the sheep, and go, pasture them."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 29, 8, 'But they said, "We cannot until all the flocks are gathered together, and the stone is rolled from the mouth of the well; then we water the sheep."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 29, 9, 'While he was still speaking with them, Rachel came with her father"s sheep; for she kept them.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 29, 10, 'Now when Jacob saw Rachel, the daughter of his mother"s brother Laban, and the sheep of his mother"s brother Laban, Jacob went up and rolled the stone from the well"s mouth, and watered the flock of his mother"s brother Laban.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 29, 11, 'Then Jacob kissed Rachel, and wept aloud.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 29, 12, 'And Jacob told Rachel that he was her father"s kinsman, and that he was Rebekah"s son; and she ran and told her father.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 29, 13, 'When Laban heard the news about his sister"s son Jacob, he ran to meet him; he embraced him and kissed him, and brought him to his house. Jacob told Laban all these things,', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 29, 14, 'and Laban said to him, "Surely you are my bone and my flesh!" And he stayed with him a month.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 29, 15, 'Then Laban said to Jacob, "Because you are my kinsman, should you therefore serve me for nothing? Tell me, what shall your wages be?"', 'en', 'NRSV-CE', 'Jacob Marries Laban"s Daughters'),
(1, 'Kej', 'Genesis', 29, 16, 'Now Laban had two daughters; the name of the elder was Leah, and the name of the younger was Rachel.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 29, 17, 'Leah"s eyes were lovely, and Rachel was graceful and beautiful.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 29, 18, 'Jacob loved Rachel; so he said, "I will serve you seven years for your younger daughter Rachel."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 29, 19, 'Laban said, "It is better that I give her to you than that I should give her to any other man; stay with me."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 29, 20, 'So Jacob served seven years for Rachel, and they seemed to him but a few days because of the love he had for her.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 29, 21, 'Then Jacob said to Laban, "Give me my wife that I may go in to her, for my time is completed."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 29, 22, 'So Laban gathered together all the people of the place, and made a feast.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 29, 23, 'But in the evening he took his daughter Leah and brought her to Jacob; and he went in to her.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 29, 24, '(Laban gave his maid Zilpah to his daughter Leah to be her maid.)', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 29, 25, 'When morning came, it was Leah! And Jacob said to Laban, "What is this you have done to me? Did I not serve with you for Rachel? Why then have you deceived me?"', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 29, 26, 'Laban said, "This is not done in our country--giving the younger before the firstborn.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 29, 27, 'Complete the week of this one, and we will give you the other also in return for serving me another seven years."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 29, 28, 'Jacob did so, and completed her week; then Laban gave him his daughter Rachel as a wife.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 29, 29, '(Laban gave his maid Bilhah to his daughter Rachel to be her maid.)', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 29, 30, 'So Jacob went in to Rachel also, and he loved Rachel more than Leah. He served Laban for another seven years.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 29, 31, 'When the LORD saw that Leah was unloved, he opened her womb; but Rachel was barren.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 29, 32, 'Leah conceived and bore a son, and she named him Reuben; for she said, "Because the LORD has looked on my affliction; surely now my husband will love me."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 29, 33, 'She conceived again and bore a son, and said, "Because the LORD has heard that I am hated, he has given me this son also"; and she named him Simeon.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 29, 34, 'Again she conceived and bore a son, and said, "Now this time my husband will be joined to me, because I have borne him three sons"; therefore he was named Levi.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 29, 35, 'She conceived again and bore a son, and said, "This time I will praise the LORD"; therefore she named him Judah; then she ceased bearing.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(1, 'Kej', 'Genesis', 30, 1, 'When Rachel saw that she bore Jacob no children, she envied her sister; and she said to Jacob, "Give me children, or I shall die!"', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 30, 2, 'Jacob became very angry with Rachel and said, "Am I in the place of God, who has withheld from you the fruit of the womb?"', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 30, 3, 'Then she said, "Here is my maid Bilhah; go in to her, that she may bear upon my knees and that I too may have children through her."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 30, 4, 'So she gave him her maid Bilhah as a wife; and Jacob went in to her.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 30, 5, 'And Bilhah conceived and bore Jacob a son.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 30, 6, 'Then Rachel said, "God has judged me, and has also heard my voice and given me a son"; therefore she named him Dan.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 30, 7, 'Rachel"s maid Bilhah conceived again and bore Jacob a second son.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 30, 8, 'Then Rachel said, "With mighty wrestlings I have wrestled with my sister, and have prevailed"; so she named him Naphtali.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 30, 9, 'When Leah saw that she had ceased bearing children, she took her maid Zilpah and gave her to Jacob as a wife.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 30, 10, 'Then Leah"s maid Zilpah bore Jacob a son.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 30, 11, 'And Leah said, "Good fortune!" so she named him Gad.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 30, 12, 'Leah"s maid Zilpah bore Jacob a second son.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 30, 13, 'And Leah said, "Happy am I! For the women will call me happy"; so she named him Asher.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 30, 14, 'In the days of wheat harvest Reuben went and found mandrakes in the field, and brought them to his mother Leah. Then Rachel said to Leah, "Please give me some of your son"s mandrakes."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 30, 15, 'But she said to her, "Is it a small matter that you have taken away my husband? Would you take away my son"s mandrakes also?" Rachel said, "Then he may lie with you tonight for your son"s mandrakes."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 30, 16, 'When Jacob came from the field in the evening, Leah went out to meet him, and said, "You must come in to me; for I have hired you with my son"s mandrakes." So he lay with her that night.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 30, 17, 'And God heeded Leah, and she conceived and bore Jacob a fifth son.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 30, 18, 'Leah said, "God has given me my hire because I gave my maid to my husband"; so she named him Issachar.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 30, 19, 'And Leah conceived again, and she bore Jacob a sixth son.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 30, 20, 'Then Leah said, "God has endowed me with a good dowry; now my husband will honor me, because I have borne him six sons"; so she named him Zebulun.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 30, 21, 'Afterwards she bore a daughter, and named her Dinah.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 30, 22, 'Then God remembered Rachel, and God heeded her and opened her womb.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 30, 23, 'She conceived and bore a son, and said, "God has taken away my reproach";', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 30, 24, 'and she named him Joseph, saying, "May the LORD add to me another son!"', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 30, 25, 'When Rachel had borne Joseph, Jacob said to Laban, "Send me away, that I may go to my own home and country.', 'en', 'NRSV-CE', 'Jacob Prospers at Laban"s Expense'),
(1, 'Kej', 'Genesis', 30, 26, 'Give me my wives and my children for whom I have served you, and let me go; for you know very well the service I have given you."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 30, 27, 'But Laban said to him, "If you will allow me to say so, I have learned by divination that the LORD has blessed me because of you;', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 30, 28, 'name your wages, and I will give it."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 30, 29, 'Jacob said to him, "You yourself know how I have served you, and how your cattle have fared with me.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 30, 30, 'For you had little before I came, and it has increased abundantly; and the LORD has blessed you wherever I turned. But now when shall I provide for my own household also?"', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 30, 31, 'He said, "What shall I give you?" Jacob said, "You shall not give me anything; if you will do this for me, I will again feed your flock and keep it:', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 30, 32, 'let me pass through all your flock today, removing from it every speckled and spotted sheep and every black lamb, and the spotted and speckled among the goats; and such shall be my wages.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 30, 33, 'So my honesty will answer for me later, when you come to look into my wages with you. Every one that is not speckled and spotted among the goats and black among the lambs, if found with me, shall be counted stolen."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 30, 34, 'Laban said, "Good! Let it be as you have said."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 30, 35, 'But that day Laban removed the male goats that were striped and spotted, and all the female goats that were speckled and spotted, every one that had white on it, and every lamb that was black, and put them in charge of his sons;', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 30, 36, 'and he set a distance of three days" journey between himself and Jacob, while Jacob was pasturing the rest of Laban"s flock.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 30, 37, 'Then Jacob took fresh rods of poplar and almond and plane, and peeled white streaks in them, exposing the white of the rods.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 30, 38, 'He set the rods that he had peeled in front of the flocks in the troughs, that is, the watering places, where the flocks came to drink. And since they bred when they came to drink,', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 30, 39, 'the flocks bred in front of the rods, and so the flocks produced young that were striped, speckled, and spotted.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 30, 40, 'Jacob separated the lambs, and set the faces of the flocks toward the striped and the completely black animals in the flock of Laban; and he put his own droves apart, and did not put them with Laban"s flock.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 30, 41, 'Whenever the stronger of the flock were breeding, Jacob laid the rods in the troughs before the eyes of the flock, that they might breed among the rods,', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 30, 42, 'but for the feebler of the flock he did not lay them there; so the feebler were Laban"s, and the stronger Jacob"s.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 30, 43, 'Thus the man grew exceedingly rich, and had large flocks, and male and female slaves, and camels and donkeys.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(1, 'Kej', 'Genesis', 31, 1, 'Now Jacob heard that the sons of Laban were saying, "Jacob has taken all that was our father"s; he has gained all this wealth from what belonged to our father."', 'en', 'NRSV-CE', 'Jacob Flees with Family and Flocks'),
(1, 'Kej', 'Genesis', 31, 2, 'And Jacob saw that Laban did not regard him as favorably as he did before.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 31, 3, 'Then the LORD said to Jacob, "Return to the land of your ancestors and to your kindred, and I will be with you."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 31, 4, 'So Jacob sent and called Rachel and Leah into the field where his flock was,', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 31, 5, 'and said to them, "I see that your father does not regard me as favorably as he did before. But the God of my father has been with me.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 31, 6, 'You know that I have served your father with all my strength;', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 31, 7, 'yet your father has cheated me and changed my wages ten times, but God did not permit him to harm me.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 31, 8, 'If he said, "The speckled shall be your wages," then all the flock bore speckled; and if he said, "The striped shall be your wages," then all the flock bore striped.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 31, 9, 'Thus God has taken away the livestock of your father, and given them to me.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 31, 10, '"During the mating of the flock I once had a dream in which I looked up and saw that the male goats that leaped upon the flock were striped, speckled, and mottled.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 31, 11, 'Then the angel of God said to me in the dream, "Jacob," and I said, "Here I am!"', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 31, 12, 'And he said, "Look up and see that all the goats that leap on the flock are striped, speckled, and mottled; for I have seen all that Laban is doing to you.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 31, 13, 'I am the God of Bethel, where you anointed a pillar and made a vow to me. Now leave this land at once and return to the land of your birth.""', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 31, 14, 'Then Rachel and Leah answered him, "Is there any portion or inheritance left to us in our father"s house?', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 31, 15, 'Are we not regarded by him as foreigners? For he has sold us, and he has been using up the money given for us.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 31, 16, 'All the property that God has taken away from our father belongs to us and to our children; now then, do whatever God has said to you."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 31, 17, 'So Jacob arose, and set his children and his wives on camels;', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 31, 18, 'and he drove away all his livestock, all the property that he had gained, the livestock in his possession that he had acquired in Paddan-aram, to go to his father Isaac in the land of Canaan.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 31, 19, 'Now Laban had gone to shear his sheep, and Rachel stole her father"s household gods.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 31, 20, 'And Jacob deceived Laban the Aramean, in that he did not tell him that he intended to flee.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 31, 21, 'So he fled with all that he had; starting out he crossed the Euphrates, and set his face toward the hill country of Gilead.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 31, 22, 'On the third day Laban was told that Jacob had fled.', 'en', 'NRSV-CE', 'Laban Overtakes Jacob'),
(1, 'Kej', 'Genesis', 31, 23, 'So he took his kinsfolk with him and pursued him for seven days until he caught up with him in the hill country of Gilead.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 31, 24, 'But God came to Laban the Aramean in a dream by night, and said to him, "Take heed that you say not a word to Jacob, either good or bad."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 31, 25, 'Laban overtook Jacob. Now Jacob had pitched his tent in the hill country, and Laban with his kinsfolk camped in the hill country of Gilead.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 31, 26, 'Laban said to Jacob, "What have you done? You have deceived me, and carried away my daughters like captives of the sword.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 31, 27, 'Why did you flee secretly and deceive me and not tell me? I would have sent you away with mirth and songs, with tambourine and lyre.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 31, 28, 'And why did you not permit me to kiss my sons and my daughters farewell? What you have done is foolish.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 31, 29, 'It is in my power to do you harm; but the God of your father spoke to me last night, saying, "Take heed that you speak to Jacob neither good nor bad."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 31, 30, 'Even though you had to go because you longed greatly for your father"s house, why did you steal my gods?"', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 31, 31, 'Jacob answered Laban, "Because I was afraid, for I thought that you would take your daughters from me by force.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 31, 32, 'But anyone with whom you find your gods shall not live. In the presence of our kinsfolk, point out what I have that is yours, and take it." Now Jacob did not know that Rachel had stolen the gods.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 31, 33, 'So Laban went into Jacob"s tent, and into Leah"s tent, and into the tent of the two maids, but he did not find them. And he went out of Leah"s tent, and entered Rachel"s.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 31, 34, 'Now Rachel had taken the household gods and put them in the camel"s saddle, and sat on them. Laban felt all about in the tent, but did not find them.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 31, 35, 'And she said to her father, "Let not my lord be angry that I cannot rise before you, for the way of women is upon me." So he searched, but did not find the household gods.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 31, 36, 'Then Jacob became angry, and upbraided Laban. Jacob said to Laban, "What is my offense? What is my sin, that you have hotly pursued me?', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 31, 37, 'Although you have felt about through all my goods, what have you found of all your household goods? Set it here before my kinsfolk and your kinsfolk, so that they may decide between us two.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 31, 38, 'These twenty years I have been with you; your ewes and your female goats have not miscarried, and I have not eaten the rams of your flocks.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 31, 39, 'That which was torn by wild beasts I did not bring to you; I bore the loss of it myself; of my hand you required it, whether stolen by day or stolen by night.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 31, 40, 'It was like this with me: by day the heat consumed me, and the cold by night, and my sleep fled from my eyes.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 31, 41, 'These twenty years I have been in your house; I served you fourteen years for your two daughters, and six years for your flock, and you have changed my wages ten times.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 31, 42, 'If the God of my father, the God of Abraham and the Fear of Isaac, had not been on my side, surely now you would have sent me away empty-handed. God saw my affliction and the labor of my hands, and rebuked you last night."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 31, 43, 'Then Laban answered and said to Jacob, "The daughters are my daughters, the children are my children, the flocks are my flocks, and all that you see is mine. But what can I do today about these daughters of mine, or about their children whom they have borne?', 'en', 'NRSV-CE', 'Laban and Jacob Make a Covenant'),
(1, 'Kej', 'Genesis', 31, 44, 'Come now, let us make a covenant, you and I; and let it be a witness between you and me."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 31, 45, 'So Jacob took a stone, and set it up as a pillar.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 31, 46, 'And Jacob said to his kinsfolk, "Gather stones," and they took stones, and made a heap; and they ate there by the heap.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 31, 47, 'Laban called it Jegar-sahadutha: but Jacob called it Galeed.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 31, 48, 'Laban said, "This heap is a witness between you and me today." Therefore he called it Galeed,', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 31, 49, 'and the pillar Mizpah, for he said, "The LORD watch between you and me, when we are absent one from the other.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 31, 50, 'If you ill-treat my daughters, or if you take wives in addition to my daughters, though no one else is with us, remember that God is witness between you and me."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 31, 51, 'Then Laban said to Jacob, "See this heap and see the pillar, which I have set between you and me.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 31, 52, 'This heap is a witness, and the pillar is a witness, that I will not pass beyond this heap to you, and you will not pass beyond this heap and this pillar to me, for harm.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 31, 53, 'May the God of Abraham and the God of Nahor"--the God of their father--"judge between us." So Jacob swore by the Fear of his father Isaac,', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 31, 54, 'and Jacob offered a sacrifice on the height and called his kinsfolk to eat bread; and they ate bread and tarried all night in the hill country.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 31, 55, 'Early in the morning Laban rose up, and kissed his grandchildren and his daughters and blessed them; then he departed and returned home.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(1, 'Kej', 'Genesis', 32, 1, 'Jacob went on his way and the angels of God met him;', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 32, 2, 'and when Jacob saw them he said, "This is God"s camp!" So he called that place Mahanaim.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 32, 3, 'Jacob sent messengers before him to his brother Esau in the land of Seir, the country of Edom,', 'en', 'NRSV-CE', 'Jacob Sends Presents to Appease Esau'),
(1, 'Kej', 'Genesis', 32, 4, 'instructing them, "Thus you shall say to my lord Esau: Thus says your servant Jacob, "I have lived with Laban as an alien, and stayed until now;', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 32, 5, 'and I have oxen, donkeys, flocks, male and female slaves; and I have sent to tell my lord, in order that I may find favor in your sight.""', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 32, 6, 'The messengers returned to Jacob, saying, "We came to your brother Esau, and he is coming to meet you, and four hundred men are with him."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 32, 7, 'Then Jacob was greatly afraid and distressed; and he divided the people that were with him, and the flocks and herds and camels, into two companies,', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 32, 8, 'thinking, "If Esau comes to the one company and destroys it, then the company that is left will escape."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 32, 9, 'And Jacob said, "O God of my father Abraham and God of my father Isaac, O LORD who said to me, "Return to your country and to your kindred, and I will do you good,"', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 32, 10, 'I am not worthy of the least of all the steadfast love and all the faithfulness that you have shown to your servant, for with only my staff I crossed this Jordan; and now I have become two companies.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 32, 11, 'Deliver me, please, from the hand of my brother, from the hand of Esau, for I am afraid of him; he may come and kill us all, the mothers with the children.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 32, 12, 'Yet you have said, "I will surely do you good, and make your offspring as the sand of the sea, which cannot be counted because of their number.""', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 32, 13, 'So he spent that night there, and from what he had with him he took a present for his brother Esau,', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 32, 14, 'two hundred female goats and twenty male goats, two hundred ewes and twenty rams,', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 32, 15, 'thirty milch camels and their colts, forty cows and ten bulls, twenty female donkeys and ten male donkeys.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 32, 16, 'These he delivered into the hand of his servants, every drove by itself, and said to his servants, "Pass on ahead of me, and put a space between drove and drove."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 32, 17, 'He instructed the foremost, "When Esau my brother meets you, and asks you, "To whom do you belong? Where are you going? And whose are these ahead of you?"', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 32, 18, 'then you shall say, "They belong to your servant Jacob; they are a present sent to my lord Esau; and moreover he is behind us.""', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 32, 19, 'He likewise instructed the second and the third and all who followed the droves, "You shall say the same thing to Esau when you meet him,', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 32, 20, 'and you shall say, "Moreover your servant Jacob is behind us."" For he thought, "I may appease him with the present that goes ahead of me, and afterwards I shall see his face; perhaps he will accept me."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 32, 21, 'So the present passed on ahead of him; and he himself spent that night in the camp.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 32, 22, 'The same night he got up and took his two wives, his two maids, and his eleven children, and crossed the ford of the Jabbok.', 'en', 'NRSV-CE', 'Jacob Wrestles at Peniel'),
(1, 'Kej', 'Genesis', 32, 23, 'He took them and sent them across the stream, and likewise everything that he had.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 32, 24, 'Jacob was left alone; and a man wrestled with him until daybreak.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 32, 25, 'When the man saw that he did not prevail against Jacob, he struck him on the hip socket; and Jacob"s hip was put out of joint as he wrestled with him.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 32, 26, 'Then he said, "Let me go, for the day is breaking." But Jacob said, "I will not let you go, unless you bless me."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 32, 27, 'So he said to him, "What is your name?" And he said, "Jacob."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 32, 28, 'Then the man said, "You shall no longer be called Jacob, but Israel, for you have striven with God and with humans, and have prevailed."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 32, 29, 'Then Jacob asked him, "Please tell me your name." But he said, "Why is it that you ask my name?" And there he blessed him.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 32, 30, 'So Jacob called the place Peniel, saying, "For I have seen God face to face, and yet my life is preserved."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 32, 31, 'The sun rose upon him as he passed Penuel, limping because of his hip.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 32, 32, 'Therefore to this day the Israelites do not eat the thigh muscle that is on the hip socket, because he struck Jacob on the hip socket at the thigh muscle.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(1, 'Kej', 'Genesis', 33, 1, 'Now Jacob looked up and saw Esau coming, and four hundred men with him. So he divided the children among Leah and Rachel and the two maids.', 'en', 'NRSV-CE', 'Jacob and Esau Meet'),
(1, 'Kej', 'Genesis', 33, 2, 'He put the maids with their children in front, then Leah with her children, and Rachel and Joseph last of all.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 33, 3, 'He himself went on ahead of them, bowing himself to the ground seven times, until he came near his brother.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 33, 4, 'But Esau ran to meet him, and embraced him, and fell on his neck and kissed him, and they wept.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 33, 5, 'When Esau looked up and saw the women and children, he said, "Who are these with you?" Jacob said, "The children whom God has graciously given your servant."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 33, 6, 'Then the maids drew near, they and their children, and bowed down;', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 33, 7, 'Leah likewise and her children drew near and bowed down; and finally Joseph and Rachel drew near, and they bowed down.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 33, 8, 'Esau said, "What do you mean by all this company that I met?" Jacob answered, "To find favor with my lord."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 33, 9, 'But Esau said, "I have enough, my brother; keep what you have for yourself."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 33, 10, 'Jacob said, "No, please; if I find favor with you, then accept my present from my hand; for truly to see your face is like seeing the face of God--since you have received me with such favor.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 33, 11, 'Please accept my gift that is brought to you, because God has dealt graciously with me, and because I have everything I want." So he urged him, and he took it.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 33, 12, 'Then Esau said, "Let us journey on our way, and I will go alongside you."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 33, 13, 'But Jacob said to him, "My lord knows that the children are frail and that the flocks and herds, which are nursing, are a care to me; and if they are overdriven for one day, all the flocks will die.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 33, 14, 'Let my lord pass on ahead of his servant, and I will lead on slowly, according to the pace of the cattle that are before me and according to the pace of the children, until I come to my lord in Seir."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 33, 15, 'So Esau said, "Let me leave with you some of the people who are with me." But he said, "Why should my lord be so kind to me?"', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 33, 16, 'So Esau returned that day on his way to Seir.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 33, 17, 'But Jacob journeyed to Succoth, and built himself a house, and made booths for his cattle; therefore the place is called Succoth.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 33, 18, 'Jacob came safely to the city of Shechem, which is in the land of Canaan, on his way from Paddan-aram; and he camped before the city.', 'en', 'NRSV-CE', 'Jacob Reaches Shechem'),
(1, 'Kej', 'Genesis', 33, 19, 'And from the sons of Hamor, Shechem"s father, he bought for one hundred pieces of money the plot of land on which he had pitched his tent.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 33, 20, 'There he erected an altar and called it El-Elohe-Israel.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(1, 'Kej', 'Genesis', 34, 1, 'Now Dinah the daughter of Leah, whom she had borne to Jacob, went out to visit the women of the region.', 'en', 'NRSV-CE', 'The Rape of Dinah'),
(1, 'Kej', 'Genesis', 34, 2, 'When Shechem son of Hamor the Hivite, prince of the region, saw her, he seized her and lay with her by force.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 34, 3, 'And his soul was drawn to Dinah daughter of Jacob; he loved the girl, and spoke tenderly to her.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 34, 4, 'So Shechem spoke to his father Hamor, saying, "Get me this girl to be my wife."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 34, 5, 'Now Jacob heard that Shechem had defiled his daughter Dinah; but his sons were with his cattle in the field, so Jacob held his peace until they came.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 34, 6, 'And Hamor the father of Shechem went out to Jacob to speak with him,', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 34, 7, 'just as the sons of Jacob came in from the field. When they heard of it, the men were indignant and very angry, because he had committed an outrage in Israel by lying with Jacob"s daughter, for such a thing ought not to be done.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 34, 8, 'But Hamor spoke with them, saying, "The heart of my son Shechem longs for your daughter; please give her to him in marriage.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 34, 9, 'Make marriages with us; give your daughters to us, and take our daughters for yourselves.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 34, 10, 'You shall live with us; and the land shall be open to you; live and trade in it, and get property in it."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 34, 11, 'Shechem also said to her father and to her brothers, "Let me find favor with you, and whatever you say to me I will give.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 34, 12, 'Put the marriage present and gift as high as you like, and I will give whatever you ask me; only give me the girl to be my wife."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 34, 13, 'The sons of Jacob answered Shechem and his father Hamor deceitfully, because he had defiled their sister Dinah.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 34, 14, 'They said to them, "We cannot do this thing, to give our sister to one who is uncircumcised, for that would be a disgrace to us.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 34, 15, 'Only on this condition will we consent to you: that you will become as we are and every male among you be circumcised.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 34, 16, 'Then we will give our daughters to you, and we will take your daughters for ourselves, and we will live among you and become one people.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 34, 17, 'But if you will not listen to us and be circumcised, then we will take our daughter and be gone."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 34, 18, 'Their words pleased Hamor and Hamor"s son Shechem.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 34, 19, 'And the young man did not delay to do the thing, because he was delighted with Jacob"s daughter. Now he was the most honored of all his family.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 34, 20, 'So Hamor and his son Shechem came to the gate of their city and spoke to the men of their city, saying,', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 34, 21, '"These people are friendly with us; let them live in the land and trade in it, for the land is large enough for them; let us take their daughters in marriage, and let us give them our daughters.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 34, 22, 'Only on this condition will they agree to live among us, to become one people: that every male among us be circumcised as they are circumcised.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 34, 23, 'Will not their livestock, their property, and all their animals be ours? Only let us agree with them, and they will live among us."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 34, 24, 'And all who went out of the city gate heeded Hamor and his son Shechem; and every male was circumcised, all who went out of the gate of his city.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 34, 25, 'On the third day, when they were still in pain, two of the sons of Jacob, Simeon and Levi, Dinah"s brothers, took their swords and came against the city unawares, and killed all the males.', 'en', 'NRSV-CE', 'Dinah"s Brothers Avenge Their Sister'),
(1, 'Kej', 'Genesis', 34, 26, 'They killed Hamor and his son Shechem with the sword, and took Dinah out of Shechem"s house, and went away.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 34, 27, 'And the other sons of Jacob came upon the slain, and plundered the city, because their sister had been defiled.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 34, 28, 'They took their flocks and their herds, their donkeys, and whatever was in the city and in the field.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 34, 29, 'All their wealth, all their little ones and their wives, all that was in the houses, they captured and made their prey.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 34, 30, 'Then Jacob said to Simeon and Levi, "You have brought trouble on me by making me odious to the inhabitants of the land, the Canaanites and the Perizzites; my numbers are few, and if they gather themselves against me and attack me, I shall be destroyed, both I and my household."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 34, 31, 'But they said, "Should our sister be treated like a whore?"', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(1, 'Kej', 'Genesis', 35, 1, 'God said to Jacob, "Arise, go up to Bethel, and settle there. Make an altar there to the God who appeared to you when you fled from your brother Esau."', 'en', 'NRSV-CE', 'Jacob Returns to Bethel'),
(1, 'Kej', 'Genesis', 35, 2, 'So Jacob said to his household and to all who were with him, "Put away the foreign gods that are among you, and purify yourselves, and change your clothes;', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 35, 3, 'then come, let us go up to Bethel, that I may make an altar there to the God who answered me in the day of my distress and has been with me wherever I have gone."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 35, 4, 'So they gave to Jacob all the foreign gods that they had, and the rings that were in their ears; and Jacob hid them under the oak that was near Shechem.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 35, 5, 'As they journeyed, a terror from God fell upon the cities all around them, so that no one pursued them.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 35, 6, 'Jacob came to Luz (that is, Bethel), which is in the land of Canaan, he and all the people who were with him,', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 35, 7, 'and there he built an altar and called the place El-bethel, because it was there that God had revealed himself to him when he fled from his brother.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 35, 8, 'And Deborah, Rebekah"s nurse, died, and she was buried under an oak below Bethel. So it was called Allon-bacuth.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 35, 9, 'God appeared to Jacob again when he came from Paddan-aram, and he blessed him.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 35, 10, 'God said to him, "Your name is Jacob; no longer shall you be called Jacob, but Israel shall be your name." So he was called Israel.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 35, 11, 'God said to him, "I am God Almighty: be fruitful and multiply; a nation and a company of nations shall come from you, and kings shall spring from you.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 35, 12, 'The land that I gave to Abraham and Isaac I will give to you, and I will give the land to your offspring after you."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 35, 13, 'Then God went up from him at the place where he had spoken with him.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 35, 14, 'Jacob set up a pillar in the place where he had spoken with him, a pillar of stone; and he poured out a drink offering on it, and poured oil on it.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 35, 15, 'So Jacob called the place where God had spoken with him Bethel.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 35, 16, 'Then they journeyed from Bethel; and when they were still some distance from Ephrath, Rachel was in childbirth, and she had hard labor.', 'en', 'NRSV-CE', 'The Birth of Benjamin and the Death of Rachel'),
(1, 'Kej', 'Genesis', 35, 17, 'When she was in her hard labor, the midwife said to her, "Do not be afraid; for now you will have another son."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 35, 18, 'As her soul was departing (for she died), she named him Ben-oni; but his father called him Benjamin.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 35, 19, 'So Rachel died, and she was buried on the way to Ephrath (that is, Bethlehem),', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 35, 20, 'and Jacob set up a pillar at her grave; it is the pillar of Rachel"s tomb, which is there to this day.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 35, 21, 'Israel journeyed on, and pitched his tent beyond the tower of Eder.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 35, 22, 'While Israel lived in that land, Reuben went and lay with Bilhah his father"s concubine; and Israel heard of it.
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(1, 'Kej', 'Genesis', 36, 1, 'These are the descendants of Esau (that is, Edom).', 'en', 'NRSV-CE', 'Esau"s Descendants'),
(1, 'Kej', 'Genesis', 36, 2, 'Esau took his wives from the Canaanites: Adah daughter of Elon the Hittite, Oholibamah daughter of Anah son of Zibeon the Hivite,', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 36, 3, 'and Basemath, Ishmael"s daughter, sister of Nebaioth.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 36, 4, 'Adah bore Eliphaz to Esau; Basemath bore Reuel;', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 36, 5, 'and Oholibamah bore Jeush, Jalam, and Korah. These are the sons of Esau who were born to him in the land of Canaan.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 36, 6, 'Then Esau took his wives, his sons, his daughters, and all the members of his household, his cattle, all his livestock, and all the property he had acquired in the land of Canaan; and he moved to a land some distance from his brother Jacob.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 36, 7, 'For their possessions were too great for them to live together; the land where they were staying could not support them because of their livestock.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 36, 8, 'So Esau settled in the hill country of Seir; Esau is Edom.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 36, 9, 'These are the descendants of Esau, ancestor of the Edomites, in the hill country of Seir.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 36, 10, 'These are the names of Esau"s sons: Eliphaz son of Adah the wife of Esau; Reuel, the son of Esau"s wife Basemath.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 36, 11, 'The sons of Eliphaz were Teman, Omar, Zepho, Gatam, and Kenaz.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 36, 12, '(Timna was a concubine of Eliphaz, Esau"s son; she bore Amalek to Eliphaz.) These were the sons of Adah, Esau"s wife.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 36, 13, 'These were the sons of Reuel: Nahath, Zerah, Shammah, and Mizzah. These were the sons of Esau"s wife, Basemath.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 36, 14, 'These were the sons of Esau"s wife Oholibamah, daughter of Anah son of Zibeon: she bore to Esau Jeush, Jalam, and Korah.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 36, 15, 'These are the clans of the sons of Esau. The sons of Eliphaz the firstborn of Esau: the clans Teman, Omar, Zepho, Kenaz,', 'en', 'NRSV-CE', 'Clans and Kings of Edom'),
(1, 'Kej', 'Genesis', 36, 16, 'Korah, Gatam, and Amalek; these are the clans of Eliphaz in the land of Edom; they are the sons of Adah.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 36, 17, 'These are the sons of Esau"s son Reuel: the clans Nahath, Zerah, Shammah, and Mizzah; these are the clans of Reuel in the land of Edom; they are the sons of Esau"s wife Basemath.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 36, 18, 'These are the sons of Esau"s wife Oholibamah: the clans Jeush, Jalam, and Korah; these are the clans born of Esau"s wife Oholibamah, the daughter of Anah.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 36, 19, 'These are the sons of Esau (that is, Edom), and these are their clans.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 36, 20, 'These are the sons of Seir the Horite, the inhabitants of the land: Lotan, Shobal, Zibeon, Anah,', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 36, 21, 'Dishon, Ezer, and Dishan; these are the clans of the Horites, the sons of Seir in the land of Edom.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 36, 22, 'The sons of Lotan were Hori and Heman; and Lotan"s sister was Timna.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 36, 23, 'These are the sons of Shobal: Alvan, Manahath, Ebal, Shepho, and Onam.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 36, 24, 'These are the sons of Zibeon: Aiah and Anah; he is the Anah who found the springs in the wilderness, as he pastured the donkeys of his father Zibeon.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 36, 25, 'These are the children of Anah: Dishon and Oholibamah daughter of Anah.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 36, 26, 'These are the sons of Dishon: Hemdan, Eshban, Ithran, and Cheran.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 36, 27, 'These are the sons of Ezer: Bilhan, Zaavan, and Akan.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 36, 28, 'These are the sons of Dishan: Uz and Aran.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 36, 29, 'These are the clans of the Horites: the clans Lotan, Shobal, Zibeon, Anah,', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 36, 30, 'Dishon, Ezer, and Dishan; these are the clans of the Horites, clan by clan in the land of Seir.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 36, 31, 'These are the kings who reigned in the land of Edom, before any king reigned over the Israelites.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 36, 32, 'Bela son of Beor reigned in Edom, the name of his city being Dinhabah.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 36, 33, 'Bela died, and Jobab son of Zerah of Bozrah succeeded him as king.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 36, 34, 'Jobab died, and Husham of the land of the Temanites succeeded him as king.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 36, 35, 'Husham died, and Hadad son of Bedad, who defeated Midian in the country of Moab, succeeded him as king, the name of his city being Avith.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 36, 36, 'Hadad died, and Samlah of Masrekah succeeded him as king.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 36, 37, 'Samlah died, and Shaul of Rehoboth on the Euphrates succeeded him as king.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 36, 38, 'Shaul died, and Baal-hanan son of Achbor succeeded him as king.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 36, 39, 'Baal-hanan son of Achbor died, and Hadar succeeded him as king, the name of his city being Pau; his wife"s name was Mehetabel, the daughter of Matred, daughter of Me-zahab.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 36, 40, 'These are the names of the clans of Esau, according to their families and their localities by their names: the clans Timna, Alvah, Jetheth,', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 36, 41, 'Oholibamah, Elah, Pinon,', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 36, 42, 'Kenaz, Teman, Mibzar,', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 36, 43, 'Magdiel, and Iram; these are the clans of Edom (that is, Esau, the father of Edom), according to their settlements in the land that they held.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(1, 'Kej', 'Genesis', 37, 1, 'Jacob settled in the land where his father had lived as an alien, the land of Canaan.', 'en', 'NRSV-CE', 'Joseph Dreams of Greatness'),
(1, 'Kej', 'Genesis', 37, 2, 'This is the story of the family of Jacob.
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(1, 'Kej', 'Genesis', 38, 1, 'It happened at that time that Judah went down from his brothers and settled near a certain Adullamite whose name was Hirah.', 'en', 'NRSV-CE', 'Judah and Tamar'),
(1, 'Kej', 'Genesis', 38, 2, 'There Judah saw the daughter of a certain Canaanite whose name was Shua; he married her and went in to her.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 38, 3, 'She conceived and bore a son; and he named him Er.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 38, 4, 'Again she conceived and bore a son whom she named Onan.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 38, 5, 'Yet again she bore a son, and she named him Shelah. She was in Chezib when she bore him.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 38, 6, 'Judah took a wife for Er his firstborn; her name was Tamar.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 38, 7, 'But Er, Judah"s firstborn, was wicked in the sight of the LORD, and the LORD put him to death.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 38, 8, 'Then Judah said to Onan, "Go in to your brother"s wife and perform the duty of a brother-in-law to her; raise up offspring for your brother."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 38, 9, 'But since Onan knew that the offspring would not be his, he spilled his semen on the ground whenever he went in to his brother"s wife, so that he would not give offspring to his brother.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 38, 10, 'What he did was displeasing in the sight of the LORD, and he put him to death also.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 38, 11, 'Then Judah said to his daughter-in-law Tamar, "Remain a widow in your father"s house until my son Shelah grows up"--for he feared that he too would die, like his brothers. So Tamar went to live in her father"s house.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 38, 12, 'In course of time the wife of Judah, Shua"s daughter, died; when Judah"s time of mourning was over, he went up to Timnah to his sheepshearers, he and his friend Hirah the Adullamite.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 38, 13, 'When Tamar was told, "Your father-in-law is going up to Timnah to shear his sheep,"', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 38, 14, 'she put off her widow"s garments, put on a veil, wrapped herself up, and sat down at the entrance to Enaim, which is on the road to Timnah. She saw that Shelah was grown up, yet she had not been given to him in marriage.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 38, 15, 'When Judah saw her, he thought her to be a prostitute, for she had covered her face.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 38, 16, 'He went over to her at the roadside, and said, "Come, let me come in to you," for he did not know that she was his daughter-in-law. She said, "What will you give me, that you may come in to me?"', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 38, 17, 'He answered, "I will send you a kid from the flock." And she said, "Only if you give me a pledge, until you send it."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 38, 18, 'He said, "What pledge shall I give you?" She replied, "Your signet and your cord, and the staff that is in your hand." So he gave them to her, and went in to her, and she conceived by him.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 38, 19, 'Then she got up and went away, and taking off her veil she put on the garments of her widowhood.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 38, 20, 'When Judah sent the kid by his friend the Adullamite, to recover the pledge from the woman, he could not find her.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 38, 21, 'He asked the townspeople, "Where is the temple prostitute who was at Enaim by the wayside?" But they said, "No prostitute has been here."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 38, 22, 'So he returned to Judah, and said, "I have not found her; moreover the townspeople said, "No prostitute has been here.""', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 38, 23, 'Judah replied, "Let her keep the things as her own, otherwise we will be laughed at; you see, I sent this kid, and you could not find her."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 38, 24, 'About three months later Judah was told, "Your daughter-in-law Tamar has played the whore; moreover she is pregnant as a result of whoredom." And Judah said, "Bring her out, and let her be burned."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 38, 25, 'As she was being brought out, she sent word to her father-in-law, "It was the owner of these who made me pregnant." And she said, "Take note, please, whose these are, the signet and the cord and the staff."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 38, 26, 'Then Judah acknowledged them and said, "She is more in the right than I, since I did not give her to my son Shelah." And he did not lie with her again.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 38, 27, 'When the time of her delivery came, there were twins in her womb.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 38, 28, 'While she was in labor, one put out a hand; and the midwife took and bound on his hand a crimson thread, saying, "This one came out first."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 38, 29, 'But just then he drew back his hand, and out came his brother; and she said, "What a breach you have made for yourself!" Therefore he was named Perez.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 38, 30, 'Afterward his brother came out with the crimson thread on his hand; and he was named Zerah.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(1, 'Kej', 'Genesis', 39, 1, 'Now Joseph was taken down to Egypt, and Potiphar, an officer of Pharaoh, the captain of the guard, an Egyptian, bought him from the Ishmaelites who had brought him down there.', 'en', 'NRSV-CE', 'Joseph and Potiphar"s Wife'),
(1, 'Kej', 'Genesis', 39, 2, 'The LORD was with Joseph, and he became a successful man; he was in the house of his Egyptian master.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 39, 3, 'His master saw that the LORD was with him, and that the LORD caused all that he did to prosper in his hands.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 39, 4, 'So Joseph found favor in his sight and attended him; he made him overseer of his house and put him in charge of all that he had.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 39, 5, 'From the time that he made him overseer in his house and over all that he had, the LORD blessed the Egyptian"s house for Joseph"s sake; the blessing of the LORD was on all that he had, in house and field.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 39, 6, 'So he left all that he had in Joseph"s charge; and, with him there, he had no concern for anything but the food that he ate.
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(1, 'Kej', 'Genesis', 40, 1, 'Some time after this, the cupbearer of the king of Egypt and his baker offended their lord the king of Egypt.', 'en', 'NRSV-CE', 'The Dreams of Two Prisoners'),
(1, 'Kej', 'Genesis', 40, 2, 'Pharaoh was angry with his two officers, the chief cupbearer and the chief baker,', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 40, 3, 'and he put them in custody in the house of the captain of the guard, in the prison where Joseph was confined.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 40, 4, 'The captain of the guard charged Joseph with them, and he waited on them; and they continued for some time in custody.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 40, 5, 'One night they both dreamed--the cupbearer and the baker of the king of Egypt, who were confined in the prison--each his own dream, and each dream with its own meaning.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 40, 6, 'When Joseph came to them in the morning, he saw that they were troubled.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 40, 7, 'So he asked Pharaoh"s officers, who were with him in custody in his master"s house, "Why are your faces downcast today?"', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 40, 8, 'They said to him, "We have had dreams, and there is no one to interpret them." And Joseph said to them, "Do not interpretations belong to God? Please tell them to me."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 40, 9, 'So the chief cupbearer told his dream to Joseph, and said to him, "In my dream there was a vine before me,', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 40, 10, 'and on the vine there were three branches. As soon as it budded, its blossoms came out and the clusters ripened into grapes.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 40, 11, 'Pharaoh"s cup was in my hand; and I took the grapes and pressed them into Pharaoh"s cup, and placed the cup in Pharaoh"s hand."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 40, 12, 'Then Joseph said to him, "This is its interpretation: the three branches are three days;', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 40, 13, 'within three days Pharaoh will lift up your head and restore you to your office; and you shall place Pharaoh"s cup in his hand, just as you used to do when you were his cupbearer.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 40, 14, 'But remember me when it is well with you; please do me the kindness to make mention of me to Pharaoh, and so get me out of this place.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 40, 15, 'For in fact I was stolen out of the land of the Hebrews; and here also I have done nothing that they should have put me into the dungeon."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 40, 16, 'When the chief baker saw that the interpretation was favorable, he said to Joseph, "I also had a dream: there were three cake baskets on my head,', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 40, 17, 'and in the uppermost basket there were all sorts of baked food for Pharaoh, but the birds were eating it out of the basket on my head."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 40, 18, 'And Joseph answered, "This is its interpretation: the three baskets are three days;', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 40, 19, 'within three days Pharaoh will lift up your head--from you!--and hang you on a pole; and the birds will eat the flesh from you."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 40, 20, 'On the third day, which was Pharaoh"s birthday, he made a feast for all his servants, and lifted up the head of the chief cupbearer and the head of the chief baker among his servants.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 40, 21, 'He restored the chief cupbearer to his cupbearing, and he placed the cup in Pharaoh"s hand;', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 40, 22, 'but the chief baker he hanged, just as Joseph had interpreted to them.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 40, 23, 'Yet the chief cupbearer did not remember Joseph, but forgot him.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(1, 'Kej', 'Genesis', 41, 1, 'After two whole years, Pharaoh dreamed that he was standing by the Nile,', 'en', 'NRSV-CE', 'Joseph Interprets Pharaoh"s Dream'),
(1, 'Kej', 'Genesis', 41, 2, 'and there came up out of the Nile seven sleek and fat cows, and they grazed in the reed grass.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 41, 3, 'Then seven other cows, ugly and thin, came up out of the Nile after them, and stood by the other cows on the bank of the Nile.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 41, 4, 'The ugly and thin cows ate up the seven sleek and fat cows. And Pharaoh awoke.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 41, 5, 'Then he fell asleep and dreamed a second time; seven ears of grain, plump and good, were growing on one stalk.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 41, 6, 'Then seven ears, thin and blighted by the east wind, sprouted after them.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 41, 7, 'The thin ears swallowed up the seven plump and full ears. Pharaoh awoke, and it was a dream.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 41, 8, 'In the morning his spirit was troubled; so he sent and called for all the magicians of Egypt and all its wise men. Pharaoh told them his dreams, but there was no one who could interpret them to Pharaoh.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 41, 9, 'Then the chief cupbearer said to Pharaoh, "I remember my faults today.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 41, 10, 'Once Pharaoh was angry with his servants, and put me and the chief baker in custody in the house of the captain of the guard.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 41, 11, 'We dreamed on the same night, he and I, each having a dream with its own meaning.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 41, 12, 'A young Hebrew was there with us, a servant of the captain of the guard. When we told him, he interpreted our dreams to us, giving an interpretation to each according to his dream.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 41, 13, 'As he interpreted to us, so it turned out; I was restored to my office, and the baker was hanged."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 41, 14, 'Then Pharaoh sent for Joseph, and he was hurriedly brought out of the dungeon. When he had shaved himself and changed his clothes, he came in before Pharaoh.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 41, 15, 'And Pharaoh said to Joseph, "I have had a dream, and there is no one who can interpret it. I have heard it said of you that when you hear a dream you can interpret it."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 41, 16, 'Joseph answered Pharaoh, "It is not I; God will give Pharaoh a favorable answer."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 41, 17, 'Then Pharaoh said to Joseph, "In my dream I was standing on the banks of the Nile;', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 41, 18, 'and seven cows, fat and sleek, came up out of the Nile and fed in the reed grass.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 41, 19, 'Then seven other cows came up after them, poor, very ugly, and thin. Never had I seen such ugly ones in all the land of Egypt.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 41, 20, 'The thin and ugly cows ate up the first seven fat cows,', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 41, 21, 'but when they had eaten them no one would have known that they had done so, for they were still as ugly as before. Then I awoke.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 41, 22, 'I fell asleep a second time and I saw in my dream seven ears of grain, full and good, growing on one stalk,', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 41, 23, 'and seven ears, withered, thin, and blighted by the east wind, sprouting after them;', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 41, 24, 'and the thin ears swallowed up the seven good ears. But when I told it to the magicians, there was no one who could explain it to me."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 41, 25, 'Then Joseph said to Pharaoh, "Pharaoh"s dreams are one and the same; God has revealed to Pharaoh what he is about to do.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 41, 26, 'The seven good cows are seven years, and the seven good ears are seven years; the dreams are one.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 41, 27, 'The seven lean and ugly cows that came up after them are seven years, as are the seven empty ears blighted by the east wind. They are seven years of famine.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 41, 28, 'It is as I told Pharaoh; God has shown to Pharaoh what he is about to do.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 41, 29, 'There will come seven years of great plenty throughout all the land of Egypt.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 41, 30, 'After them there will arise seven years of famine, and all the plenty will be forgotten in the land of Egypt; the famine will consume the land.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 41, 31, 'The plenty will no longer be known in the land because of the famine that will follow, for it will be very grievous.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 41, 32, 'And the doubling of Pharaoh"s dream means that the thing is fixed by God, and God will shortly bring it about.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 41, 33, 'Now therefore let Pharaoh select a man who is discerning and wise, and set him over the land of Egypt.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 41, 34, 'Let Pharaoh proceed to appoint overseers over the land, and take one-fifth of the produce of the land of Egypt during the seven plenteous years.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 41, 35, 'Let them gather all the food of these good years that are coming, and lay up grain under the authority of Pharaoh for food in the cities, and let them keep it.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 41, 36, 'That food shall be a reserve for the land against the seven years of famine that are to befall the land of Egypt, so that the land may not perish through the famine."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 41, 37, 'The proposal pleased Pharaoh and all his servants.', 'en', 'NRSV-CE', 'Joseph"s Rise to Power'),
(1, 'Kej', 'Genesis', 41, 38, 'Pharaoh said to his servants, "Can we find anyone else like this--one in whom is the spirit of God?"', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 41, 39, 'So Pharaoh said to Joseph, "Since God has shown you all this, there is no one so discerning and wise as you.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 41, 40, 'You shall be over my house, and all my people shall order themselves as you command; only with regard to the throne will I be greater than you."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 41, 41, 'And Pharaoh said to Joseph, "See, I have set you over all the land of Egypt."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 41, 42, 'Removing his signet ring from his hand, Pharaoh put it on Joseph"s hand; he arrayed him in garments of fine linen, and put a gold chain around his neck.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 41, 43, 'He had him ride in the chariot of his second-in-command; and they cried out in front of him, "Bow the knee!" Thus he set him over all the land of Egypt.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 41, 44, 'Moreover Pharaoh said to Joseph, "I am Pharaoh, and without your consent no one shall lift up hand or foot in all the land of Egypt."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 41, 45, 'Pharaoh gave Joseph the name Zaphenath-paneah; and he gave him Asenath daughter of Potiphera, priest of On, as his wife. Thus Joseph gained authority over the land of Egypt.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 41, 46, 'Joseph was thirty years old when he entered the service of Pharaoh king of Egypt. And Joseph went out from the presence of Pharaoh, and went through all the land of Egypt.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 41, 47, 'During the seven plenteous years the earth produced abundantly.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 41, 48, 'He gathered up all the food of the seven years when there was plenty in the land of Egypt, and stored up food in the cities; he stored up in every city the food from the fields around it.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 41, 49, 'So Joseph stored up grain in such abundance--like the sand of the sea--that he stopped measuring it; it was beyond measure.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 41, 50, 'Before the years of famine came, Joseph had two sons, whom Asenath daughter of Potiphera, priest of On, bore to him.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 41, 51, 'Joseph named the firstborn Manasseh, "For," he said, "God has made me forget all my hardship and all my father"s house."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 41, 52, 'The second he named Ephraim, "For God has made me fruitful in the land of my misfortunes."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 41, 53, 'The seven years of plenty that prevailed in the land of Egypt came to an end;', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 41, 54, 'and the seven years of famine began to come, just as Joseph had said. There was famine in every country, but throughout the land of Egypt there was bread.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 41, 55, 'When all the land of Egypt was famished, the people cried to Pharaoh for bread. Pharaoh said to all the Egyptians, "Go to Joseph; what he says to you, do."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 41, 56, 'And since the famine had spread over all the land, Joseph opened all the storehouses, and sold to the Egyptians, for the famine was severe in the land of Egypt.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 41, 57, 'Moreover, all the world came to Joseph in Egypt to buy grain, because the famine became severe throughout the world.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(1, 'Kej', 'Genesis', 42, 1, 'When Jacob learned that there was grain in Egypt, he said to his sons, "Why do you keep looking at one another?', 'en', 'NRSV-CE', 'Joseph"s Brothers Go to Egypt'),
(1, 'Kej', 'Genesis', 42, 2, 'I have heard," he said, "that there is grain in Egypt; go down and buy grain for us there, that we may live and not die."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 42, 3, 'So ten of Joseph"s brothers went down to buy grain in Egypt.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 42, 4, 'But Jacob did not send Joseph"s brother Benjamin with his brothers, for he feared that harm might come to him.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 42, 5, 'Thus the sons of Israel were among the other people who came to buy grain, for the famine had reached the land of Canaan.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 42, 6, 'Now Joseph was governor over the land; it was he who sold to all the people of the land. And Joseph"s brothers came and bowed themselves before him with their faces to the ground.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 42, 7, 'When Joseph saw his brothers, he recognized them, but he treated them like strangers and spoke harshly to them. "Where do you come from?" he said. They said, "From the land of Canaan, to buy food."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 42, 8, 'Although Joseph had recognized his brothers, they did not recognize him.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 42, 9, 'Joseph also remembered the dreams that he had dreamed about them. He said to them, "You are spies; you have come to see the nakedness of the land!"', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 42, 10, 'They said to him, "No, my lord; your servants have come to buy food.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 42, 11, 'We are all sons of one man; we are honest men; your servants have never been spies."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 42, 12, 'But he said to them, "No, you have come to see the nakedness of the land!"', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 42, 13, 'They said, "We, your servants, are twelve brothers, the sons of a certain man in the land of Canaan; the youngest, however, is now with our father, and one is no more."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 42, 14, 'But Joseph said to them, "It is just as I have said to you; you are spies!', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 42, 15, 'Here is how you shall be tested: as Pharaoh lives, you shall not leave this place unless your youngest brother comes here!', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 42, 16, 'Let one of you go and bring your brother, while the rest of you remain in prison, in order that your words may be tested, whether there is truth in you; or else, as Pharaoh lives, surely you are spies."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 42, 17, 'And he put them all together in prison for three days.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 42, 18, 'On the third day Joseph said to them, "Do this and you will live, for I fear God:', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 42, 19, 'if you are honest men, let one of your brothers stay here where you are imprisoned. The rest of you shall go and carry grain for the famine of your households,', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 42, 20, 'and bring your youngest brother to me. Thus your words will be verified, and you shall not die." And they agreed to do so.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 42, 21, 'They said to one another, "Alas, we are paying the penalty for what we did to our brother; we saw his anguish when he pleaded with us, but we would not listen. That is why this anguish has come upon us."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 42, 22, 'Then Reuben answered them, "Did I not tell you not to wrong the boy? But you would not listen. So now there comes a reckoning for his blood."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 42, 23, 'They did not know that Joseph understood them, since he spoke with them through an interpreter.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 42, 24, 'He turned away from them and wept; then he returned and spoke to them. And he picked out Simeon and had him bound before their eyes.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 42, 25, 'Joseph then gave orders to fill their bags with grain, to return every man"s money to his sack, and to give them provisions for their journey. This was done for them.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 42, 26, 'They loaded their donkeys with their grain, and departed.', 'en', 'NRSV-CE', 'Joseph"s Brothers Return to Canaan'),
(1, 'Kej', 'Genesis', 42, 27, 'When one of them opened his sack to give his donkey fodder at the lodging place, he saw his money at the top of the sack.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 42, 28, 'He said to his brothers, "My money has been put back; here it is in my sack!" At this they lost heart and turned trembling to one another, saying, "What is this that God has done to us?"', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 42, 29, 'When they came to their father Jacob in the land of Canaan, they told him all that had happened to them, saying,', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 42, 30, '"The man, the lord of the land, spoke harshly to us, and charged us with spying on the land.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 42, 31, 'But we said to him, "We are honest men, we are not spies.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 42, 32, 'We are twelve brothers, sons of our father; one is no more, and the youngest is now with our father in the land of Canaan."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 42, 33, 'Then the man, the lord of the land, said to us, "By this I shall know that you are honest men: leave one of your brothers with me, take grain for the famine of your households, and go your way.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 42, 34, 'Bring your youngest brother to me, and I shall know that you are not spies but honest men. Then I will release your brother to you, and you may trade in the land.""', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 42, 35, 'As they were emptying their sacks, there in each one"s sack was his bag of money. When they and their father saw their bundles of money, they were dismayed.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 42, 36, 'And their father Jacob said to them, "I am the one you have bereaved of children: Joseph is no more, and Simeon is no more, and now you would take Benjamin. All this has happened to me!"', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 42, 37, 'Then Reuben said to his father, "You may kill my two sons if I do not bring him back to you. Put him in my hands, and I will bring him back to you."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 42, 38, 'But he said, "My son shall not go down with you, for his brother is dead, and he alone is left. If harm should come to him on the journey that you are to make, you would bring down my gray hairs with sorrow to Sheol."', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(1, 'Kej', 'Genesis', 43, 1, 'Now the famine was severe in the land.', 'en', 'NRSV-CE', 'The Brothers Come Again, Bringing Benjamin'),
(1, 'Kej', 'Genesis', 43, 2, 'And when they had eaten up the grain that they had brought from Egypt, their father said to them, "Go again, buy us a little more food."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 43, 3, 'But Judah said to him, "The man solemnly warned us, saying, "You shall not see my face unless your brother is with you."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 43, 4, 'If you will send our brother with us, we will go down and buy you food;', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 43, 5, 'but if you will not send him, we will not go down, for the man said to us, "You shall not see my face, unless your brother is with you.""', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 43, 6, 'Israel said, "Why did you treat me so badly as to tell the man that you had another brother?"', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 43, 7, 'They replied, "The man questioned us carefully about ourselves and our kindred, saying, "Is your father still alive? Have you another brother?" What we told him was in answer to these questions. Could we in any way know that he would say, "Bring your brother down"?"', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 43, 8, 'Then Judah said to his father Israel, "Send the boy with me, and let us be on our way, so that we may live and not die--you and we and also our little ones.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 43, 9, 'I myself will be surety for him; you can hold me accountable for him. If I do not bring him back to you and set him before you, then let me bear the blame forever.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 43, 10, 'If we had not delayed, we would now have returned twice."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 43, 11, 'Then their father Israel said to them, "If it must be so, then do this: take some of the choice fruits of the land in your bags, and carry them down as a present to the man--a little balm and a little honey, gum, resin, pistachio nuts, and almonds.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 43, 12, 'Take double the money with you. Carry back with you the money that was returned in the top of your sacks; perhaps it was an oversight.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 43, 13, 'Take your brother also, and be on your way again to the man;', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 43, 14, 'may God Almighty grant you mercy before the man, so that he may send back your other brother and Benjamin. As for me, if I am bereaved of my children, I am bereaved."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 43, 15, 'So the men took the present, and they took double the money with them, as well as Benjamin. Then they went on their way down to Egypt, and stood before Joseph.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 43, 16, 'When Joseph saw Benjamin with them, he said to the steward of his house, "Bring the men into the house, and slaughter an animal and make ready, for the men are to dine with me at noon."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 43, 17, 'The man did as Joseph said, and brought the men to Joseph"s house.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 43, 18, 'Now the men were afraid because they were brought to Joseph"s house, and they said, "It is because of the money, replaced in our sacks the first time, that we have been brought in, so that he may have an opportunity to fall upon us, to make slaves of us and take our donkeys."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 43, 19, 'So they went up to the steward of Joseph"s house and spoke with him at the entrance to the house.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 43, 20, 'They said, "Oh, my lord, we came down the first time to buy food;', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 43, 21, 'and when we came to the lodging place we opened our sacks, and there was each one"s money in the top of his sack, our money in full weight. So we have brought it back with us.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 43, 22, 'Moreover we have brought down with us additional money to buy food. We do not know who put our money in our sacks."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 43, 23, 'He replied, "Rest assured, do not be afraid; your God and the God of your father must have put treasure in your sacks for you; I received your money." Then he brought Simeon out to them.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 43, 24, 'When the steward had brought the men into Joseph"s house, and given them water, and they had washed their feet, and when he had given their donkeys fodder,', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 43, 25, 'they made the present ready for Joseph"s coming at noon, for they had heard that they would dine there.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 43, 26, 'When Joseph came home, they brought him the present that they had carried into the house, and bowed to the ground before him.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 43, 27, 'He inquired about their welfare, and said, "Is your father well, the old man of whom you spoke? Is he still alive?"', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 43, 28, 'They said, "Your servant our father is well; he is still alive." And they bowed their heads and did obeisance.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 43, 29, 'Then he looked up and saw his brother Benjamin, his mother"s son, and said, "Is this your youngest brother, of whom you spoke to me? God be gracious to you, my son!"', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 43, 30, 'With that, Joseph hurried out, because he was overcome with affection for his brother, and he was about to weep. So he went into a private room and wept there.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 43, 31, 'Then he washed his face and came out; and controlling himself he said, "Serve the meal."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 43, 32, 'They served him by himself, and them by themselves, and the Egyptians who ate with him by themselves, because the Egyptians could not eat with the Hebrews, for that is an abomination to the Egyptians.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 43, 33, 'When they were seated before him, the firstborn according to his birthright and the youngest according to his youth, the men looked at one another in amazement.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 43, 34, 'Portions were taken to them from Joseph"s table, but Benjamin"s portion was five times as much as any of theirs. So they drank and were merry with him.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(1, 'Kej', 'Genesis', 44, 1, 'Then he commanded the steward of his house, "Fill the men"s sacks with food, as much as they can carry, and put each man"s money in the top of his sack.', 'en', 'NRSV-CE', 'Joseph Detains Benjamin'),
(1, 'Kej', 'Genesis', 44, 2, 'Put my cup, the silver cup, in the top of the sack of the youngest, with his money for the grain." And he did as Joseph told him.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 44, 3, 'As soon as the morning was light, the men were sent away with their donkeys.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 44, 4, 'When they had gone only a short distance from the city, Joseph said to his steward, "Go, follow after the men; and when you overtake them, say to them, "Why have you returned evil for good? Why have you stolen my silver cup?', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 44, 5, 'Is it not from this that my lord drinks? Does he not indeed use it for divination? You have done wrong in doing this.""', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 44, 6, 'When he overtook them, he repeated these words to them.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 44, 7, 'They said to him, "Why does my lord speak such words as these? Far be it from your servants that they should do such a thing!', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 44, 8, 'Look, the money that we found at the top of our sacks, we brought back to you from the land of Canaan; why then would we steal silver or gold from your lord"s house?', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 44, 9, 'Should it be found with any one of your servants, let him die; moreover the rest of us will become my lord"s slaves."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 44, 10, 'He said, "Even so; in accordance with your words, let it be: he with whom it is found shall become my slave, but the rest of you shall go free."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 44, 11, 'Then each one quickly lowered his sack to the ground, and each opened his sack.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 44, 12, 'He searched, beginning with the eldest and ending with the youngest; and the cup was found in Benjamin"s sack.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 44, 13, 'At this they tore their clothes. Then each one loaded his donkey, and they returned to the city.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 44, 14, 'Judah and his brothers came to Joseph"s house while he was still there; and they fell to the ground before him.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 44, 15, 'Joseph said to them, "What deed is this that you have done? Do you not know that one such as I can practice divination?"', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 44, 16, 'And Judah said, "What can we say to my lord? What can we speak? How can we clear ourselves? God has found out the guilt of your servants; here we are then, my lord"s slaves, both we and also the one in whose possession the cup has been found."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 44, 17, 'But he said, "Far be it from me that I should do so! Only the one in whose possession the cup was found shall be my slave; but as for you, go up in peace to your father."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 44, 18, 'Then Judah stepped up to him and said, "O my lord, let your servant please speak a word in my lord"s ears, and do not be angry with your servant; for you are like Pharaoh himself.', 'en', 'NRSV-CE', 'Judah Pleads for Benjamin"s Release'),
(1, 'Kej', 'Genesis', 44, 19, 'My lord asked his servants, saying, "Have you a father or a brother?"', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 44, 20, 'And we said to my lord, "We have a father, an old man, and a young brother, the child of his old age. His brother is dead; he alone is left of his mother"s children, and his father loves him."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 44, 21, 'Then you said to your servants, "Bring him down to me, so that I may set my eyes on him."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 44, 22, 'We said to my lord, "The boy cannot leave his father, for if he should leave his father, his father would die."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 44, 23, 'Then you said to your servants, "Unless your youngest brother comes down with you, you shall see my face no more."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 44, 24, 'When we went back to your servant my father we told him the words of my lord.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 44, 25, 'And when our father said, "Go again, buy us a little food,"', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 44, 26, 'we said, "We cannot go down. Only if our youngest brother goes with us, will we go down; for we cannot see the man"s face unless our youngest brother is with us."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 44, 27, 'Then your servant my father said to us, "You know that my wife bore me two sons;', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 44, 28, 'one left me, and I said, Surely he has been torn to pieces; and I have never seen him since.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 44, 29, 'If you take this one also from me, and harm comes to him, you will bring down my gray hairs in sorrow to Sheol."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 44, 30, 'Now therefore, when I come to your servant my father and the boy is not with us, then, as his life is bound up in the boy"s life,', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 44, 31, 'when he sees that the boy is not with us, he will die; and your servants will bring down the gray hairs of your servant our father with sorrow to Sheol.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 44, 32, 'For your servant became surety for the boy to my father, saying, "If I do not bring him back to you, then I will bear the blame in the sight of my father all my life."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 44, 33, 'Now therefore, please let your servant remain as a slave to my lord in place of the boy; and let the boy go back with his brothers.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 44, 34, 'For how can I go back to my father if the boy is not with me? I fear to see the suffering that would come upon my father."', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(1, 'Kej', 'Genesis', 45, 1, 'Then Joseph could no longer control himself before all those who stood by him, and he cried out, "Send everyone away from me." So no one stayed with him when Joseph made himself known to his brothers.', 'en', 'NRSV-CE', 'Joseph Reveals Himself to His Brothers'),
(1, 'Kej', 'Genesis', 45, 2, 'And he wept so loudly that the Egyptians heard it, and the household of Pharaoh heard it.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 45, 3, 'Joseph said to his brothers, "I am Joseph. Is my father still alive?" But his brothers could not answer him, so dismayed were they at his presence.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 45, 4, 'Then Joseph said to his brothers, "Come closer to me." And they came closer. He said, "I am your brother, Joseph, whom you sold into Egypt.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 45, 5, 'And now do not be distressed, or angry with yourselves, because you sold me here; for God sent me before you to preserve life.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 45, 6, 'For the famine has been in the land these two years; and there are five more years in which there will be neither plowing nor harvest.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 45, 7, 'God sent me before you to preserve for you a remnant on earth, and to keep alive for you many survivors.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 45, 8, 'So it was not you who sent me here, but God; he has made me a father to Pharaoh, and lord of all his house and ruler over all the land of Egypt.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 45, 9, 'Hurry and go up to my father and say to him, "Thus says your son Joseph, God has made me lord of all Egypt; come down to me, do not delay.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 45, 10, 'You shall settle in the land of Goshen, and you shall be near me, you and your children and your children"s children, as well as your flocks, your herds, and all that you have.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 45, 11, 'I will provide for you there--since there are five more years of famine to come--so that you and your household, and all that you have, will not come to poverty."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 45, 12, 'And now your eyes and the eyes of my brother Benjamin see that it is my own mouth that speaks to you.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 45, 13, 'You must tell my father how greatly I am honored in Egypt, and all that you have seen. Hurry and bring my father down here."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 45, 14, 'Then he fell upon his brother Benjamin"s neck and wept, while Benjamin wept upon his neck.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 45, 15, 'And he kissed all his brothers and wept upon them; and after that his brothers talked with him.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 45, 16, 'When the report was heard in Pharaoh"s house, "Joseph"s brothers have come," Pharaoh and his servants were pleased.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 45, 17, 'Pharaoh said to Joseph, "Say to your brothers, "Do this: load your animals and go back to the land of Canaan.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 45, 18, 'Take your father and your households and come to me, so that I may give you the best of the land of Egypt, and you may enjoy the fat of the land."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 45, 19, 'You are further charged to say, "Do this: take wagons from the land of Egypt for your little ones and for your wives, and bring your father, and come.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 45, 20, 'Give no thought to your possessions, for the best of all the land of Egypt is yours.""', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 45, 21, 'The sons of Israel did so. Joseph gave them wagons according to the instruction of Pharaoh, and he gave them provisions for the journey.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 45, 22, 'To each one of them he gave a set of garments; but to Benjamin he gave three hundred pieces of silver and five sets of garments.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 45, 23, 'To his father he sent the following: ten donkeys loaded with the good things of Egypt, and ten female donkeys loaded with grain, bread, and provision for his father on the journey.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 45, 24, 'Then he sent his brothers on their way, and as they were leaving he said to them, "Do not quarrel along the way."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 45, 25, 'So they went up out of Egypt and came to their father Jacob in the land of Canaan.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 45, 26, 'And they told him, "Joseph is still alive! He is even ruler over all the land of Egypt." He was stunned; he could not believe them.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 45, 27, 'But when they told him all the words of Joseph that he had said to them, and when he saw the wagons that Joseph had sent to carry him, the spirit of their father Jacob revived.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 45, 28, 'Israel said, "Enough! My son Joseph is still alive. I must go and see him before I die."', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(1, 'Kej', 'Genesis', 46, 1, 'When Israel set out on his journey with all that he had and came to Beer-sheba, he offered sacrifices to the God of his father Isaac.', 'en', 'NRSV-CE', 'Jacob Brings His Whole Family to Egypt'),
(1, 'Kej', 'Genesis', 46, 2, 'God spoke to Israel in visions of the night, and said, "Jacob, Jacob." And he said, "Here I am."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 46, 3, 'Then he said, "I am God, the God of your father; do not be afraid to go down to Egypt, for I will make of you a great nation there.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 46, 4, 'I myself will go down with you to Egypt, and I will also bring you up again; and Joseph"s own hand shall close your eyes."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 46, 5, 'Then Jacob set out from Beer-sheba; and the sons of Israel carried their father Jacob, their little ones, and their wives, in the wagons that Pharaoh had sent to carry him.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 46, 6, 'They also took their livestock and the goods that they had acquired in the land of Canaan, and they came into Egypt, Jacob and all his offspring with him,', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 46, 7, 'his sons, and his sons" sons with him, his daughters, and his sons" daughters; all his offspring he brought with him into Egypt.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 46, 8, 'Now these are the names of the Israelites, Jacob and his offspring, who came to Egypt. Reuben, Jacob"s firstborn,', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 46, 9, 'and the children of Reuben: Hanoch, Pallu, Hezron, and Carmi.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 46, 10, 'The children of Simeon: Jemuel, Jamin, Ohad, Jachin, Zohar, and Shaul, the son of a Canaanite woman.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 46, 11, 'The children of Levi: Gershon, Kohath, and Merari.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 46, 12, 'The children of Judah: Er, Onan, Shelah, Perez, and Zerah (but Er and Onan died in the land of Canaan); and the children of Perez were Hezron and Hamul.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 46, 13, 'The children of Issachar: Tola, Puvah, Jashub, and Shimron.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 46, 14, 'The children of Zebulun: Sered, Elon, and Jahleel', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 46, 15, '(these are the sons of Leah, whom she bore to Jacob in Paddan-aram, together with his daughter Dinah; in all his sons and his daughters numbered thirty-three).', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 46, 16, 'The children of Gad: Ziphion, Haggi, Shuni, Ezbon, Eri, Arodi, and Areli.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 46, 17, 'The children of Asher: Imnah, Ishvah, Ishvi, Beriah, and their sister Serah. The children of Beriah: Heber and Malchiel', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 46, 18, '(these are the children of Zilpah, whom Laban gave to his daughter Leah; and these she bore to Jacob--sixteen persons).', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 46, 19, 'The children of Jacob"s wife Rachel: Joseph and Benjamin.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 46, 20, 'To Joseph in the land of Egypt were born Manasseh and Ephraim, whom Asenath daughter of Potiphera, priest of On, bore to him.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 46, 21, 'The children of Benjamin: Bela, Becher, Ashbel, Gera, Naaman, Ehi, Rosh, Muppim, Huppim, and Ard', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 46, 22, '(these are the children of Rachel, who were born to Jacob--fourteen persons in all).', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 46, 23, 'The children of Dan: Hashum.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 46, 24, 'The children of Naphtali: Jahzeel, Guni, Jezer, and Shillem', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 46, 25, '(these are the children of Bilhah, whom Laban gave to his daughter Rachel, and these she bore to Jacob--seven persons in all).', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 46, 26, 'All the persons belonging to Jacob who came into Egypt, who were his own offspring, not including the wives of his sons, were sixty-six persons in all.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 46, 27, 'The children of Joseph, who were born to him in Egypt, were two; all the persons of the house of Jacob who came into Egypt were seventy.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 46, 28, 'Israel sent Judah ahead to Joseph to lead the way before him into Goshen. When they came to the land of Goshen,', 'en', 'NRSV-CE', 'Jacob Settles in Goshen'),
(1, 'Kej', 'Genesis', 46, 29, 'Joseph made ready his chariot and went up to meet his father Israel in Goshen. He presented himself to him, fell on his neck, and wept on his neck a good while.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 46, 30, 'Israel said to Joseph, "I can die now, having seen for myself that you are still alive."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 46, 31, 'Joseph said to his brothers and to his father"s household, "I will go up and tell Pharaoh, and will say to him, "My brothers and my father"s household, who were in the land of Canaan, have come to me.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 46, 32, 'The men are shepherds, for they have been keepers of livestock; and they have brought their flocks, and their herds, and all that they have."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 46, 33, 'When Pharaoh calls you, and says, "What is your occupation?"', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 46, 34, 'you shall say, "Your servants have been keepers of livestock from our youth even until now, both we and our ancestors"--in order that you may settle in the land of Goshen, because all shepherds are abhorrent to the Egyptians."', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(1, 'Kej', 'Genesis', 47, 1, 'So Joseph went and told Pharaoh, "My father and my brothers, with their flocks and herds and all that they possess, have come from the land of Canaan; they are now in the land of Goshen."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 47, 2, 'From among his brothers he took five men and presented them to Pharaoh.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 47, 3, 'Pharaoh said to his brothers, "What is your occupation?" And they said to Pharaoh, "Your servants are shepherds, as our ancestors were."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 47, 4, 'They said to Pharaoh, "We have come to reside as aliens in the land; for there is no pasture for your servants" flocks because the famine is severe in the land of Canaan. Now, we ask you, let your servants settle in the land of Goshen."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 47, 5, 'Then Pharaoh said to Joseph, "Your father and your brothers have come to you.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 47, 6, 'The land of Egypt is before you; settle your father and your brothers in the best part of the land; let them live in the land of Goshen; and if you know that there are capable men among them, put them in charge of my livestock."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 47, 7, 'Then Joseph brought in his father Jacob, and presented him before Pharaoh, and Jacob blessed Pharaoh.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 47, 8, 'Pharaoh said to Jacob, "How many are the years of your life?"', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 47, 9, 'Jacob said to Pharaoh, "The years of my earthly sojourn are one hundred thirty; few and hard have been the years of my life. They do not compare with the years of the life of my ancestors during their long sojourn."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 47, 10, 'Then Jacob blessed Pharaoh, and went out from the presence of Pharaoh.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 47, 11, 'Joseph settled his father and his brothers, and granted them a holding in the land of Egypt, in the best part of the land, in the land of Rameses, as Pharaoh had instructed.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 47, 12, 'And Joseph provided his father, his brothers, and all his father"s household with food, according to the number of their dependents.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 47, 13, 'Now there was no food in all the land, for the famine was very severe. The land of Egypt and the land of Canaan languished because of the famine.', 'en', 'NRSV-CE', 'The Famine in Egypt'),
(1, 'Kej', 'Genesis', 47, 14, 'Joseph collected all the money to be found in the land of Egypt and in the land of Canaan, in exchange for the grain that they bought; and Joseph brought the money into Pharaoh"s house.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 47, 15, 'When the money from the land of Egypt and from the land of Canaan was spent, all the Egyptians came to Joseph, and said, "Give us food! Why should we die before your eyes? For our money is gone."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 47, 16, 'And Joseph answered, "Give me your livestock, and I will give you food in exchange for your livestock, if your money is gone."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 47, 17, 'So they brought their livestock to Joseph; and Joseph gave them food in exchange for the horses, the flocks, the herds, and the donkeys. That year he supplied them with food in exchange for all their livestock.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 47, 18, 'When that year was ended, they came to him the following year, and said to him, "We can not hide from my lord that our money is all spent; and the herds of cattle are my lord"s. There is nothing left in the sight of my lord but our bodies and our lands.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 47, 19, 'Shall we die before your eyes, both we and our land? Buy us and our land in exchange for food. We with our land will become slaves to Pharaoh; just give us seed, so that we may live and not die, and that the land may not become desolate."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 47, 20, 'So Joseph bought all the land of Egypt for Pharaoh. All the Egyptians sold their fields, because the famine was severe upon them; and the land became Pharaoh"s.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 47, 21, 'As for the people, he made slaves of them from one end of Egypt to the other.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 47, 22, 'Only the land of the priests he did not buy; for the priests had a fixed allowance from Pharaoh, and lived on the allowance that Pharaoh gave them; therefore they did not sell their land.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 47, 23, 'Then Joseph said to the people, "Now that I have this day bought you and your land for Pharaoh, here is seed for you; sow the land.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 47, 24, 'And at the harvests you shall give one-fifth to Pharaoh, and four-fifths shall be your own, as seed for the field and as food for yourselves and your households, and as food for your little ones."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 47, 25, 'They said, "You have saved our lives; may it please my lord, we will be slaves to Pharaoh."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 47, 26, 'So Joseph made it a statute concerning the land of Egypt, and it stands to this day, that Pharaoh should have the fifth. The land of the priests alone did not become Pharaoh"s.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 47, 27, 'Thus Israel settled in the land of Egypt, in the region of Goshen; and they gained possessions in it, and were fruitful and multiplied exceedingly.', 'en', 'NRSV-CE', 'The Last Days of Jacob'),
(1, 'Kej', 'Genesis', 47, 28, 'Jacob lived in the land of Egypt seventeen years; so the days of Jacob, the years of his life, were one hundred forty-seven years.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 47, 29, 'When the time of Israel"s death drew near, he called his son Joseph and said to him, "If I have found favor with you, put your hand under my thigh and promise to deal loyally and truly with me. Do not bury me in Egypt.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 47, 30, 'When I lie down with my ancestors, carry me out of Egypt and bury me in their burial place." He answered, "I will do as you have said."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 47, 31, 'And he said, "Swear to me"; and he swore to him. Then Israel bowed himself on the head of his bed.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(1, 'Kej', 'Genesis', 48, 1, 'After this Joseph was told, "Your father is ill." So he took with him his two sons, Manasseh and Ephraim.', 'en', 'NRSV-CE', 'Jacob Blesses Joseph"s Sons'),
(1, 'Kej', 'Genesis', 48, 2, 'When Jacob was told, "Your son Joseph has come to you," he summoned his strength and sat up in bed.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 48, 3, 'And Jacob said to Joseph, "God Almighty appeared to me at Luz in the land of Canaan, and he blessed me,', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 48, 4, 'and said to me, "I am going to make you fruitful and increase your numbers; I will make of you a company of peoples, and will give this land to your offspring after you for a perpetual holding."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 48, 5, 'Therefore your two sons, who were born to you in the land of Egypt before I came to you in Egypt, are now mine; Ephraim and Manasseh shall be mine, just as Reuben and Simeon are.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 48, 6, 'As for the offspring born to you after them, they shall be yours. They shall be recorded under the names of their brothers with regard to their inheritance.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 48, 7, 'For when I came from Paddan, Rachel, alas, died in the land of Canaan on the way, while there was still some distance to go to Ephrath; and I buried her there on the way to Ephrath" (that is, Bethlehem).', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 48, 8, 'When Israel saw Joseph"s sons, he said, "Who are these?"', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 48, 9, 'Joseph said to his father, "They are my sons, whom God has given me here." And he said, "Bring them to me, please, that I may bless them."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 48, 10, 'Now the eyes of Israel were dim with age, and he could not see well. So Joseph brought them near him; and he kissed them and embraced them.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 48, 11, 'Israel said to Joseph, "I did not expect to see your face; and here God has let me see your children also."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 48, 12, 'Then Joseph removed them from his father"s knees, and he bowed himself with his face to the earth.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 48, 13, 'Joseph took them both, Ephraim in his right hand toward Israel"s left, and Manasseh in his left hand toward Israel"s right, and brought them near him.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 48, 14, 'But Israel stretched out his right hand and laid it on the head of Ephraim, who was the younger, and his left hand on the head of Manasseh, crossing his hands, for Manasseh was the firstborn.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 48, 15, 'He blessed Joseph, and said,
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(1, 'Kej', 'Genesis', 49, 1, 'Then Jacob called his sons, and said: "Gather around, that I may tell you what will happen to you in days to come.', 'en', 'NRSV-CE', 'Jacob"s Last Words to His Sons'),
(1, 'Kej', 'Genesis', 49, 2, 'Assemble and hear, O sons of Jacob;  
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(1, 'Kej', 'Genesis', 50, 1, 'Then Joseph threw himself on his father"s face and wept over him and kissed him.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 50, 2, 'Joseph commanded the physicians in his service to embalm his father. So the physicians embalmed Israel;', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 50, 3, 'they spent forty days in doing this, for that is the time required for embalming. And the Egyptians wept for him seventy days.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 50, 4, 'When the days of weeping for him were past, Joseph addressed the household of Pharaoh, "If now I have found favor with you, please speak to Pharaoh as follows:', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 50, 5, 'My father made me swear an oath; he said, "I am about to die. In the tomb that I hewed out for myself in the land of Canaan, there you shall bury me." Now therefore let me go up, so that I may bury my father; then I will return."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 50, 6, 'Pharaoh answered, "Go up, and bury your father, as he made you swear to do."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 50, 7, 'So Joseph went up to bury his father. With him went up all the servants of Pharaoh, the elders of his household, and all the elders of the land of Egypt,', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 50, 8, 'as well as all the household of Joseph, his brothers, and his father"s household. Only their children, their flocks, and their herds were left in the land of Goshen.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 50, 9, 'Both chariots and charioteers went up with him. It was a very great company.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 50, 10, 'When they came to the threshing floor of Atad, which is beyond the Jordan, they held there a very great and sorrowful lamentation; and he observed a time of mourning for his father seven days.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 50, 11, 'When the Canaanite inhabitants of the land saw the mourning on the threshing floor of Atad, they said, "This is a grievous mourning on the part of the Egyptians." Therefore the place was named Abel-mizraim; it is beyond the Jordan.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 50, 12, 'Thus his sons did for him as he had instructed them.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 50, 13, 'They carried him to the land of Canaan and buried him in the cave of the field at Machpelah, the field near Mamre, which Abraham bought as a burial site from Ephron the Hittite.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 50, 14, 'After he had buried his father, Joseph returned to Egypt with his brothers and all who had gone up with him to bury his father.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 50, 15, 'Realizing that their father was dead, Joseph"s brothers said, "What if Joseph still bears a grudge against us and pays us back in full for all the wrong that we did to him?"', 'en', 'NRSV-CE', 'Joseph Forgives His Brothers'),
(1, 'Kej', 'Genesis', 50, 16, 'So they approached Joseph, saying, "Your father gave this instruction before he died,', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 50, 17, '"Say to Joseph: I beg you, forgive the crime of your brothers and the wrong they did in harming you." Now therefore please forgive the crime of the servants of the God of your father." Joseph wept when they spoke to him.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 50, 18, 'Then his brothers also wept, fell down before him, and said, "We are here as your slaves."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 50, 19, 'But Joseph said to them, "Do not be afraid! Am I in the place of God?', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 50, 20, 'Even though you intended to do harm to me, God intended it for good, in order to preserve a numerous people, as he is doing today.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 50, 21, 'So have no fear; I myself will provide for you and your little ones." In this way he reassured them, speaking kindly to them.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 50, 22, 'So Joseph remained in Egypt, he and his father"s household; and Joseph lived one hundred ten years.', 'en', 'NRSV-CE', 'Joseph"s Last Days and Death'),
(1, 'Kej', 'Genesis', 50, 23, 'Joseph saw Ephraim"s children of the third generation; the children of Machir son of Manasseh were also born on Joseph"s knees.', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 50, 24, 'Then Joseph said to his brothers, "I am about to die; but God will surely come to you, and bring you up out of this land to the land that he swore to Abraham, to Isaac, and to Jacob."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 50, 25, 'So Joseph made the Israelites swear, saying, "When God comes to you, you shall carry up my bones from here."', 'en', 'NRSV-CE', NULL),
(1, 'Kej', 'Genesis', 50, 26, 'And Joseph died, being one hundred ten years old; he was embalmed and placed in a coffin in Egypt.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(2, 'Kel', 'Exodus', 1, 1, 'These are the names of the sons of Israel who came to Egypt with Jacob, each with his household:', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 1, 2, 'Reuben, Simeon, Levi, and Judah,', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 1, 3, 'Issachar, Zebulun, and Benjamin,', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 1, 4, 'Dan and Naphtali, Gad and Asher.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 1, 5, 'The total number of people born to Jacob was seventy. Joseph was already in Egypt.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 1, 6, 'Then Joseph died, and all his brothers, and that whole generation.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 1, 7, 'But the Israelites were fruitful and prolific; they multiplied and grew exceedingly strong, so that the land was filled with them.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 1, 8, 'Now a new king arose over Egypt, who did not know Joseph.', 'en', 'NRSV-CE', 'The Israelites Are Oppressed'),
(2, 'Kel', 'Exodus', 1, 9, 'He said to his people, "Look, the Israelite people are more numerous and more powerful than we.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 1, 10, 'Come, let us deal shrewdly with them, or they will increase and, in the event of war, join our enemies and fight against us and escape from the land."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 1, 11, 'Therefore they set taskmasters over them to oppress them with forced labor. They built supply cities, Pithom and Rameses, for Pharaoh.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 1, 12, 'But the more they were oppressed, the more they multiplied and spread, so that the Egyptians came to dread the Israelites.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 1, 13, 'The Egyptians became ruthless in imposing tasks on the Israelites,', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 1, 14, 'and made their lives bitter with hard service in mortar and brick and in every kind of field labor. They were ruthless in all the tasks that they imposed on them.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 1, 15, 'The king of Egypt said to the Hebrew midwives, one of whom was named Shiphrah and the other Puah,', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 1, 16, '"When you act as midwives to the Hebrew women, and see them on the birthstool, if it is a boy, kill him; but if it is a girl, she shall live."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 1, 17, 'But the midwives feared God; they did not do as the king of Egypt commanded them, but they let the boys live.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 1, 18, 'So the king of Egypt summoned the midwives and said to them, "Why have you done this, and allowed the boys to live?"', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 1, 19, 'The midwives said to Pharaoh, "Because the Hebrew women are not like the Egyptian women; for they are vigorous and give birth before the midwife comes to them."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 1, 20, 'So God dealt well with the midwives; and the people multiplied and became very strong.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 1, 21, 'And because the midwives feared God, he gave them families.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 1, 22, 'Then Pharaoh commanded all his people, "Every boy that is born to the Hebrews you shall throw into the Nile, but you shall let every girl live."', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(2, 'Kel', 'Exodus', 2, 1, 'Now a man from the house of Levi went and married a Levite woman.', 'en', 'NRSV-CE', 'Birth and Youth of Moses'),
(2, 'Kel', 'Exodus', 2, 2, 'The woman conceived and bore a son; and when she saw that he was a fine baby, she hid him three months.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 2, 3, 'When she could hide him no longer she got a papyrus basket for him, and plastered it with bitumen and pitch; she put the child in it and placed it among the reeds on the bank of the river.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 2, 4, 'His sister stood at a distance, to see what would happen to him.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 2, 5, 'The daughter of Pharaoh came down to bathe at the river, while her attendants walked beside the river. She saw the basket among the reeds and sent her maid to bring it.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 2, 6, 'When she opened it, she saw the child. He was crying, and she took pity on him. "This must be one of the Hebrews" children," she said.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 2, 7, 'Then his sister said to Pharaoh"s daughter, "Shall I go and get you a nurse from the Hebrew women to nurse the child for you?"', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 2, 8, 'Pharaoh"s daughter said to her, "Yes." So the girl went and called the child"s mother.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 2, 9, 'Pharaoh"s daughter said to her, "Take this child and nurse it for me, and I will give you your wages." So the woman took the child and nursed it.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 2, 10, 'When the child grew up, she brought him to Pharaoh"s daughter, and she took him as her son. She named him Moses, "because," she said, "I drew him out of the water."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 2, 11, 'One day, after Moses had grown up, he went out to his people and saw their forced labor. He saw an Egyptian beating a Hebrew, one of his kinsfolk.', 'en', 'NRSV-CE', 'Moses Flees to Midian'),
(2, 'Kel', 'Exodus', 2, 12, 'He looked this way and that, and seeing no one he killed the Egyptian and hid him in the sand.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 2, 13, 'When he went out the next day, he saw two Hebrews fighting; and he said to the one who was in the wrong, "Why do you strike your fellow Hebrew?"', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 2, 14, 'He answered, "Who made you a ruler and judge over us? Do you mean to kill me as you killed the Egyptian?" Then Moses was afraid and thought, "Surely the thing is known."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 2, 15, 'When Pharaoh heard of it, he sought to kill Moses.
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(2, 'Kel', 'Exodus', 3, 1, 'Moses was keeping the flock of his father-in-law Jethro, the priest of Midian; he led his flock beyond the wilderness, and came to Horeb, the mountain of God.', 'en', 'NRSV-CE', 'Moses at the Burning Bush'),
(2, 'Kel', 'Exodus', 3, 2, 'There the angel of the LORD appeared to him in a flame of fire out of a bush; he looked, and the bush was blazing, yet it was not consumed.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 3, 3, 'Then Moses said, "I must turn aside and look at this great sight, and see why the bush is not burned up."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 3, 4, 'When the LORD saw that he had turned aside to see, God called to him out of the bush, "Moses, Moses!" And he said, "Here I am."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 3, 5, 'Then he said, "Come no closer! Remove the sandals from your feet, for the place on which you are standing is holy ground."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 3, 6, 'He said further, "I am the God of your father, the God of Abraham, the God of Isaac, and the God of Jacob." And Moses hid his face, for he was afraid to look at God.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 3, 7, 'Then the LORD said, "I have observed the misery of my people who are in Egypt; I have heard their cry on account of their taskmasters. Indeed, I know their sufferings,', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 3, 8, 'and I have come down to deliver them from the Egyptians, and to bring them up out of that land to a good and broad land, a land flowing with milk and honey, to the country of the Canaanites, the Hittites, the Amorites, the Perizzites, the Hivites, and the Jebusites.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 3, 9, 'The cry of the Israelites has now come to me; I have also seen how the Egyptians oppress them.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 3, 10, 'So come, I will send you to Pharaoh to bring my people, the Israelites, out of Egypt."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 3, 11, 'But Moses said to God, "Who am I that I should go to Pharaoh, and bring the Israelites out of Egypt?"', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 3, 12, 'He said, "I will be with you; and this shall be the sign for you that it is I who sent you: when you have brought the people out of Egypt, you shall worship God on this mountain."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 3, 13, 'But Moses said to God, "If I come to the Israelites and say to them, "The God of your ancestors has sent me to you," and they ask me, "What is his name?" what shall I say to them?"', 'en', 'NRSV-CE', 'The Divine Name Revealed'),
(2, 'Kel', 'Exodus', 3, 14, 'God said to Moses, "I am who I am." He said further, "Thus you shall say to the Israelites, "I am has sent me to you.""', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 3, 15, 'God also said to Moses, "Thus you shall say to the Israelites, "The LORD, the God of your ancestors, the God of Abraham, the God of Isaac, and the God of Jacob, has sent me to you":
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(2, 'Kel', 'Exodus', 4, 1, 'Then Moses answered, "But suppose they do not believe me or listen to me, but say, "The LORD did not appear to you.""', 'en', 'NRSV-CE', 'Moses" Miraculous Power'),
(2, 'Kel', 'Exodus', 4, 2, 'The LORD said to him, "What is that in your hand?" He said, "A staff."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 4, 3, 'And he said, "Throw it on the ground." So he threw the staff on the ground, and it became a snake; and Moses drew back from it.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 4, 4, 'Then the LORD said to Moses, "Reach out your hand, and seize it by the tail"--so he reached out his hand and grasped it, and it became a staff in his hand--', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 4, 5, '"so that they may believe that the LORD, the God of their ancestors, the God of Abraham, the God of Isaac, and the God of Jacob, has appeared to you."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 4, 6, 'Again, the LORD said to him, "Put your hand inside your cloak." He put his hand into his cloak; and when he took it out, his hand was leprous, as white as snow.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 4, 7, 'Then God said, "Put your hand back into your cloak"--so he put his hand back into his cloak, and when he took it out, it was restored like the rest of his body--', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 4, 8, '"If they will not believe you or heed the first sign, they may believe the second sign.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 4, 9, 'If they will not believe even these two signs or heed you, you shall take some water from the Nile and pour it on the dry ground; and the water that you shall take from the Nile will become blood on the dry ground."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 4, 10, 'But Moses said to the LORD, "O my Lord, I have never been eloquent, neither in the past nor even now that you have spoken to your servant; but I am slow of speech and slow of tongue."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 4, 11, 'Then the LORD said to him, "Who gives speech to mortals? Who makes them mute or deaf, seeing or blind? Is it not I, the LORD?', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 4, 12, 'Now go, and I will be with your mouth and teach you what you are to speak."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 4, 13, 'But he said, "O my Lord, please send someone else."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 4, 14, 'Then the anger of the LORD was kindled against Moses and he said, "What of your brother Aaron the Levite? I know that he can speak fluently; even now he is coming out to meet you, and when he sees you his heart will be glad.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 4, 15, 'You shall speak to him and put the words in his mouth; and I will be with your mouth and with his mouth, and will teach you what you shall do.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 4, 16, 'He indeed shall speak for you to the people; he shall serve as a mouth for you, and you shall serve as God for him.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 4, 17, 'Take in your hand this staff, with which you shall perform the signs."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 4, 18, 'Moses went back to his father-in-law Jethro and said to him, "Please let me go back to my kindred in Egypt and see whether they are still living." And Jethro said to Moses, "Go in peace."', 'en', 'NRSV-CE', 'Moses Returns to Egypt'),
(2, 'Kel', 'Exodus', 4, 19, 'The LORD said to Moses in Midian, "Go back to Egypt; for all those who were seeking your life are dead."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 4, 20, 'So Moses took his wife and his sons, put them on a donkey, and went back to the land of Egypt; and Moses carried the staff of God in his hand.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 4, 21, 'And the LORD said to Moses, "When you go back to Egypt, see that you perform before Pharaoh all the wonders that I have put in your power; but I will harden his heart, so that he will not let the people go.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 4, 22, 'Then you shall say to Pharaoh, "Thus says the LORD: Israel is my firstborn son.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 4, 23, 'I said to you, "Let my son go that he may worship me." But you refused to let him go; now I will kill your firstborn son.""', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 4, 24, 'On the way, at a place where they spent the night, the LORD met him and tried to kill him.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 4, 25, 'But Zipporah took a flint and cut off her son"s foreskin, and touched Moses" feet with it, and said, "Truly you are a bridegroom of blood to me!"', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 4, 26, 'So he let him alone. It was then she said, "A bridegroom of blood by circumcision."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 4, 27, 'The LORD said to Aaron, "Go into the wilderness to meet Moses." So he went; and he met him at the mountain of God and kissed him.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 4, 28, 'Moses told Aaron all the words of the LORD with which he had sent him, and all the signs with which he had charged him.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 4, 29, 'Then Moses and Aaron went and assembled all the elders of the Israelites.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 4, 30, 'Aaron spoke all the words that the LORD had spoken to Moses, and performed the signs in the sight of the people.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 4, 31, 'The people believed; and when they heard that the LORD had given heed to the Israelites and that he had seen their misery, they bowed down and worshiped.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(2, 'Kel', 'Exodus', 5, 1, 'Afterward Moses and Aaron went to Pharaoh and said, "Thus says the LORD, the God of Israel, "Let my people go, so that they may celebrate a festival to me in the wilderness.""', 'en', 'NRSV-CE', 'Bricks without Straw'),
(2, 'Kel', 'Exodus', 5, 2, 'But Pharaoh said, "Who is the LORD, that I should heed him and let Israel go? I do not know the LORD, and I will not let Israel go."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 5, 3, 'Then they said, "The God of the Hebrews has revealed himself to us; let us go a three days" journey into the wilderness to sacrifice to the LORD our God, or he will fall upon us with pestilence or sword."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 5, 4, 'But the king of Egypt said to them, "Moses and Aaron, why are you taking the people away from their work? Get to your labors!"', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 5, 5, 'Pharaoh continued, "Now they are more numerous than the people of the land and yet you want them to stop working!"', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 5, 6, 'That same day Pharaoh commanded the taskmasters of the people, as well as their supervisors,', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 5, 7, '"You shall no longer give the people straw to make bricks, as before; let them go and gather straw for themselves.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 5, 8, 'But you shall require of them the same quantity of bricks as they have made previously; do not diminish it, for they are lazy; that is why they cry, "Let us go and offer sacrifice to our God."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 5, 9, 'Let heavier work be laid on them; then they will labor at it and pay no attention to deceptive words."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 5, 10, 'So the taskmasters and the supervisors of the people went out and said to the people, "Thus says Pharaoh, "I will not give you straw.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 5, 11, 'Go and get straw yourselves, wherever you can find it; but your work will not be lessened in the least.""', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 5, 12, 'So the people scattered throughout the land of Egypt, to gather stubble for straw.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 5, 13, 'The taskmasters were urgent, saying, "Complete your work, the same daily assignment as when you were given straw."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 5, 14, 'And the supervisors of the Israelites, whom Pharaoh"s taskmasters had set over them, were beaten, and were asked, "Why did you not finish the required quantity of bricks yesterday and today, as you did before?"', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 5, 15, 'Then the Israelite supervisors came to Pharaoh and cried, "Why do you treat your servants like this?', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 5, 16, 'No straw is given to your servants, yet they say to us, "Make bricks!" Look how your servants are beaten! You are unjust to your own people."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 5, 17, 'He said, "You are lazy, lazy; that is why you say, "Let us go and sacrifice to the LORD."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 5, 18, 'Go now, and work; for no straw shall be given you, but you shall still deliver the same number of bricks."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 5, 19, 'The Israelite supervisors saw that they were in trouble when they were told, "You shall not lessen your daily number of bricks."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 5, 20, 'As they left Pharaoh, they came upon Moses and Aaron who were waiting to meet them.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 5, 21, 'They said to them, "The LORD look upon you and judge! You have brought us into bad odor with Pharaoh and his officials, and have put a sword in their hand to kill us."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 5, 22, 'Then Moses turned again to the LORD and said, "O LORD, why have you mistreated this people? Why did you ever send me?', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 5, 23, 'Since I first came to Pharaoh to speak in your name, he has mistreated this people, and you have done nothing at all to deliver your people."', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(2, 'Kel', 'Exodus', 6, 1, 'Then the LORD said to Moses, "Now you shall see what I will do to Pharaoh: Indeed, by a mighty hand he will let them go; by a mighty hand he will drive them out of his land."', 'en', 'NRSV-CE', 'Israel"s Deliverance Assured'),
(2, 'Kel', 'Exodus', 6, 2, 'God also spoke to Moses and said to him: "I am the LORD.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 6, 3, 'I appeared to Abraham, Isaac, and Jacob as God Almighty, but by my name "The LORD" I did not make myself known to them.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 6, 4, 'I also established my covenant with them, to give them the land of Canaan, the land in which they resided as aliens.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 6, 5, 'I have also heard the groaning of the Israelites whom the Egyptians are holding as slaves, and I have remembered my covenant.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 6, 6, 'Say therefore to the Israelites, "I am the LORD, and I will free you from the burdens of the Egyptians and deliver you from slavery to them. I will redeem you with an outstretched arm and with mighty acts of judgment.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 6, 7, 'I will take you as my people, and I will be your God. You shall know that I am the LORD your God, who has freed you from the burdens of the Egyptians.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 6, 8, 'I will bring you into the land that I swore to give to Abraham, Isaac, and Jacob; I will give it to you for a possession. I am the LORD.""', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 6, 9, 'Moses told this to the Israelites; but they would not listen to Moses, because of their broken spirit and their cruel slavery.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 6, 10, 'Then the LORD spoke to Moses,', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 6, 11, '"Go and tell Pharaoh king of Egypt to let the Israelites go out of his land."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 6, 12, 'But Moses spoke to the LORD, "The Israelites have not listened to me; how then shall Pharaoh listen to me, poor speaker that I am?"', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 6, 13, 'Thus the LORD spoke to Moses and Aaron, and gave them orders regarding the Israelites and Pharaoh king of Egypt, charging them to free the Israelites from the land of Egypt.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 6, 14, 'The following are the heads of their ancestral houses: the sons of Reuben, the firstborn of Israel: Hanoch, Pallu, Hezron, and Carmi; these are the families of Reuben.', 'en', 'NRSV-CE', 'The Genealogy of Moses and Aaron'),
(2, 'Kel', 'Exodus', 6, 15, 'The sons of Simeon: Jemuel, Jamin, Ohad, Jachin, Zohar, and Shaul, the son of a Canaanite woman; these are the families of Simeon.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 6, 16, 'The following are the names of the sons of Levi according to their genealogies: Gershon, Kohath, and Merari, and the length of Levi"s life was one hundred thirty-seven years.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 6, 17, 'The sons of Gershon: Libni and Shimei, by their families.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 6, 18, 'The sons of Kohath: Amram, Izhar, Hebron, and Uzziel, and the length of Kohath"s life was one hundred thirty-three years.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 6, 19, 'The sons of Merari: Mahli and Mushi. These are the families of the Levites according to their genealogies.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 6, 20, 'Amram married Jochebed his father"s sister and she bore him Aaron and Moses, and the length of Amram"s life was one hundred thirty-seven years.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 6, 21, 'The sons of Izhar: Korah, Nepheg, and Zichri.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 6, 22, 'The sons of Uzziel: Mishael, Elzaphan, and Sithri.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 6, 23, 'Aaron married Elisheba, daughter of Amminadab and sister of Nahshon, and she bore him Nadab, Abihu, Eleazar, and Ithamar.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 6, 24, 'The sons of Korah: Assir, Elkanah, and Abiasaph; these are the families of the Korahites.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 6, 25, 'Aaron"s son Eleazar married one of the daughters of Putiel, and she bore him Phinehas. These are the heads of the ancestral houses of the Levites by their families.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 6, 26, 'It was this same Aaron and Moses to whom the LORD said, "Bring the Israelites out of the land of Egypt, company by company."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 6, 27, 'It was they who spoke to Pharaoh king of Egypt to bring the Israelites out of Egypt, the same Moses and Aaron.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 6, 28, 'On the day when the LORD spoke to Moses in the land of Egypt,', 'en', 'NRSV-CE', 'Moses and Aaron Obey God"s Commands'),
(2, 'Kel', 'Exodus', 6, 29, 'he said to him, "I am the LORD; tell Pharaoh king of Egypt all that I am speaking to you."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 6, 30, 'But Moses said in the LORD"s presence, "Since I am a poor speaker, why would Pharaoh listen to me?"', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(2, 'Kel', 'Exodus', 7, 1, 'The LORD said to Moses, "See, I have made you like God to Pharaoh, and your brother Aaron shall be your prophet.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 7, 2, 'You shall speak all that I command you, and your brother Aaron shall tell Pharaoh to let the Israelites go out of his land.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 7, 3, 'But I will harden Pharaoh"s heart, and I will multiply my signs and wonders in the land of Egypt.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 7, 4, 'When Pharaoh does not listen to you, I will lay my hand upon Egypt and bring my people the Israelites, company by company, out of the land of Egypt by great acts of judgment.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 7, 5, 'The Egyptians shall know that I am the LORD, when I stretch out my hand against Egypt and bring the Israelites out from among them."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 7, 6, 'Moses and Aaron did so; they did just as the LORD commanded them.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 7, 7, 'Moses was eighty years old and Aaron eighty-three when they spoke to Pharaoh.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 7, 8, 'The LORD said to Moses and Aaron,', 'en', 'NRSV-CE', 'Aaron"s Miraculous Rod'),
(2, 'Kel', 'Exodus', 7, 9, '"When Pharaoh says to you, "Perform a wonder," then you shall say to Aaron, "Take your staff and throw it down before Pharaoh, and it will become a snake.""', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 7, 10, 'So Moses and Aaron went to Pharaoh and did as the LORD had commanded; Aaron threw down his staff before Pharaoh and his officials, and it became a snake.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 7, 11, 'Then Pharaoh summoned the wise men and the sorcerers; and they also, the magicians of Egypt, did the same by their secret arts.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 7, 12, 'Each one threw down his staff, and they became snakes; but Aaron"s staff swallowed up theirs.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 7, 13, 'Still Pharaoh"s heart was hardened, and he would not listen to them, as the LORD had said.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 7, 14, 'Then the LORD said to Moses, "Pharaoh"s heart is hardened; he refuses to let the people go.', 'en', 'NRSV-CE', 'The First Plague: Water Turned to Blood'),
(2, 'Kel', 'Exodus', 7, 15, 'Go to Pharaoh in the morning, as he is going out to the water; stand by at the river bank to meet him, and take in your hand the staff that was turned into a snake.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 7, 16, 'Say to him, "The LORD, the God of the Hebrews, sent me to you to say, "Let my people go, so that they may worship me in the wilderness." But until now you have not listened.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 7, 17, 'Thus says the LORD, "By this you shall know that I am the LORD." See, with the staff that is in my hand I will strike the water that is in the Nile, and it shall be turned to blood.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 7, 18, 'The fish in the river shall die, the river itself shall stink, and the Egyptians shall be unable to drink water from the Nile.""', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 7, 19, 'The LORD said to Moses, "Say to Aaron, "Take your staff and stretch out your hand over the waters of Egypt--over its rivers, its canals, and its ponds, and all its pools of water--so that they may become blood; and there shall be blood throughout the whole land of Egypt, even in vessels of wood and in vessels of stone.""', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 7, 20, 'Moses and Aaron did just as the LORD commanded. In the sight of Pharaoh and of his officials he lifted up the staff and struck the water in the river, and all the water in the river was turned into blood,', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 7, 21, 'and the fish in the river died. The river stank so that the Egyptians could not drink its water, and there was blood throughout the whole land of Egypt.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 7, 22, 'But the magicians of Egypt did the same by their secret arts; so Pharaoh"s heart remained hardened, and he would not listen to them, as the LORD had said.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 7, 23, 'Pharaoh turned and went into his house, and he did not take even this to heart.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 7, 24, 'And all the Egyptians had to dig along the Nile for water to drink, for they could not drink the water of the river.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 7, 25, 'Seven days passed after the LORD had struck the Nile.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(2, 'Kel', 'Exodus', 8, 1, 'Then the LORD said to Moses, "Go to Pharaoh and say to him, "Thus says the LORD: Let my people go, so that they may worship me.', 'en', 'NRSV-CE', 'The Second Plague: Frogs'),
(2, 'Kel', 'Exodus', 8, 2, 'If you refuse to let them go, I will plague your whole country with frogs.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 8, 3, 'The river shall swarm with frogs; they shall come up into your palace, into your bedchamber and your bed, and into the houses of your officials and of your people, and into your ovens and your kneading bowls.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 8, 4, 'The frogs shall come up on you and on your people and on all your officials.""', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 8, 5, 'And the LORD said to Moses, "Say to Aaron, "Stretch out your hand with your staff over the rivers, the canals, and the pools, and make frogs come up on the land of Egypt.""', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 8, 6, 'So Aaron stretched out his hand over the waters of Egypt; and the frogs came up and covered the land of Egypt.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 8, 7, 'But the magicians did the same by their secret arts, and brought frogs up on the land of Egypt.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 8, 8, 'Then Pharaoh called Moses and Aaron, and said, "Pray to the LORD to take away the frogs from me and my people, and I will let the people go to sacrifice to the LORD."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 8, 9, 'Moses said to Pharaoh, "Kindly tell me when I am to pray for you and for your officials and for your people, that the frogs may be removed from you and your houses and be left only in the Nile."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 8, 10, 'And he said, "Tomorrow." Moses said, "As you say! So that you may know that there is no one like the LORD our God,', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 8, 11, 'the frogs shall leave you and your houses and your officials and your people; they shall be left only in the Nile."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 8, 12, 'Then Moses and Aaron went out from Pharaoh; and Moses cried out to the LORD concerning the frogs that he had brought upon Pharaoh.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 8, 13, 'And the LORD did as Moses requested: the frogs died in the houses, the courtyards, and the fields.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 8, 14, 'And they gathered them together in heaps, and the land stank.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 8, 15, 'But when Pharaoh saw that there was a respite, he hardened his heart, and would not listen to them, just as the LORD had said.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 8, 16, 'Then the LORD said to Moses, "Say to Aaron, "Stretch out your staff and strike the dust of the earth, so that it may become gnats throughout the whole land of Egypt.""', 'en', 'NRSV-CE', 'The Third Plague: Gnats'),
(2, 'Kel', 'Exodus', 8, 17, 'And they did so; Aaron stretched out his hand with his staff and struck the dust of the earth, and gnats came on humans and animals alike; all the dust of the earth turned into gnats throughout the whole land of Egypt.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 8, 18, 'The magicians tried to produce gnats by their secret arts, but they could not. There were gnats on both humans and animals.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 8, 19, 'And the magicians said to Pharaoh, "This is the finger of God!" But Pharaoh"s heart was hardened, and he would not listen to them, just as the LORD had said.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 8, 20, 'Then the LORD said to Moses, "Rise early in the morning and present yourself before Pharaoh, as he goes out to the water, and say to him, "Thus says the LORD: Let my people go, so that they may worship me.', 'en', 'NRSV-CE', 'The Fourth Plague: Flies'),
(2, 'Kel', 'Exodus', 8, 21, 'For if you will not let my people go, I will send swarms of flies on you, your officials, and your people, and into your houses; and the houses of the Egyptians shall be filled with swarms of flies; so also the land where they live.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 8, 22, 'But on that day I will set apart the land of Goshen, where my people live, so that no swarms of flies shall be there, that you may know that I the LORD am in this land.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 8, 23, 'Thus I will make a distinction between my people and your people. This sign shall appear tomorrow.""', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 8, 24, 'The LORD did so, and great swarms of flies came into the house of Pharaoh and into his officials" houses; in all of Egypt the land was ruined because of the flies.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 8, 25, 'Then Pharaoh summoned Moses and Aaron, and said, "Go, sacrifice to your God within the land."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 8, 26, 'But Moses said, "It would not be right to do so; for the sacrifices that we offer to the LORD our God are offensive to the Egyptians. If we offer in the sight of the Egyptians sacrifices that are offensive to them, will they not stone us?', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 8, 27, 'We must go a three days" journey into the wilderness and sacrifice to the LORD our God as he commands us."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 8, 28, 'So Pharaoh said, "I will let you go to sacrifice to the LORD your God in the wilderness, provided you do not go very far away. Pray for me."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 8, 29, 'Then Moses said, "As soon as I leave you, I will pray to the LORD that the swarms of flies may depart tomorrow from Pharaoh, from his officials, and from his people; only do not let Pharaoh again deal falsely by not letting the people go to sacrifice to the LORD."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 8, 30, 'So Moses went out from Pharaoh and prayed to the LORD.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 8, 31, 'And the LORD did as Moses asked: he removed the swarms of flies from Pharaoh, from his officials, and from his people; not one remained.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 8, 32, 'But Pharaoh hardened his heart this time also, and would not let the people go.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(2, 'Kel', 'Exodus', 9, 1, 'Then the LORD said to Moses, "Go to Pharaoh, and say to him, "Thus says the LORD, the God of the Hebrews: Let my people go, so that they may worship me.', 'en', 'NRSV-CE', 'The Fifth Plague: Livestock Diseased'),
(2, 'Kel', 'Exodus', 9, 2, 'For if you refuse to let them go and still hold them,', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 9, 3, 'the hand of the LORD will strike with a deadly pestilence your livestock in the field: the horses, the donkeys, the camels, the herds, and the flocks.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 9, 4, 'But the LORD will make a distinction between the livestock of Israel and the livestock of Egypt, so that nothing shall die of all that belongs to the Israelites.""', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 9, 5, 'The LORD set a time, saying, "Tomorrow the LORD will do this thing in the land."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 9, 6, 'And on the next day the LORD did so; all the livestock of the Egyptians died, but of the livestock of the Israelites not one died.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 9, 7, 'Pharaoh inquired and found that not one of the livestock of the Israelites was dead. But the heart of Pharaoh was hardened, and he would not let the people go.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 9, 8, 'Then the LORD said to Moses and Aaron, "Take handfuls of soot from the kiln, and let Moses throw it in the air in the sight of Pharaoh.', 'en', 'NRSV-CE', 'The Sixth Plague: Boils'),
(2, 'Kel', 'Exodus', 9, 9, 'It shall become fine dust all over the land of Egypt, and shall cause festering boils on humans and animals throughout the whole land of Egypt."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 9, 10, 'So they took soot from the kiln, and stood before Pharaoh, and Moses threw it in the air, and it caused festering boils on humans and animals.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 9, 11, 'The magicians could not stand before Moses because of the boils, for the boils afflicted the magicians as well as all the Egyptians.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 9, 12, 'But the LORD hardened the heart of Pharaoh, and he would not listen to them, just as the LORD had spoken to Moses.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 9, 13, 'Then the LORD said to Moses, "Rise up early in the morning and present yourself before Pharaoh, and say to him, "Thus says the LORD, the God of the Hebrews: Let my people go, so that they may worship me.', 'en', 'NRSV-CE', 'The Seventh Plague: Thunder and Hail'),
(2, 'Kel', 'Exodus', 9, 14, 'For this time I will send all my plagues upon you yourself, and upon your officials, and upon your people, so that you may know that there is no one like me in all the earth.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 9, 15, 'For by now I could have stretched out my hand and struck you and your people with pestilence, and you would have been cut off from the earth.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 9, 16, 'But this is why I have let you live: to show you my power, and to make my name resound through all the earth.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 9, 17, 'You are still exalting yourself against my people, and will not let them go.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 9, 18, 'Tomorrow at this time I will cause the heaviest hail to fall that has ever fallen in Egypt from the day it was founded until now.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 9, 19, 'Send, therefore, and have your livestock and everything that you have in the open field brought to a secure place; every human or animal that is in the open field and is not brought under shelter will die when the hail comes down upon them.""', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 9, 20, 'Those officials of Pharaoh who feared the word of the LORD hurried their slaves and livestock off to a secure place.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 9, 21, 'Those who did not regard the word of the LORD left their slaves and livestock in the open field.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 9, 22, 'The LORD said to Moses, "Stretch out your hand toward heaven so that hail may fall on the whole land of Egypt, on humans and animals and all the plants of the field in the land of Egypt."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 9, 23, 'Then Moses stretched out his staff toward heaven, and the LORD sent thunder and hail, and fire came down on the earth. And the LORD rained hail on the land of Egypt;', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 9, 24, 'there was hail with fire flashing continually in the midst of it, such heavy hail as had never fallen in all the land of Egypt since it became a nation.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 9, 25, 'The hail struck down everything that was in the open field throughout all the land of Egypt, both human and animal; the hail also struck down all the plants of the field, and shattered every tree in the field.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 9, 26, 'Only in the land of Goshen, where the Israelites were, there was no hail.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 9, 27, 'Then Pharaoh summoned Moses and Aaron, and said to them, "This time I have sinned; the LORD is in the right, and I and my people are in the wrong.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 9, 28, 'Pray to the LORD! Enough of God"s thunder and hail! I will let you go; you need stay no longer."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 9, 29, 'Moses said to him, "As soon as I have gone out of the city, I will stretch out my hands to the LORD; the thunder will cease, and there will be no more hail, so that you may know that the earth is the LORD"s.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 9, 30, 'But as for you and your officials, I know that you do not yet fear the LORD God."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 9, 31, '(Now the flax and the barley were ruined, for the barley was in the ear and the flax was in bud.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 9, 32, 'But the wheat and the spelt were not ruined, for they are late in coming up.)', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 9, 33, 'So Moses left Pharaoh, went out of the city, and stretched out his hands to the LORD; then the thunder and the hail ceased, and the rain no longer poured down on the earth.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 9, 34, 'But when Pharaoh saw that the rain and the hail and the thunder had ceased, he sinned once more and hardened his heart, he and his officials.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 9, 35, 'So the heart of Pharaoh was hardened, and he would not let the Israelites go, just as the LORD had spoken through Moses.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(2, 'Kel', 'Exodus', 10, 1, 'Then the LORD said to Moses, "Go to Pharaoh; for I have hardened his heart and the heart of his officials, in order that I may show these signs of mine among them,', 'en', 'NRSV-CE', 'The Eighth Plague: Locusts'),
(2, 'Kel', 'Exodus', 10, 2, 'and that you may tell your children and grandchildren how I have made fools of the Egyptians and what signs I have done among them--so that you may know that I am the LORD."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 10, 3, 'So Moses and Aaron went to Pharaoh, and said to him, "Thus says the LORD, the God of the Hebrews, "How long will you refuse to humble yourself before me? Let my people go, so that they may worship me.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 10, 4, 'For if you refuse to let my people go, tomorrow I will bring locusts into your country.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 10, 5, 'They shall cover the surface of the land, so that no one will be able to see the land. They shall devour the last remnant left you after the hail, and they shall devour every tree of yours that grows in the field.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 10, 6, 'They shall fill your houses, and the houses of all your officials and of all the Egyptians--something that neither your parents nor your grandparents have seen, from the day they came on earth to this day."" Then he turned and went out from Pharaoh.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 10, 7, 'Pharaoh"s officials said to him, "How long shall this fellow be a snare to us? Let the people go, so that they may worship the LORD their God; do you not yet understand that Egypt is ruined?"', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 10, 8, 'So Moses and Aaron were brought back to Pharaoh, and he said to them, "Go, worship the LORD your God! But which ones are to go?"', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 10, 9, 'Moses said, "We will go with our young and our old; we will go with our sons and daughters and with our flocks and herds, because we have the LORD"s festival to celebrate."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 10, 10, 'He said to them, "The LORD indeed will be with you, if ever I let your little ones go with you! Plainly, you have some evil purpose in mind.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 10, 11, 'No, never! Your men may go and worship the LORD, for that is what you are asking." And they were driven out from Pharaoh"s presence.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 10, 12, 'Then the LORD said to Moses, "Stretch out your hand over the land of Egypt, so that the locusts may come upon it and eat every plant in the land, all that the hail has left."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 10, 13, 'So Moses stretched out his staff over the land of Egypt, and the LORD brought an east wind upon the land all that day and all that night; when morning came, the east wind had brought the locusts.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 10, 14, 'The locusts came upon all the land of Egypt and settled on the whole country of Egypt, such a dense swarm of locusts as had never been before, nor ever shall be again.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 10, 15, 'They covered the surface of the whole land, so that the land was black; and they ate all the plants in the land and all the fruit of the trees that the hail had left; nothing green was left, no tree, no plant in the field, in all the land of Egypt.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 10, 16, 'Pharaoh hurriedly summoned Moses and Aaron and said, "I have sinned against the LORD your God, and against you.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 10, 17, 'Do forgive my sin just this once, and pray to the LORD your God that at the least he remove this deadly thing from me."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 10, 18, 'So he went out from Pharaoh and prayed to the LORD.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 10, 19, 'The LORD changed the wind into a very strong west wind, which lifted the locusts and drove them into the Red Sea; not a single locust was left in all the country of Egypt.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 10, 20, 'But the LORD hardened Pharaoh"s heart, and he would not let the Israelites go.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 10, 21, 'Then the LORD said to Moses, "Stretch out your hand toward heaven so that there may be darkness over the land of Egypt, a darkness that can be felt."', 'en', 'NRSV-CE', 'The Ninth Plague: Darkness'),
(2, 'Kel', 'Exodus', 10, 22, 'So Moses stretched out his hand toward heaven, and there was dense darkness in all the land of Egypt for three days.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 10, 23, 'People could not see one another, and for three days they could not move from where they were; but all the Israelites had light where they lived.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 10, 24, 'Then Pharaoh summoned Moses, and said, "Go, worship the LORD. Only your flocks and your herds shall remain behind. Even your children may go with you."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 10, 25, 'But Moses said, "You must also let us have sacrifices and burnt offerings to sacrifice to the LORD our God.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 10, 26, 'Our livestock also must go with us; not a hoof shall be left behind, for we must choose some of them for the worship of the LORD our God, and we will not know what to use to worship the LORD until we arrive there."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 10, 27, 'But the LORD hardened Pharaoh"s heart, and he was unwilling to let them go.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 10, 28, 'Then Pharaoh said to him, "Get away from me! Take care that you do not see my face again, for on the day you see my face you shall die."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 10, 29, 'Moses said, "Just as you say! I will never see your face again."', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(2, 'Kel', 'Exodus', 11, 1, 'The LORD said to Moses, "I will bring one more plague upon Pharaoh and upon Egypt; afterwards he will let you go from here; indeed, when he lets you go, he will drive you away.', 'en', 'NRSV-CE', 'Warning of the Final Plague'),
(2, 'Kel', 'Exodus', 11, 2, 'Tell the people that every man is to ask his neighbor and every woman is to ask her neighbor for objects of silver and gold."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 11, 3, 'The LORD gave the people favor in the sight of the Egyptians. Moreover, Moses himself was a man of great importance in the land of Egypt, in the sight of Pharaoh"s officials and in the sight of the people.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 11, 4, 'Moses said, "Thus says the LORD: About midnight I will go out through Egypt.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 11, 5, 'Every firstborn in the land of Egypt shall die, from the firstborn of Pharaoh who sits on his throne to the firstborn of the female slave who is behind the handmill, and all the firstborn of the livestock.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 11, 6, 'Then there will be a loud cry throughout the whole land of Egypt, such as has never been or will ever be again.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 11, 7, 'But not a dog shall growl at any of the Israelites--not at people, not at animals--so that you may know that the LORD makes a distinction between Egypt and Israel.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 11, 8, 'Then all these officials of yours shall come down to me, and bow low to me, saying, "Leave us, you and all the people who follow you." After that I will leave." And in hot anger he left Pharaoh.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 11, 9, 'The LORD said to Moses, "Pharaoh will not listen to you, in order that my wonders may be multiplied in the land of Egypt."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 11, 10, 'Moses and Aaron performed all these wonders before Pharaoh; but the LORD hardened Pharaoh"s heart, and he did not let the people of Israel go out of his land.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(2, 'Kel', 'Exodus', 12, 1, 'The LORD said to Moses and Aaron in the land of Egypt:', 'en', 'NRSV-CE', 'The First Passover Instituted'),
(2, 'Kel', 'Exodus', 12, 2, 'This month shall mark for you the beginning of months; it shall be the first month of the year for you.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 12, 3, 'Tell the whole congregation of Israel that on the tenth of this month they are to take a lamb for each family, a lamb for each household.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 12, 4, 'If a household is too small for a whole lamb, it shall join its closest neighbor in obtaining one; the lamb shall be divided in proportion to the number of people who eat of it.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 12, 5, 'Your lamb shall be without blemish, a year-old male; you may take it from the sheep or from the goats.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 12, 6, 'You shall keep it until the fourteenth day of this month; then the whole assembled congregation of Israel shall slaughter it at twilight.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 12, 7, 'They shall take some of the blood and put it on the two doorposts and the lintel of the houses in which they eat it.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 12, 8, 'They shall eat the lamb that same night; they shall eat it roasted over the fire with unleavened bread and bitter herbs.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 12, 9, 'Do not eat any of it raw or boiled in water, but roasted over the fire, with its head, legs, and inner organs.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 12, 10, 'You shall let none of it remain until the morning; anything that remains until the morning you shall burn.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 12, 11, 'This is how you shall eat it: your loins girded, your sandals on your feet, and your staff in your hand; and you shall eat it hurriedly. It is the passover of the LORD.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 12, 12, 'For I will pass through the land of Egypt that night, and I will strike down every firstborn in the land of Egypt, both human beings and animals; on all the gods of Egypt I will execute judgments: I am the LORD.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 12, 13, 'The blood shall be a sign for you on the houses where you live: when I see the blood, I will pass over you, and no plague shall destroy you when I strike the land of Egypt.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 12, 14, 'This day shall be a day of remembrance for you. You shall celebrate it as a festival to the LORD; throughout your generations you shall observe it as a perpetual ordinance.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 12, 15, 'Seven days you shall eat unleavened bread; on the first day you shall remove leaven from your houses, for whoever eats leavened bread from the first day until the seventh day shall be cut off from Israel.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 12, 16, 'On the first day you shall hold a solemn assembly, and on the seventh day a solemn assembly; no work shall be done on those days; only what everyone must eat, that alone may be prepared by you.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 12, 17, 'You shall observe the festival of unleavened bread, for on this very day I brought your companies out of the land of Egypt: you shall observe this day throughout your generations as a perpetual ordinance.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 12, 18, 'In the first month, from the evening of the fourteenth day until the evening of the twenty-first day, you shall eat unleavened bread.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 12, 19, 'For seven days no leaven shall be found in your houses; for whoever eats what is leavened shall be cut off from the congregation of Israel, whether an alien or a native of the land.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 12, 20, 'You shall eat nothing leavened; in all your settlements you shall eat unleavened bread.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 12, 21, 'Then Moses called all the elders of Israel and said to them, "Go, select lambs for your families, and slaughter the passover lamb.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 12, 22, 'Take a bunch of hyssop, dip it in the blood that is in the basin, and touch the lintel and the two doorposts with the blood in the basin. None of you shall go outside the door of your house until morning.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 12, 23, 'For the LORD will pass through to strike down the Egyptians; when he sees the blood on the lintel and on the two doorposts, the LORD will pass over that door and will not allow the destroyer to enter your houses to strike you down.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 12, 24, 'You shall observe this rite as a perpetual ordinance for you and your children.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 12, 25, 'When you come to the land that the LORD will give you, as he has promised, you shall keep this observance.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 12, 26, 'And when your children ask you, "What do you mean by this observance?"', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 12, 27, 'you shall say, "It is the passover sacrifice to the LORD, for he passed over the houses of the Israelites in Egypt, when he struck down the Egyptians but spared our houses."" And the people bowed down and worshiped.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 12, 28, 'The Israelites went and did just as the LORD had commanded Moses and Aaron.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 12, 29, 'At midnight the LORD struck down all the firstborn in the land of Egypt, from the firstborn of Pharaoh who sat on his throne to the firstborn of the prisoner who was in the dungeon, and all the firstborn of the livestock.', 'en', 'NRSV-CE', 'The Tenth Plague: Death of the Firstborn'),
(2, 'Kel', 'Exodus', 12, 30, 'Pharaoh arose in the night, he and all his officials and all the Egyptians; and there was a loud cry in Egypt, for there was not a house without someone dead.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 12, 31, 'Then he summoned Moses and Aaron in the night, and said, "Rise up, go away from my people, both you and the Israelites! Go, worship the LORD, as you said.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 12, 32, 'Take your flocks and your herds, as you said, and be gone. And bring a blessing on me too!"', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 12, 33, 'The Egyptians urged the people to hasten their departure from the land, for they said, "We shall all be dead."', 'en', 'NRSV-CE', 'The Exodus: From Rameses to Succoth'),
(2, 'Kel', 'Exodus', 12, 34, 'So the people took their dough before it was leavened, with their kneading bowls wrapped up in their cloaks on their shoulders.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 12, 35, 'The Israelites had done as Moses told them; they had asked the Egyptians for jewelry of silver and gold, and for clothing,', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 12, 36, 'and the LORD had given the people favor in the sight of the Egyptians, so that they let them have what they asked. And so they plundered the Egyptians.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 12, 37, 'The Israelites journeyed from Rameses to Succoth, about six hundred thousand men on foot, besides children.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 12, 38, 'A mixed crowd also went up with them, and livestock in great numbers, both flocks and herds.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 12, 39, 'They baked unleavened cakes of the dough that they had brought out of Egypt; it was not leavened, because they were driven out of Egypt and could not wait, nor had they prepared any provisions for themselves.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 12, 40, 'The time that the Israelites had lived in Egypt was four hundred thirty years.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 12, 41, 'At the end of four hundred thirty years, on that very day, all the companies of the LORD went out from the land of Egypt.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 12, 42, 'That was for the LORD a night of vigil, to bring them out of the land of Egypt. That same night is a vigil to be kept for the LORD by all the Israelites throughout their generations.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 12, 43, 'The LORD said to Moses and Aaron: This is the ordinance for the passover: no foreigner shall eat of it,', 'en', 'NRSV-CE', 'Directions for the Passover'),
(2, 'Kel', 'Exodus', 12, 44, 'but any slave who has been purchased may eat of it after he has been circumcised;', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 12, 45, 'no bound or hired servant may eat of it.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 12, 46, 'It shall be eaten in one house; you shall not take any of the animal outside the house, and you shall not break any of its bones.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 12, 47, 'The whole congregation of Israel shall celebrate it.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 12, 48, 'If an alien who resides with you wants to celebrate the passover to the LORD, all his males shall be circumcised; then he may draw near to celebrate it; he shall be regarded as a native of the land. But no uncircumcised person shall eat of it;', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 12, 49, 'there shall be one law for the native and for the alien who resides among you.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 12, 50, 'All the Israelites did just as the LORD had commanded Moses and Aaron.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 12, 51, 'That very day the LORD brought the Israelites out of the land of Egypt, company by company.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(2, 'Kel', 'Exodus', 13, 1, 'The LORD said to Moses:', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 13, 2, 'Consecrate to me all the firstborn; whatever is the first to open the womb among the Israelites, of human beings and animals, is mine.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 13, 3, 'Moses said to the people, "Remember this day on which you came out of Egypt, out of the house of slavery, because the LORD brought you out from there by strength of hand; no leavened bread shall be eaten.', 'en', 'NRSV-CE', 'The Festival of Unleavened Bread'),
(2, 'Kel', 'Exodus', 13, 4, 'Today, in the month of Abib, you are going out.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 13, 5, 'When the LORD brings you into the land of the Canaanites, the Hittites, the Amorites, the Hivites, and the Jebusites, which he swore to your ancestors to give you, a land flowing with milk and honey, you shall keep this observance in this month.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 13, 6, 'Seven days you shall eat unleavened bread, and on the seventh day there shall be a festival to the LORD.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 13, 7, 'Unleavened bread shall be eaten for seven days; no leavened bread shall be seen in your possession, and no leaven shall be seen among you in all your territory.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 13, 8, 'You shall tell your child on that day, "It is because of what the LORD did for me when I came out of Egypt."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 13, 9, 'It shall serve for you as a sign on your hand and as a reminder on your forehead, so that the teaching of the LORD may be on your lips; for with a strong hand the LORD brought you out of Egypt.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 13, 10, 'You shall keep this ordinance at its proper time from year to year.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 13, 11, '"When the LORD has brought you into the land of the Canaanites, as he swore to you and your ancestors, and has given it to you,', 'en', 'NRSV-CE', 'The Consecration of the Firstborn'),
(2, 'Kel', 'Exodus', 13, 12, 'you shall set apart to the LORD all that first opens the womb. All the firstborn of your livestock that are males shall be the LORD"s.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 13, 13, 'But every firstborn donkey you shall redeem with a sheep; if you do not redeem it, you must break its neck. Every firstborn male among your children you shall redeem.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 13, 14, 'When in the future your child asks you, "What does this mean?" you shall answer, "By strength of hand the LORD brought us out of Egypt, from the house of slavery.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 13, 15, 'When Pharaoh stubbornly refused to let us go, the LORD killed all the firstborn in the land of Egypt, from human firstborn to the firstborn of animals. Therefore I sacrifice to the LORD every male that first opens the womb, but every firstborn of my sons I redeem."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 13, 16, 'It shall serve as a sign on your hand and as an emblem on your forehead that by strength of hand the LORD brought us out of Egypt."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 13, 17, 'When Pharaoh let the people go, God did not lead them by way of the land of the Philistines, although that was nearer; for God thought, "If the people face war, they may change their minds and return to Egypt."', 'en', 'NRSV-CE', 'The Pillars of Cloud and Fire'),
(2, 'Kel', 'Exodus', 13, 18, 'So God led the people by the roundabout way of the wilderness toward the Red Sea. The Israelites went up out of the land of Egypt prepared for battle.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 13, 19, 'And Moses took with him the bones of Joseph who had required a solemn oath of the Israelites, saying, "God will surely take notice of you, and then you must carry my bones with you from here."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 13, 20, 'They set out from Succoth, and camped at Etham, on the edge of the wilderness.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 13, 21, 'The LORD went in front of them in a pillar of cloud by day, to lead them along the way, and in a pillar of fire by night, to give them light, so that they might travel by day and by night.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 13, 22, 'Neither the pillar of cloud by day nor the pillar of fire by night left its place in front of the people.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(2, 'Kel', 'Exodus', 14, 1, 'Then the LORD said to Moses:', 'en', 'NRSV-CE', 'Crossing the Red Sea'),
(2, 'Kel', 'Exodus', 14, 2, 'Tell the Israelites to turn back and camp in front of Pi-hahiroth, between Migdol and the sea, in front of Baal-zephon; you shall camp opposite it, by the sea.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 14, 3, 'Pharaoh will say of the Israelites, "They are wandering aimlessly in the land; the wilderness has closed in on them."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 14, 4, 'I will harden Pharaoh"s heart, and he will pursue them, so that I will gain glory for myself over Pharaoh and all his army; and the Egyptians shall know that I am the LORD. And they did so.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 14, 5, 'When the king of Egypt was told that the people had fled, the minds of Pharaoh and his officials were changed toward the people, and they said, "What have we done, letting Israel leave our service?"', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 14, 6, 'So he had his chariot made ready, and took his army with him;', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 14, 7, 'he took six hundred picked chariots and all the other chariots of Egypt with officers over all of them.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 14, 8, 'The LORD hardened the heart of Pharaoh king of Egypt and he pursued the Israelites, who were going out boldly.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 14, 9, 'The Egyptians pursued them, all Pharaoh"s horses and chariots, his chariot drivers and his army; they overtook them camped by the sea, by Pi-hahiroth, in front of Baal-zephon.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 14, 10, 'As Pharaoh drew near, the Israelites looked back, and there were the Egyptians advancing on them. In great fear the Israelites cried out to the LORD.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 14, 11, 'They said to Moses, "Was it because there were no graves in Egypt that you have taken us away to die in the wilderness? What have you done to us, bringing us out of Egypt?', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 14, 12, 'Is this not the very thing we told you in Egypt, "Let us alone and let us serve the Egyptians"? For it would have been better for us to serve the Egyptians than to die in the wilderness."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 14, 13, 'But Moses said to the people, "Do not be afraid, stand firm, and see the deliverance that the LORD will accomplish for you today; for the Egyptians whom you see today you shall never see again.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 14, 14, 'The LORD will fight for you, and you have only to keep still."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 14, 15, 'Then the LORD said to Moses, "Why do you cry out to me? Tell the Israelites to go forward.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 14, 16, 'But you lift up your staff, and stretch out your hand over the sea and divide it, that the Israelites may go into the sea on dry ground.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 14, 17, 'Then I will harden the hearts of the Egyptians so that they will go in after them; and so I will gain glory for myself over Pharaoh and all his army, his chariots, and his chariot drivers.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 14, 18, 'And the Egyptians shall know that I am the LORD, when I have gained glory for myself over Pharaoh, his chariots, and his chariot drivers."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 14, 19, 'The angel of God who was going before the Israelite army moved and went behind them; and the pillar of cloud moved from in front of them and took its place behind them.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 14, 20, 'It came between the army of Egypt and the army of Israel. And so the cloud was there with the darkness, and it lit up the night; one did not come near the other all night.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 14, 21, 'Then Moses stretched out his hand over the sea. The LORD drove the sea back by a strong east wind all night, and turned the sea into dry land; and the waters were divided.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 14, 22, 'The Israelites went into the sea on dry ground, the waters forming a wall for them on their right and on their left.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 14, 23, 'The Egyptians pursued, and went into the sea after them, all of Pharaoh"s horses, chariots, and chariot drivers.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 14, 24, 'At the morning watch the LORD in the pillar of fire and cloud looked down upon the Egyptian army, and threw the Egyptian army into panic.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 14, 25, 'He clogged their chariot wheels so that they turned with difficulty. The Egyptians said, "Let us flee from the Israelites, for the LORD is fighting for them against Egypt."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 14, 26, 'Then the LORD said to Moses, "Stretch out your hand over the sea, so that the water may come back upon the Egyptians, upon their chariots and chariot drivers."', 'en', 'NRSV-CE', 'The Pursuers Drowned'),
(2, 'Kel', 'Exodus', 14, 27, 'So Moses stretched out his hand over the sea, and at dawn the sea returned to its normal depth. As the Egyptians fled before it, the LORD tossed the Egyptians into the sea.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 14, 28, 'The waters returned and covered the chariots and the chariot drivers, the entire army of Pharaoh that had followed them into the sea; not one of them remained.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 14, 29, 'But the Israelites walked on dry ground through the sea, the waters forming a wall for them on their right and on their left.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 14, 30, 'Thus the LORD saved Israel that day from the Egyptians; and Israel saw the Egyptians dead on the seashore.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 14, 31, 'Israel saw the great work that the LORD did against the Egyptians. So the people feared the LORD and believed in the LORD and in his servant Moses.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(2, 'Kel', 'Exodus', 15, 1, 'Then Moses and the Israelites sang this song to the LORD:
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(2, 'Kel', 'Exodus', 16, 1, 'The whole congregation of the Israelites set out from Elim; and Israel came to the wilderness of Sin, which is between Elim and Sinai, on the fifteenth day of the second month after they had departed from the land of Egypt.', 'en', 'NRSV-CE', 'Bread from Heaven'),
(2, 'Kel', 'Exodus', 16, 2, 'The whole congregation of the Israelites complained against Moses and Aaron in the wilderness.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 16, 3, 'The Israelites said to them, "If only we had died by the hand of the LORD in the land of Egypt, when we sat by the fleshpots and ate our fill of bread; for you have brought us out into this wilderness to kill this whole assembly with hunger."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 16, 4, 'Then the LORD said to Moses, "I am going to rain bread from heaven for you, and each day the people shall go out and gather enough for that day. In that way I will test them, whether they will follow my instruction or not.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 16, 5, 'On the sixth day, when they prepare what they bring in, it will be twice as much as they gather on other days."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 16, 6, 'So Moses and Aaron said to all the Israelites, "In the evening you shall know that it was the LORD who brought you out of the land of Egypt,', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 16, 7, 'and in the morning you shall see the glory of the LORD, because he has heard your complaining against the LORD. For what are we, that you complain against us?"', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 16, 8, 'And Moses said, "When the LORD gives you meat to eat in the evening and your fill of bread in the morning, because the LORD has heard the complaining that you utter against him--what are we? Your complaining is not against us but against the LORD."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 16, 9, 'Then Moses said to Aaron, "Say to the whole congregation of the Israelites, "Draw near to the LORD, for he has heard your complaining.""', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 16, 10, 'And as Aaron spoke to the whole congregation of the Israelites, they looked toward the wilderness, and the glory of the LORD appeared in the cloud.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 16, 11, 'The LORD spoke to Moses and said,', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 16, 12, '"I have heard the complaining of the Israelites; say to them, "At twilight you shall eat meat, and in the morning you shall have your fill of bread; then you shall know that I am the LORD your God.""', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 16, 13, 'In the evening quails came up and covered the camp; and in the morning there was a layer of dew around the camp.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 16, 14, 'When the layer of dew lifted, there on the surface of the wilderness was a fine flaky substance, as fine as frost on the ground.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 16, 15, 'When the Israelites saw it, they said to one another, "What is it?" For they did not know what it was. Moses said to them, "It is the bread that the LORD has given you to eat.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 16, 16, 'This is what the LORD has commanded: "Gather as much of it as each of you needs, an omer to a person according to the number of persons, all providing for those in their own tents.""', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 16, 17, 'The Israelites did so, some gathering more, some less.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 16, 18, 'But when they measured it with an omer, those who gathered much had nothing over, and those who gathered little had no shortage; they gathered as much as each of them needed.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 16, 19, 'And Moses said to them, "Let no one leave any of it over until morning."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 16, 20, 'But they did not listen to Moses; some left part of it until morning, and it bred worms and became foul. And Moses was angry with them.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 16, 21, 'Morning by morning they gathered it, as much as each needed; but when the sun grew hot, it melted.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 16, 22, 'On the sixth day they gathered twice as much food, two omers apiece. When all the leaders of the congregation came and told Moses,', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 16, 23, 'he said to them, "This is what the LORD has commanded: "Tomorrow is a day of solemn rest, a holy sabbath to the LORD; bake what you want to bake and boil what you want to boil, and all that is left over put aside to be kept until morning.""', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 16, 24, 'So they put it aside until morning, as Moses commanded them; and it did not become foul, and there were no worms in it.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 16, 25, 'Moses said, "Eat it today, for today is a sabbath to the LORD; today you will not find it in the field.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 16, 26, 'Six days you shall gather it; but on the seventh day, which is a sabbath, there will be none."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 16, 27, 'On the seventh day some of the people went out to gather, and they found none.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 16, 28, 'The LORD said to Moses, "How long will you refuse to keep my commandments and instructions?', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 16, 29, 'See! The LORD has given you the sabbath, therefore on the sixth day he gives you food for two days; each of you stay where you are; do not leave your place on the seventh day."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 16, 30, 'So the people rested on the seventh day.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 16, 31, 'The house of Israel called it manna; it was like coriander seed, white, and the taste of it was like wafers made with honey.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 16, 32, 'Moses said, "This is what the LORD has commanded: "Let an omer of it be kept throughout your generations, in order that they may see the food with which I fed you in the wilderness, when I brought you out of the land of Egypt.""', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 16, 33, 'And Moses said to Aaron, "Take a jar, and put an omer of manna in it, and place it before the LORD, to be kept throughout your generations."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 16, 34, 'As the LORD commanded Moses, so Aaron placed it before the covenant, for safekeeping.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 16, 35, 'The Israelites ate manna forty years, until they came to a habitable land; they ate manna, until they came to the border of the land of Canaan.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 16, 36, 'An omer is a tenth of an ephah.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(2, 'Kel', 'Exodus', 17, 1, 'From the wilderness of Sin the whole congregation of the Israelites journeyed by stages, as the LORD commanded. They camped at Rephidim, but there was no water for the people to drink.', 'en', 'NRSV-CE', 'Water from the Rock'),
(2, 'Kel', 'Exodus', 17, 2, 'The people quarreled with Moses, and said, "Give us water to drink." Moses said to them, "Why do you quarrel with me? Why do you test the LORD?"', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 17, 3, 'But the people thirsted there for water; and the people complained against Moses and said, "Why did you bring us out of Egypt, to kill us and our children and livestock with thirst?"', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 17, 4, 'So Moses cried out to the LORD, "What shall I do with this people? They are almost ready to stone me."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 17, 5, 'The LORD said to Moses, "Go on ahead of the people, and take some of the elders of Israel with you; take in your hand the staff with which you struck the Nile, and go.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 17, 6, 'I will be standing there in front of you on the rock at Horeb. Strike the rock, and water will come out of it, so that the people may drink." Moses did so, in the sight of the elders of Israel.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 17, 7, 'He called the place Massah and Meribah, because the Israelites quarreled and tested the LORD, saying, "Is the LORD among us or not?"', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 17, 8, 'Then Amalek came and fought with Israel at Rephidim.', 'en', 'NRSV-CE', 'Amalek Attacks Israel and Is Defeated'),
(2, 'Kel', 'Exodus', 17, 9, 'Moses said to Joshua, "Choose some men for us and go out, fight with Amalek. Tomorrow I will stand on the top of the hill with the staff of God in my hand."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 17, 10, 'So Joshua did as Moses told him, and fought with Amalek, while Moses, Aaron, and Hur went up to the top of the hill.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 17, 11, 'Whenever Moses held up his hand, Israel prevailed; and whenever he lowered his hand, Amalek prevailed.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 17, 12, 'But Moses" hands grew weary; so they took a stone and put it under him, and he sat on it. Aaron and Hur held up his hands, one on one side, and the other on the other side; so his hands were steady until the sun set.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 17, 13, 'And Joshua defeated Amalek and his people with the sword.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 17, 14, 'Then the LORD said to Moses, "Write this as a reminder in a book and recite it in the hearing of Joshua: I will utterly blot out the remembrance of Amalek from under heaven."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 17, 15, 'And Moses built an altar and called it, The LORD is my banner.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 17, 16, 'He said, "A hand upon the banner of the LORD! The LORD will have war with Amalek from generation to generation."', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(2, 'Kel', 'Exodus', 18, 1, 'Jethro, the priest of Midian, Moses" father-in-law, heard of all that God had done for Moses and for his people Israel, how the LORD had brought Israel out of Egypt.', 'en', 'NRSV-CE', 'Jethro"s Advice'),
(2, 'Kel', 'Exodus', 18, 2, 'After Moses had sent away his wife Zipporah, his father-in-law Jethro took her back,', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 18, 3, 'along with her two sons. The name of the one was Gershom (for he said, "I have been an alien in a foreign land"),', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 18, 4, 'and the name of the other, Eliezer (for he said, "The God of my father was my help, and delivered me from the sword of Pharaoh").', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 18, 5, 'Jethro, Moses" father-in-law, came into the wilderness where Moses was encamped at the mountain of God, bringing Moses" sons and wife to him.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 18, 6, 'He sent word to Moses, "I, your father-in-law Jethro, am coming to you, with your wife and her two sons."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 18, 7, 'Moses went out to meet his father-in-law; he bowed down and kissed him; each asked after the other"s welfare, and they went into the tent.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 18, 8, 'Then Moses told his father-in-law all that the LORD had done to Pharaoh and to the Egyptians for Israel"s sake, all the hardship that had beset them on the way, and how the LORD had delivered them.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 18, 9, 'Jethro rejoiced for all the good that the LORD had done to Israel, in delivering them from the Egyptians.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 18, 10, 'Jethro said, "Blessed be the LORD, who has delivered you from the Egyptians and from Pharaoh.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 18, 11, 'Now I know that the LORD is greater than all gods, because he delivered the people from the Egyptians, when they dealt arrogantly with them."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 18, 12, 'And Jethro, Moses" father-in-law, brought a burnt offering and sacrifices to God; and Aaron came with all the elders of Israel to eat bread with Moses" father-in-law in the presence of God.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 18, 13, 'The next day Moses sat as judge for the people, while the people stood around him from morning until evening.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 18, 14, 'When Moses" father-in-law saw all that he was doing for the people, he said, "What is this that you are doing for the people? Why do you sit alone, while all the people stand around you from morning until evening?"', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 18, 15, 'Moses said to his father-in-law, "Because the people come to me to inquire of God.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 18, 16, 'When they have a dispute, they come to me and I decide between one person and another, and I make known to them the statutes and instructions of God."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 18, 17, 'Moses" father-in-law said to him, "What you are doing is not good.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 18, 18, 'You will surely wear yourself out, both you and these people with you. For the task is too heavy for you; you cannot do it alone.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 18, 19, 'Now listen to me. I will give you counsel, and God be with you! You should represent the people before God, and you should bring their cases before God;', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 18, 20, 'teach them the statutes and instructions and make known to them the way they are to go and the things they are to do.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 18, 21, 'You should also look for able men among all the people, men who fear God, are trustworthy, and hate dishonest gain; set such men over them as officers over thousands, hundreds, fifties, and tens.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 18, 22, 'Let them sit as judges for the people at all times; let them bring every important case to you, but decide every minor case themselves. So it will be easier for you, and they will bear the burden with you.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 18, 23, 'If you do this, and God so commands you, then you will be able to endure, and all these people will go to their home in peace."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 18, 24, 'So Moses listened to his father-in-law and did all that he had said.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 18, 25, 'Moses chose able men from all Israel and appointed them as heads over the people, as officers over thousands, hundreds, fifties, and tens.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 18, 26, 'And they judged the people at all times; hard cases they brought to Moses, but any minor case they decided themselves.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 18, 27, 'Then Moses let his father-in-law depart, and he went off to his own country.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(2, 'Kel', 'Exodus', 19, 1, 'On the third new moon after the Israelites had gone out of the land of Egypt, on that very day, they came into the wilderness of Sinai.', 'en', 'NRSV-CE', 'The Israelites Reach Mount Sinai'),
(2, 'Kel', 'Exodus', 19, 2, 'They had journeyed from Rephidim, entered the wilderness of Sinai, and camped in the wilderness; Israel camped there in front of the mountain.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 19, 3, 'Then Moses went up to God; the LORD called to him from the mountain, saying, "Thus you shall say to the house of Jacob, and tell the Israelites:', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 19, 4, 'You have seen what I did to the Egyptians, and how I bore you on eagles" wings and brought you to myself.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 19, 5, 'Now therefore, if you obey my voice and keep my covenant, you shall be my treasured possession out of all the peoples. Indeed, the whole earth is mine,', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 19, 6, 'but you shall be for me a priestly kingdom and a holy nation. These are the words that you shall speak to the Israelites."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 19, 7, 'So Moses came, summoned the elders of the people, and set before them all these words that the LORD had commanded him.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 19, 8, 'The people all answered as one: "Everything that the LORD has spoken we will do." Moses reported the words of the people to the LORD.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 19, 9, 'Then the LORD said to Moses, "I am going to come to you in a dense cloud, in order that the people may hear when I speak with you and so trust you ever after."
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(2, 'Kel', 'Exodus', 20, 1, 'Then God spoke all these words:', 'en', 'NRSV-CE', 'The Ten Commandments'),
(2, 'Kel', 'Exodus', 20, 2, 'I am the LORD your God, who brought you out of the land of Egypt, out of the house of slavery;', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 20, 3, 'you shall have no other gods before me.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 20, 4, 'You shall not make for yourself an idol, whether in the form of anything that is in heaven above, or that is on the earth beneath, or that is in the water under the earth.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 20, 5, 'You shall not bow down to them or worship them; for I the LORD your God am a jealous God, punishing children for the iniquity of parents, to the third and the fourth generation of those who reject me,', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 20, 6, 'but showing steadfast love to the thousandth generation of those who love me and keep my commandments.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 20, 7, 'You shall not make wrongful use of the name of the LORD your God, for the LORD will not acquit anyone who misuses his name.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 20, 8, 'Remember the sabbath day, and keep it holy.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 20, 9, 'Six days you shall labor and do all your work.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 20, 10, 'But the seventh day is a sabbath to the LORD your God; you shall not do any work--you, your son or your daughter, your male or female slave, your livestock, or the alien resident in your towns.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 20, 11, 'For in six days the LORD made heaven and earth, the sea, and all that is in them, but rested the seventh day; therefore the LORD blessed the sabbath day and consecrated it.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 20, 12, 'Honor your father and your mother, so that your days may be long in the land that the LORD your God is giving you.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 20, 13, 'You shall not murder.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 20, 14, 'You shall not commit adultery.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 20, 15, 'You shall not steal.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 20, 16, 'You shall not bear false witness against your neighbor.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 20, 17, 'You shall not covet your neighbor"s house; you shall not covet your neighbor"s wife, or male or female slave, or ox, or donkey, or anything that belongs to your neighbor.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 20, 18, 'When all the people witnessed the thunder and lightning, the sound of the trumpet, and the mountain smoking, they were afraid and trembled and stood at a distance,', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 20, 19, 'and said to Moses, "You speak to us, and we will listen; but do not let God speak to us, or we will die."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 20, 20, 'Moses said to the people, "Do not be afraid; for God has come only to test you and to put the fear of him upon you so that you do not sin."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 20, 21, 'Then the people stood at a distance, while Moses drew near to the thick darkness where God was.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 20, 22, 'The LORD said to Moses: Thus you shall say to the Israelites: "You have seen for yourselves that I spoke with you from heaven.', 'en', 'NRSV-CE', 'The Law concerning the Altar'),
(2, 'Kel', 'Exodus', 20, 23, 'You shall not make gods of silver alongside me, nor shall you make for yourselves gods of gold.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 20, 24, 'You need make for me only an altar of earth and sacrifice on it your burnt offerings and your offerings of well-being, your sheep and your oxen; in every place where I cause my name to be remembered I will come to you and bless you.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 20, 25, 'But if you make for me an altar of stone, do not build it of hewn stones; for if you use a chisel upon it you profane it.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 20, 26, 'You shall not go up by steps to my altar, so that your nakedness may not be exposed on it."', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(2, 'Kel', 'Exodus', 21, 1, 'These are the ordinances that you shall set before them:', 'en', 'NRSV-CE', 'The Law concerning Slaves'),
(2, 'Kel', 'Exodus', 21, 2, 'When you buy a male Hebrew slave, he shall serve six years, but in the seventh he shall go out a free person, without debt.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 21, 3, 'If he comes in single, he shall go out single; if he comes in married, then his wife shall go out with him.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 21, 4, 'If his master gives him a wife and she bears him sons or daughters, the wife and her children shall be her master"s and he shall go out alone.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 21, 5, 'But if the slave declares, "I love my master, my wife, and my children; I will not go out a free person,"', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 21, 6, 'then his master shall bring him before God. He shall be brought to the door or the doorpost; and his master shall pierce his ear with an awl; and he shall serve him for life.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 21, 7, 'When a man sells his daughter as a slave, she shall not go out as the male slaves do.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 21, 8, 'If she does not please her master, who designated her for himself, then he shall let her be redeemed; he shall have no right to sell her to a foreign people, since he has dealt unfairly with her.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 21, 9, 'If he designates her for his son, he shall deal with her as with a daughter.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 21, 10, 'If he takes another wife to himself, he shall not diminish the food, clothing, or marital rights of the first wife.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 21, 11, 'And if he does not do these three things for her, she shall go out without debt, without payment of money.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 21, 12, 'Whoever strikes a person mortally shall be put to death.', 'en', 'NRSV-CE', 'The Law concerning Violence'),
(2, 'Kel', 'Exodus', 21, 13, 'If it was not premeditated, but came about by an act of God, then I will appoint for you a place to which the killer may flee.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 21, 14, 'But if someone willfully attacks and kills another by treachery, you shall take the killer from my altar for execution.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 21, 15, 'Whoever strikes father or mother shall be put to death.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 21, 16, 'Whoever kidnaps a person, whether that person has been sold or is still held in possession, shall be put to death.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 21, 17, 'Whoever curses father or mother shall be put to death.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 21, 18, 'When individuals quarrel and one strikes the other with a stone or fist so that the injured party, though not dead, is confined to bed,', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 21, 19, 'but recovers and walks around outside with the help of a staff, then the assailant shall be free of liability, except to pay for the loss of time, and to arrange for full recovery.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 21, 20, 'When a slaveowner strikes a male or female slave with a rod and the slave dies immediately, the owner shall be punished.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 21, 21, 'But if the slave survives a day or two, there is no punishment; for the slave is the owner"s property.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 21, 22, 'When people who are fighting injure a pregnant woman so that there is a miscarriage, and yet no further harm follows, the one responsible shall be fined what the woman"s husband demands, paying as much as the judges determine.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 21, 23, 'If any harm follows, then you shall give life for life,', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 21, 24, 'eye for eye, tooth for tooth, hand for hand, foot for foot,', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 21, 25, 'burn for burn, wound for wound, stripe for stripe.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 21, 26, 'When a slaveowner strikes the eye of a male or female slave, destroying it, the owner shall let the slave go, a free person, to compensate for the eye.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 21, 27, 'If the owner knocks out a tooth of a male or female slave, the slave shall be let go, a free person, to compensate for the tooth.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 21, 28, 'When an ox gores a man or a woman to death, the ox shall be stoned, and its flesh shall not be eaten; but the owner of the ox shall not be liable.', 'en', 'NRSV-CE', 'Laws concerning Property'),
(2, 'Kel', 'Exodus', 21, 29, 'If the ox has been accustomed to gore in the past, and its owner has been warned but has not restrained it, and it kills a man or a woman, the ox shall be stoned, and its owner also shall be put to death.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 21, 30, 'If a ransom is imposed on the owner, then the owner shall pay whatever is imposed for the redemption of the victim"s life.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 21, 31, 'If it gores a boy or a girl, the owner shall be dealt with according to this same rule.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 21, 32, 'If the ox gores a male or female slave, the owner shall pay to the slaveowner thirty shekels of silver, and the ox shall be stoned.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 21, 33, 'If someone leaves a pit open, or digs a pit and does not cover it, and an ox or a donkey falls into it,', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 21, 34, 'the owner of the pit shall make restitution, giving money to its owner, but keeping the dead animal.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 21, 35, 'If someone"s ox hurts the ox of another, so that it dies, then they shall sell the live ox and divide the price of it; and the dead animal they shall also divide.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 21, 36, 'But if it was known that the ox was accustomed to gore in the past, and its owner has not restrained it, the owner shall restore ox for ox, but keep the dead animal.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(2, 'Kel', 'Exodus', 22, 1, 'When someone steals an ox or a sheep, and slaughters it or sells it, the thief shall pay five oxen for an ox, and four sheep for a sheep. The thief shall make restitution, but if unable to do so, shall be sold for the theft.', 'en', 'NRSV-CE', 'Laws of Restitution'),
(2, 'Kel', 'Exodus', 22, 2, 'If a thief is found breaking in, and is beaten to death, no bloodguilt is incurred;', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 22, 3, 'but if it happens after sunrise, bloodguilt is incurred.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 22, 4, 'When the animal, whether ox or donkey or sheep, is found alive in the thief"s possession, the thief shall pay double.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 22, 5, 'When someone causes a field or vineyard to be grazed over, or lets livestock loose to graze in someone else"s field, restitution shall be made from the best in the owner"s field or vineyard.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 22, 6, 'When fire breaks out and catches in thorns so that the stacked grain or the standing grain or the field is consumed, the one who started the fire shall make full restitution.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 22, 7, 'When someone delivers to a neighbor money or goods for safekeeping, and they are stolen from the neighbor"s house, then the thief, if caught, shall pay double.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 22, 8, 'If the thief is not caught, the owner of the house shall be brought before God, to determine whether or not the owner had laid hands on the neighbor"s goods.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 22, 9, 'In any case of disputed ownership involving ox, donkey, sheep, clothing, or any other loss, of which one party says, "This is mine," the case of both parties shall come before God; the one whom God condemns shall pay double to the other.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 22, 10, 'When someone delivers to another a donkey, ox, sheep, or any other animal for safekeeping, and it dies or is injured or is carried off, without anyone seeing it,', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 22, 11, 'an oath before the LORD shall decide between the two of them that the one has not laid hands on the property of the other; the owner shall accept the oath, and no restitution shall be made.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 22, 12, 'But if it was stolen, restitution shall be made to its owner.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 22, 13, 'If it was mangled by beasts, let it be brought as evidence; restitution shall not be made for the mangled remains.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 22, 14, 'When someone borrows an animal from another and it is injured or dies, the owner not being present, full restitution shall be made.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 22, 15, 'If the owner was present, there shall be no restitution; if it was hired, only the hiring fee is due.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 22, 16, 'When a man seduces a virgin who is not engaged to be married, and lies with her, he shall give the bride-price for her and make her his wife.', 'en', 'NRSV-CE', 'Social and Religious Laws'),
(2, 'Kel', 'Exodus', 22, 17, 'But if her father refuses to give her to him, he shall pay an amount equal to the bride-price for virgins.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 22, 18, 'You shall not permit a female sorcerer to live.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 22, 19, 'Whoever lies with an animal shall be put to death.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 22, 20, 'Whoever sacrifices to any god, other than the LORD alone, shall be devoted to destruction.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 22, 21, 'You shall not wrong or oppress a resident alien, for you were aliens in the land of Egypt.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 22, 22, 'You shall not abuse any widow or orphan.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 22, 23, 'If you do abuse them, when they cry out to me, I will surely heed their cry;', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 22, 24, 'my wrath will burn, and I will kill you with the sword, and your wives shall become widows and your children orphans.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 22, 25, 'If you lend money to my people, to the poor among you, you shall not deal with them as a creditor; you shall not exact interest from them.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 22, 26, 'If you take your neighbor"s cloak in pawn, you shall restore it before the sun goes down;', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 22, 27, 'for it may be your neighbor"s only clothing to use as cover; in what else shall that person sleep? And if your neighbor cries out to me, I will listen, for I am compassionate.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 22, 28, 'You shall not revile God, or curse a leader of your people.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 22, 29, 'You shall not delay to make offerings from the fullness of your harvest and from the outflow of your presses.
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(2, 'Kel', 'Exodus', 23, 1, 'You shall not spread a false report. You shall not join hands with the wicked to act as a malicious witness.', 'en', 'NRSV-CE', 'Justice for All'),
(2, 'Kel', 'Exodus', 23, 2, 'You shall not follow a majority in wrongdoing; when you bear witness in a lawsuit, you shall not side with the majority so as to pervert justice;', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 23, 3, 'nor shall you be partial to the poor in a lawsuit.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 23, 4, 'When you come upon your enemy"s ox or donkey going astray, you shall bring it back.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 23, 5, 'When you see the donkey of one who hates you lying under its burden and you would hold back from setting it free, you must help to set it free.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 23, 6, 'You shall not pervert the justice due to your poor in their lawsuits.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 23, 7, 'Keep far from a false charge, and do not kill the innocent and those in the right, for I will not acquit the guilty.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 23, 8, 'You shall take no bribe, for a bribe blinds the officials, and subverts the cause of those who are in the right.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 23, 9, 'You shall not oppress a resident alien; you know the heart of an alien, for you were aliens in the land of Egypt.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 23, 10, 'For six years you shall sow your land and gather in its yield;', 'en', 'NRSV-CE', 'Sabbatical Year and Sabbath'),
(2, 'Kel', 'Exodus', 23, 11, 'but the seventh year you shall let it rest and lie fallow, so that the poor of your people may eat; and what they leave the wild animals may eat. You shall do the same with your vineyard, and with your olive orchard.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 23, 12, 'Six days you shall do your work, but on the seventh day you shall rest, so that your ox and your donkey may have relief, and your homeborn slave and the resident alien may be refreshed.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 23, 13, 'Be attentive to all that I have said to you. Do not invoke the names of other gods; do not let them be heard on your lips.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 23, 14, 'Three times in the year you shall hold a festival for me.', 'en', 'NRSV-CE', 'The Annual Festivals'),
(2, 'Kel', 'Exodus', 23, 15, 'You shall observe the festival of unleavened bread; as I commanded you, you shall eat unleavened bread for seven days at the appointed time in the month of Abib, for in it you came out of Egypt.
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(2, 'Kel', 'Exodus', 24, 1, 'Then he said to Moses, "Come up to the LORD, you and Aaron, Nadab, and Abihu, and seventy of the elders of Israel, and worship at a distance.', 'en', 'NRSV-CE', 'The Blood of the Covenant'),
(2, 'Kel', 'Exodus', 24, 2, 'Moses alone shall come near the LORD; but the others shall not come near, and the people shall not come up with him."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 24, 3, 'Moses came and told the people all the words of the LORD and all the ordinances; and all the people answered with one voice, and said, "All the words that the LORD has spoken we will do."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 24, 4, 'And Moses wrote down all the words of the LORD. He rose early in the morning, and built an altar at the foot of the mountain, and set up twelve pillars, corresponding to the twelve tribes of Israel.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 24, 5, 'He sent young men of the people of Israel, who offered burnt offerings and sacrificed oxen as offerings of well-being to the LORD.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 24, 6, 'Moses took half of the blood and put it in basins, and half of the blood he dashed against the altar.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 24, 7, 'Then he took the book of the covenant, and read it in the hearing of the people; and they said, "All that the LORD has spoken we will do, and we will be obedient."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 24, 8, 'Moses took the blood and dashed it on the people, and said, "See the blood of the covenant that the LORD has made with you in accordance with all these words."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 24, 9, 'Then Moses and Aaron, Nadab, and Abihu, and seventy of the elders of Israel went up,', 'en', 'NRSV-CE', 'On the Mountain with God'),
(2, 'Kel', 'Exodus', 24, 10, 'and they saw the God of Israel. Under his feet there was something like a pavement of sapphire stone, like the very heaven for clearness.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 24, 11, 'God did not lay his hand on the chief men of the people of Israel; also they beheld God, and they ate and drank.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 24, 12, 'The LORD said to Moses, "Come up to me on the mountain, and wait there; and I will give you the tablets of stone, with the law and the commandment, which I have written for their instruction."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 24, 13, 'So Moses set out with his assistant Joshua, and Moses went up into the mountain of God.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 24, 14, 'To the elders he had said, "Wait here for us, until we come to you again; for Aaron and Hur are with you; whoever has a dispute may go to them."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 24, 15, 'Then Moses went up on the mountain, and the cloud covered the mountain.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 24, 16, 'The glory of the LORD settled on Mount Sinai, and the cloud covered it for six days; on the seventh day he called to Moses out of the cloud.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 24, 17, 'Now the appearance of the glory of the LORD was like a devouring fire on the top of the mountain in the sight of the people of Israel.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 24, 18, 'Moses entered the cloud, and went up on the mountain. Moses was on the mountain for forty days and forty nights.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(2, 'Kel', 'Exodus', 25, 1, 'The LORD said to Moses:', 'en', 'NRSV-CE', 'Offerings for the Tabernacle'),
(2, 'Kel', 'Exodus', 25, 2, 'Tell the Israelites to take for me an offering; from all whose hearts prompt them to give you shall receive the offering for me.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 25, 3, 'This is the offering that you shall receive from them: gold, silver, and bronze,', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 25, 4, 'blue, purple, and crimson yarns and fine linen, goats" hair,', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 25, 5, 'tanned rams" skins, fine leather, acacia wood,', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 25, 6, 'oil for the lamps, spices for the anointing oil and for the fragrant incense,', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 25, 7, 'onyx stones and gems to be set in the ephod and for the breastpiece.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 25, 8, 'And have them make me a sanctuary, so that I may dwell among them.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 25, 9, 'In accordance with all that I show you concerning the pattern of the tabernacle and of all its furniture, so you shall make it.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 25, 10, 'They shall make an ark of acacia wood; it shall be two and a half cubits long, a cubit and a half wide, and a cubit and a half high.', 'en', 'NRSV-CE', 'The Ark of the Covenant'),
(2, 'Kel', 'Exodus', 25, 11, 'You shall overlay it with pure gold, inside and outside you shall overlay it, and you shall make a molding of gold upon it all around.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 25, 12, 'You shall cast four rings of gold for it and put them on its four feet, two rings on the one side of it, and two rings on the other side.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 25, 13, 'You shall make poles of acacia wood, and overlay them with gold.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 25, 14, 'And you shall put the poles into the rings on the sides of the ark, by which to carry the ark.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 25, 15, 'The poles shall remain in the rings of the ark; they shall not be taken from it.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 25, 16, 'You shall put into the ark the covenant that I shall give you.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 25, 17, 'Then you shall make a mercy seat of pure gold; two cubits and a half shall be its length, and a cubit and a half its width.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 25, 18, 'You shall make two cherubim of gold; you shall make them of hammered work, at the two ends of the mercy seat.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 25, 19, 'Make one cherub at the one end, and one cherub at the other; of one piece with the mercy seat you shall make the cherubim at its two ends.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 25, 20, 'The cherubim shall spread out their wings above, overshadowing the mercy seat with their wings. They shall face one to another; the faces of the cherubim shall be turned toward the mercy seat.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 25, 21, 'You shall put the mercy seat on the top of the ark; and in the ark you shall put the covenant that I shall give you.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 25, 22, 'There I will meet with you, and from above the mercy seat, from between the two cherubim that are on the ark of the covenant, I will deliver to you all my commands for the Israelites.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 25, 23, 'You shall make a table of acacia wood, two cubits long, one cubit wide, and a cubit and a half high.', 'en', 'NRSV-CE', 'The Table for the Bread of the Presence'),
(2, 'Kel', 'Exodus', 25, 24, 'You shall overlay it with pure gold, and make a molding of gold around it.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 25, 25, 'You shall make around it a rim a handbreadth wide, and a molding of gold around the rim.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 25, 26, 'You shall make for it four rings of gold, and fasten the rings to the four corners at its four legs.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 25, 27, 'The rings that hold the poles used for carrying the table shall be close to the rim.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 25, 28, 'You shall make the poles of acacia wood, and overlay them with gold, and the table shall be carried with these.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 25, 29, 'You shall make its plates and dishes for incense, and its flagons and bowls with which to pour drink offerings; you shall make them of pure gold.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 25, 30, 'And you shall set the bread of the Presence on the table before me always.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 25, 31, 'You shall make a lampstand of pure gold. The base and the shaft of the lampstand shall be made of hammered work; its cups, its calyxes, and its petals shall be of one piece with it;', 'en', 'NRSV-CE', 'The Lampstand'),
(2, 'Kel', 'Exodus', 25, 32, 'and there shall be six branches going out of its sides, three branches of the lampstand out of one side of it and three branches of the lampstand out of the other side of it;', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 25, 33, 'three cups shaped like almond blossoms, each with calyx and petals, on one branch, and three cups shaped like almond blossoms, each with calyx and petals, on the other branch--so for the six branches going out of the lampstand.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 25, 34, 'On the lampstand itself there shall be four cups shaped like almond blossoms, each with its calyxes and petals.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 25, 35, 'There shall be a calyx of one piece with it under the first pair of branches, a calyx of one piece with it under the next pair of branches, and a calyx of one piece with it under the last pair of branches--so for the six branches that go out of the lampstand.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 25, 36, 'Their calyxes and their branches shall be of one piece with it, the whole of it one hammered piece of pure gold.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 25, 37, 'You shall make the seven lamps for it; and the lamps shall be set up so as to give light on the space in front of it.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 25, 38, 'Its snuffers and trays shall be of pure gold.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 25, 39, 'It, and all these utensils, shall be made from a talent of pure gold.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 25, 40, 'And see that you make them according to the pattern for them, which is being shown you on the mountain.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(2, 'Kel', 'Exodus', 26, 1, 'Moreover you shall make the tabernacle with ten curtains of fine twisted linen, and blue, purple, and crimson yarns; you shall make them with cherubim skillfully worked into them.', 'en', 'NRSV-CE', 'The Tabernacle'),
(2, 'Kel', 'Exodus', 26, 2, 'The length of each curtain shall be twenty-eight cubits, and the width of each curtain four cubits; all the curtains shall be of the same size.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 26, 3, 'Five curtains shall be joined to one another; and the other five curtains shall be joined to one another.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 26, 4, 'You shall make loops of blue on the edge of the outermost curtain in the first set; and likewise you shall make loops on the edge of the outermost curtain in the second set.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 26, 5, 'You shall make fifty loops on the one curtain, and you shall make fifty loops on the edge of the curtain that is in the second set; the loops shall be opposite one another.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 26, 6, 'You shall make fifty clasps of gold, and join the curtains to one another with the clasps, so that the tabernacle may be one whole.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 26, 7, 'You shall also make curtains of goats" hair for a tent over the tabernacle; you shall make eleven curtains.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 26, 8, 'The length of each curtain shall be thirty cubits, and the width of each curtain four cubits; the eleven curtains shall be of the same size.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 26, 9, 'You shall join five curtains by themselves, and six curtains by themselves, and the sixth curtain you shall double over at the front of the tent.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 26, 10, 'You shall make fifty loops on the edge of the curtain that is outermost in one set, and fifty loops on the edge of the curtain that is outermost in the second set.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 26, 11, 'You shall make fifty clasps of bronze, and put the clasps into the loops, and join the tent together, so that it may be one whole.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 26, 12, 'The part that remains of the curtains of the tent, the half curtain that remains, shall hang over the back of the tabernacle.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 26, 13, 'The cubit on the one side, and the cubit on the other side, of what remains in the length of the curtains of the tent, shall hang over the sides of the tabernacle, on this side and that side, to cover it.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 26, 14, 'You shall make for the tent a covering of tanned rams" skins and an outer covering of fine leather.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 26, 15, 'You shall make upright frames of acacia wood for the tabernacle.', 'en', 'NRSV-CE', 'The Framework'),
(2, 'Kel', 'Exodus', 26, 16, 'Ten cubits shall be the length of a frame, and a cubit and a half the width of each frame.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 26, 17, 'There shall be two pegs in each frame to fit the frames together; you shall make these for all the frames of the tabernacle.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 26, 18, 'You shall make the frames for the tabernacle: twenty frames for the south side;', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 26, 19, 'and you shall make forty bases of silver under the twenty frames, two bases under the first frame for its two pegs, and two bases under the next frame for its two pegs;', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 26, 20, 'and for the second side of the tabernacle, on the north side twenty frames,', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 26, 21, 'and their forty bases of silver, two bases under the first frame, and two bases under the next frame;', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 26, 22, 'and for the rear of the tabernacle westward you shall make six frames.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 26, 23, 'You shall make two frames for corners of the tabernacle in the rear;', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 26, 24, 'they shall be separate beneath, but joined at the top, at the first ring; it shall be the same with both of them; they shall form the two corners.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 26, 25, 'And so there shall be eight frames, with their bases of silver, sixteen bases; two bases under the first frame, and two bases under the next frame.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 26, 26, 'You shall make bars of acacia wood, five for the frames of the one side of the tabernacle,', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 26, 27, 'and five bars for the frames of the other side of the tabernacle, and five bars for the frames of the side of the tabernacle at the rear westward.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 26, 28, 'The middle bar, halfway up the frames, shall pass through from end to end.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 26, 29, 'You shall overlay the frames with gold, and shall make their rings of gold to hold the bars; and you shall overlay the bars with gold.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 26, 30, 'Then you shall erect the tabernacle according to the plan for it that you were shown on the mountain.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 26, 31, 'You shall make a curtain of blue, purple, and crimson yarns, and of fine twisted linen; it shall be made with cherubim skillfully worked into it.', 'en', 'NRSV-CE', 'The Curtain'),
(2, 'Kel', 'Exodus', 26, 32, 'You shall hang it on four pillars of acacia overlaid with gold, which have hooks of gold and rest on four bases of silver.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 26, 33, 'You shall hang the curtain under the clasps, and bring the ark of the covenant in there, within the curtain; and the curtain shall separate for you the holy place from the most holy.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 26, 34, 'You shall put the mercy seat on the ark of the covenant in the most holy place.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 26, 35, 'You shall set the table outside the curtain, and the lampstand on the south side of the tabernacle opposite the table; and you shall put the table on the north side.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 26, 36, 'You shall make a screen for the entrance of the tent, of blue, purple, and crimson yarns, and of fine twisted linen, embroidered with needlework.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 26, 37, 'You shall make for the screen five pillars of acacia, and overlay them with gold; their hooks shall be of gold, and you shall cast five bases of bronze for them.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(2, 'Kel', 'Exodus', 27, 1, 'You shall make the altar of acacia wood, five cubits long and five cubits wide; the altar shall be square, and it shall be three cubits high.', 'en', 'NRSV-CE', 'The Altar of Burnt Offering'),
(2, 'Kel', 'Exodus', 27, 2, 'You shall make horns for it on its four corners; its horns shall be of one piece with it, and you shall overlay it with bronze.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 27, 3, 'You shall make pots for it to receive its ashes, and shovels and basins and forks and firepans; you shall make all its utensils of bronze.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 27, 4, 'You shall also make for it a grating, a network of bronze; and on the net you shall make four bronze rings at its four corners.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 27, 5, 'You shall set it under the ledge of the altar so that the net shall extend halfway down the altar.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 27, 6, 'You shall make poles for the altar, poles of acacia wood, and overlay them with bronze;', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 27, 7, 'the poles shall be put through the rings, so that the poles shall be on the two sides of the altar when it is carried.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 27, 8, 'You shall make it hollow, with boards. They shall be made just as you were shown on the mountain.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 27, 9, 'You shall make the court of the tabernacle. On the south side the court shall have hangings of fine twisted linen one hundred cubits long for that side;', 'en', 'NRSV-CE', 'The Court and Its Hangings'),
(2, 'Kel', 'Exodus', 27, 10, 'its twenty pillars and their twenty bases shall be of bronze, but the hooks of the pillars and their bands shall be of silver.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 27, 11, 'Likewise for its length on the north side there shall be hangings one hundred cubits long, their pillars twenty and their bases twenty, of bronze, but the hooks of the pillars and their bands shall be of silver.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 27, 12, 'For the width of the court on the west side there shall be fifty cubits of hangings, with ten pillars and ten bases.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 27, 13, 'The width of the court on the front to the east shall be fifty cubits.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 27, 14, 'There shall be fifteen cubits of hangings on the one side, with three pillars and three bases.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 27, 15, 'There shall be fifteen cubits of hangings on the other side, with three pillars and three bases.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 27, 16, 'For the gate of the court there shall be a screen twenty cubits long, of blue, purple, and crimson yarns, and of fine twisted linen, embroidered with needlework; it shall have four pillars and with them four bases.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 27, 17, 'All the pillars around the court shall be banded with silver; their hooks shall be of silver, and their bases of bronze.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 27, 18, 'The length of the court shall be one hundred cubits, the width fifty, and the height five cubits, with hangings of fine twisted linen and bases of bronze.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 27, 19, 'All the utensils of the tabernacle for every use, and all its pegs and all the pegs of the court, shall be of bronze.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 27, 20, 'You shall further command the Israelites to bring you pure oil of beaten olives for the light, so that a lamp may be set up to burn regularly.', 'en', 'NRSV-CE', 'The Oil for the Lamp'),
(2, 'Kel', 'Exodus', 27, 21, 'In the tent of meeting, outside the curtain that is before the covenant, Aaron and his sons shall tend it from evening to morning before the LORD. It shall be a perpetual ordinance to be observed throughout their generations by the Israelites.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(2, 'Kel', 'Exodus', 28, 1, 'Then bring near to you your brother Aaron, and his sons with him, from among the Israelites, to serve me as priests--Aaron and Aaron"s sons, Nadab and Abihu, Eleazar and Ithamar.', 'en', 'NRSV-CE', 'Vestments for the Priesthood'),
(2, 'Kel', 'Exodus', 28, 2, 'You shall make sacred vestments for the glorious adornment of your brother Aaron.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 28, 3, 'And you shall speak to all who have ability, whom I have endowed with skill, that they make Aaron"s vestments to consecrate him for my priesthood.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 28, 4, 'These are the vestments that they shall make: a breastpiece, an ephod, a robe, a checkered tunic, a turban, and a sash. When they make these sacred vestments for your brother Aaron and his sons to serve me as priests,', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 28, 5, 'they shall use gold, blue, purple, and crimson yarns, and fine linen.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 28, 6, 'They shall make the ephod of gold, of blue, purple, and crimson yarns, and of fine twisted linen, skillfully worked.', 'en', 'NRSV-CE', 'The Ephod'),
(2, 'Kel', 'Exodus', 28, 7, 'It shall have two shoulder-pieces attached to its two edges, so that it may be joined together.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 28, 8, 'The decorated band on it shall be of the same workmanship and materials, of gold, of blue, purple, and crimson yarns, and of fine twisted linen.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 28, 9, 'You shall take two onyx stones, and engrave on them the names of the sons of Israel,', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 28, 10, 'six of their names on the one stone, and the names of the remaining six on the other stone, in the order of their birth.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 28, 11, 'As a gem-cutter engraves signets, so you shall engrave the two stones with the names of the sons of Israel; you shall mount them in settings of gold filigree.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 28, 12, 'You shall set the two stones on the shoulder-pieces of the ephod, as stones of remembrance for the sons of Israel; and Aaron shall bear their names before the LORD on his two shoulders for remembrance.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 28, 13, 'You shall make settings of gold filigree,', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 28, 14, 'and two chains of pure gold, twisted like cords; and you shall attach the corded chains to the settings.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 28, 15, 'You shall make a breastpiece of judgment, in skilled work; you shall make it in the style of the ephod; of gold, of blue and purple and crimson yarns, and of fine twisted linen you shall make it.', 'en', 'NRSV-CE', 'The Breastplate'),
(2, 'Kel', 'Exodus', 28, 16, 'It shall be square and doubled, a span in length and a span in width.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 28, 17, 'You shall set in it four rows of stones. A row of carnelian, chrysolite, and emerald shall be the first row;', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 28, 18, 'and the second row a turquoise, a sapphire, and a moonstone;', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 28, 19, 'and the third row a jacinth, an agate, and an amethyst;', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 28, 20, 'and the fourth row a beryl, an onyx, and a jasper; they shall be set in gold filigree.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 28, 21, 'There shall be twelve stones with names corresponding to the names of the sons of Israel; they shall be like signets, each engraved with its name, for the twelve tribes.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 28, 22, 'You shall make for the breastpiece chains of pure gold, twisted like cords;', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 28, 23, 'and you shall make for the breastpiece two rings of gold, and put the two rings on the two edges of the breastpiece.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 28, 24, 'You shall put the two cords of gold in the two rings at the edges of the breastpiece;', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 28, 25, 'the two ends of the two cords you shall attach to the two settings, and so attach it in front to the shoulder-pieces of the ephod.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 28, 26, 'You shall make two rings of gold, and put them at the two ends of the breastpiece, on its inside edge next to the ephod.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 28, 27, 'You shall make two rings of gold, and attach them in front to the lower part of the two shoulder-pieces of the ephod, at its joining above the decorated band of the ephod.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 28, 28, 'The breastpiece shall be bound by its rings to the rings of the ephod with a blue cord, so that it may lie on the decorated band of the ephod, and so that the breastpiece shall not come loose from the ephod.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 28, 29, 'So Aaron shall bear the names of the sons of Israel in the breastpiece of judgment on his heart when he goes into the holy place, for a continual remembrance before the LORD.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 28, 30, 'In the breastpiece of judgment you shall put the Urim and the Thummim, and they shall be on Aaron"s heart when he goes in before the LORD; thus Aaron shall bear the judgment of the Israelites on his heart before the LORD continually.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 28, 31, 'You shall make the robe of the ephod all of blue.', 'en', 'NRSV-CE', 'Other Priestly Vestments'),
(2, 'Kel', 'Exodus', 28, 32, 'It shall have an opening for the head in the middle of it, with a woven binding around the opening, like the opening in a coat of mail, so that it may not be torn.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 28, 33, 'On its lower hem you shall make pomegranates of blue, purple, and crimson yarns, all around the lower hem, with bells of gold between them all around--', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 28, 34, 'a golden bell and a pomegranate alternating all around the lower hem of the robe.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 28, 35, 'Aaron shall wear it when he ministers, and its sound shall be heard when he goes into the holy place before the LORD, and when he comes out, so that he may not die.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 28, 36, 'You shall make a rosette of pure gold, and engrave on it, like the engraving of a signet, "Holy to the LORD."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 28, 37, 'You shall fasten it on the turban with a blue cord; it shall be on the front of the turban.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 28, 38, 'It shall be on Aaron"s forehead, and Aaron shall take on himself any guilt incurred in the holy offering that the Israelites consecrate as their sacred donations; it shall always be on his forehead, in order that they may find favor before the LORD.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 28, 39, 'You shall make the checkered tunic of fine linen, and you shall make a turban of fine linen, and you shall make a sash embroidered with needlework.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 28, 40, 'For Aaron"s sons you shall make tunics and sashes and headdresses; you shall make them for their glorious adornment.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 28, 41, 'You shall put them on your brother Aaron, and on his sons with him, and shall anoint them and ordain them and consecrate them, so that they may serve me as priests.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 28, 42, 'You shall make for them linen undergarments to cover their naked flesh; they shall reach from the hips to the thighs;', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 28, 43, 'Aaron and his sons shall wear them when they go into the tent of meeting, or when they come near the altar to minister in the holy place; or they will bring guilt on themselves and die. This shall be a perpetual ordinance for him and for his descendants after him.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(2, 'Kel', 'Exodus', 29, 1, 'Now this is what you shall do to them to consecrate them, so that they may serve me as priests. Take one young bull and two rams without blemish,', 'en', 'NRSV-CE', 'The Ordination of the Priests'),
(2, 'Kel', 'Exodus', 29, 2, 'and unleavened bread, unleavened cakes mixed with oil, and unleavened wafers spread with oil. You shall make them of choice wheat flour.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 29, 3, 'You shall put them in one basket and bring them in the basket, and bring the bull and the two rams.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 29, 4, 'You shall bring Aaron and his sons to the entrance of the tent of meeting, and wash them with water.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 29, 5, 'Then you shall take the vestments, and put on Aaron the tunic and the robe of the ephod, and the ephod, and the breastpiece, and gird him with the decorated band of the ephod;', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 29, 6, 'and you shall set the turban on his head, and put the holy diadem on the turban.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 29, 7, 'You shall take the anointing oil, and pour it on his head and anoint him.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 29, 8, 'Then you shall bring his sons, and put tunics on them,', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 29, 9, 'and you shall gird them with sashes and tie headdresses on them; and the priesthood shall be theirs by a perpetual ordinance. You shall then ordain Aaron and his sons.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 29, 10, 'You shall bring the bull in front of the tent of meeting. Aaron and his sons shall lay their hands on the head of the bull,', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 29, 11, 'and you shall slaughter the bull before the LORD, at the entrance of the tent of meeting,', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 29, 12, 'and shall take some of the blood of the bull and put it on the horns of the altar with your finger, and all the rest of the blood you shall pour out at the base of the altar.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 29, 13, 'You shall take all the fat that covers the entrails, and the appendage of the liver, and the two kidneys with the fat that is on them, and turn them into smoke on the altar.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 29, 14, 'But the flesh of the bull, and its skin, and its dung, you shall burn with fire outside the camp; it is a sin offering.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 29, 15, 'Then you shall take one of the rams, and Aaron and his sons shall lay their hands on the head of the ram,', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 29, 16, 'and you shall slaughter the ram, and shall take its blood and dash it against all sides of the altar.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 29, 17, 'Then you shall cut the ram into its parts, and wash its entrails and its legs, and put them with its parts and its head,', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 29, 18, 'and turn the whole ram into smoke on the altar; it is a burnt offering to the LORD; it is a pleasing odor, an offering by fire to the LORD.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 29, 19, 'You shall take the other ram; and Aaron and his sons shall lay their hands on the head of the ram,', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 29, 20, 'and you shall slaughter the ram, and take some of its blood and put it on the lobe of Aaron"s right ear and on the lobes of the right ears of his sons, and on the thumbs of their right hands, and on the big toes of their right feet, and dash the rest of the blood against all sides of the altar.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 29, 21, 'Then you shall take some of the blood that is on the altar, and some of the anointing oil, and sprinkle it on Aaron and his vestments and on his sons and his sons" vestments with him; then he and his vestments shall be holy, as well as his sons and his sons" vestments.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 29, 22, 'You shall also take the fat of the ram, the fat tail, the fat that covers the entrails, the appendage of the liver, the two kidneys with the fat that is on them, and the right thigh (for it is a ram of ordination),', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 29, 23, 'and one loaf of bread, one cake of bread made with oil, and one wafer, out of the basket of unleavened bread that is before the LORD;', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 29, 24, 'and you shall place all these on the palms of Aaron and on the palms of his sons, and raise them as an elevation offering before the LORD.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 29, 25, 'Then you shall take them from their hands, and turn them into smoke on the altar on top of the burnt offering of pleasing odor before the LORD; it is an offering by fire to the LORD.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 29, 26, 'You shall take the breast of the ram of Aaron"s ordination and raise it as an elevation offering before the LORD; and it shall be your portion.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 29, 27, 'You shall consecrate the breast that was raised as an elevation offering and the thigh that was raised as an elevation offering from the ram of ordination, from that which belonged to Aaron and his sons.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 29, 28, 'These things shall be a perpetual ordinance for Aaron and his sons from the Israelites, for this is an offering; and it shall be an offering by the Israelites from their sacrifice of offerings of well-being, their offering to the LORD.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 29, 29, 'The sacred vestments of Aaron shall be passed on to his sons after him; they shall be anointed in them and ordained in them.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 29, 30, 'The son who is priest in his place shall wear them seven days, when he comes into the tent of meeting to minister in the holy place.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 29, 31, 'You shall take the ram of ordination, and boil its flesh in a holy place;', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 29, 32, 'and Aaron and his sons shall eat the flesh of the ram and the bread that is in the basket, at the entrance of the tent of meeting.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 29, 33, 'They themselves shall eat the food by which atonement is made, to ordain and consecrate them, but no one else shall eat of them, because they are holy.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 29, 34, 'If any of the flesh for the ordination, or of the bread, remains until the morning, then you shall burn the remainder with fire; it shall not be eaten, because it is holy.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 29, 35, 'Thus you shall do to Aaron and to his sons, just as I have commanded you; through seven days you shall ordain them.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 29, 36, 'Also every day you shall offer a bull as a sin offering for atonement. Also you shall offer a sin offering for the altar, when you make atonement for it, and shall anoint it, to consecrate it.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 29, 37, 'Seven days you shall make atonement for the altar, and consecrate it, and the altar shall be most holy; whatever touches the altar shall become holy.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 29, 38, 'Now this is what you shall offer on the altar: two lambs a year old regularly each day.', 'en', 'NRSV-CE', 'The Daily Offerings'),
(2, 'Kel', 'Exodus', 29, 39, 'One lamb you shall offer in the morning, and the other lamb you shall offer in the evening;', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 29, 40, 'and with the first lamb one-tenth of a measure of choice flour mixed with one-fourth of a hin of beaten oil, and one-fourth of a hin of wine for a drink offering.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 29, 41, 'And the other lamb you shall offer in the evening, and shall offer with it a grain offering and its drink offering, as in the morning, for a pleasing odor, an offering by fire to the LORD.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 29, 42, 'It shall be a regular burnt offering throughout your generations at the entrance of the tent of meeting before the LORD, where I will meet with you, to speak to you there.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 29, 43, 'I will meet with the Israelites there, and it shall be sanctified by my glory;', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 29, 44, 'I will consecrate the tent of meeting and the altar; Aaron also and his sons I will consecrate, to serve me as priests.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 29, 45, 'I will dwell among the Israelites, and I will be their God.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 29, 46, 'And they shall know that I am the LORD their God, who brought them out of the land of Egypt that I might dwell among them; I am the LORD their God.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(2, 'Kel', 'Exodus', 30, 1, 'You shall make an altar on which to offer incense; you shall make it of acacia wood.', 'en', 'NRSV-CE', 'The Altar of Incense'),
(2, 'Kel', 'Exodus', 30, 2, 'It shall be one cubit long, and one cubit wide; it shall be square, and shall be two cubits high; its horns shall be of one piece with it.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 30, 3, 'You shall overlay it with pure gold, its top, and its sides all around and its horns; and you shall make for it a molding of gold all around.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 30, 4, 'And you shall make two golden rings for it; under its molding on two opposite sides of it you shall make them, and they shall hold the poles with which to carry it.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 30, 5, 'You shall make the poles of acacia wood, and overlay them with gold.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 30, 6, 'You shall place it in front of the curtain that is above the ark of the covenant, in front of the mercy seat that is over the covenant, where I will meet with you.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 30, 7, 'Aaron shall offer fragrant incense on it; every morning when he dresses the lamps he shall offer it,', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 30, 8, 'and when Aaron sets up the lamps in the evening, he shall offer it, a regular incense offering before the LORD throughout your generations.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 30, 9, 'You shall not offer unholy incense on it, or a burnt offering, or a grain offering; and you shall not pour a drink offering on it.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 30, 10, 'Once a year Aaron shall perform the rite of atonement on its horns. Throughout your generations he shall perform the atonement for it once a year with the blood of the atoning sin offering. It is most holy to the LORD.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 30, 11, 'The LORD spoke to Moses:', 'en', 'NRSV-CE', 'The Half Shekel for the Sanctuary'),
(2, 'Kel', 'Exodus', 30, 12, 'When you take a census of the Israelites to register them, at registration all of them shall give a ransom for their lives to the LORD, so that no plague may come upon them for being registered.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 30, 13, 'This is what each one who is registered shall give: half a shekel according to the shekel of the sanctuary (the shekel is twenty gerahs), half a shekel as an offering to the LORD.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 30, 14, 'Each one who is registered, from twenty years old and upward, shall give the LORD"s offering.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 30, 15, 'The rich shall not give more, and the poor shall not give less, than the half shekel, when you bring this offering to the LORD to make atonement for your lives.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 30, 16, 'You shall take the atonement money from the Israelites and shall designate it for the service of the tent of meeting; before the LORD it will be a reminder to the Israelites of the ransom given for your lives.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 30, 17, 'The LORD spoke to Moses:', 'en', 'NRSV-CE', 'The Bronze Basin'),
(2, 'Kel', 'Exodus', 30, 18, 'You shall make a bronze basin with a bronze stand for washing. You shall put it between the tent of meeting and the altar, and you shall put water in it;', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 30, 19, 'with the water Aaron and his sons shall wash their hands and their feet.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 30, 20, 'When they go into the tent of meeting, or when they come near the altar to minister, to make an offering by fire to the LORD, they shall wash with water, so that they may not die.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 30, 21, 'They shall wash their hands and their feet, so that they may not die: it shall be a perpetual ordinance for them, for him and for his descendants throughout their generations.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 30, 22, 'The LORD spoke to Moses:', 'en', 'NRSV-CE', 'The Anointing Oil and Incense'),
(2, 'Kel', 'Exodus', 30, 23, 'Take the finest spices: of liquid myrrh five hundred shekels, and of sweet-smelling cinnamon half as much, that is, two hundred fifty, and two hundred fifty of aromatic cane,', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 30, 24, 'and five hundred of cassia--measured by the sanctuary shekel--and a hin of olive oil;', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 30, 25, 'and you shall make of these a sacred anointing oil blended as by the perfumer; it shall be a holy anointing oil.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 30, 26, 'With it you shall anoint the tent of meeting and the ark of the covenant,', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 30, 27, 'and the table and all its utensils, and the lampstand and its utensils, and the altar of incense,', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 30, 28, 'and the altar of burnt offering with all its utensils, and the basin with its stand;', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 30, 29, 'you shall consecrate them, so that they may be most holy; whatever touches them will become holy.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 30, 30, 'You shall anoint Aaron and his sons, and consecrate them, in order that they may serve me as priests.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 30, 31, 'You shall say to the Israelites, "This shall be my holy anointing oil throughout your generations.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 30, 32, 'It shall not be used in any ordinary anointing of the body, and you shall make no other like it in composition; it is holy, and it shall be holy to you.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 30, 33, 'Whoever compounds any like it or whoever puts any of it on an unqualified person shall be cut off from the people."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 30, 34, 'The LORD said to Moses: Take sweet spices, stacte, and onycha, and galbanum, sweet spices with pure frankincense (an equal part of each),', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 30, 35, 'and make an incense blended as by the perfumer, seasoned with salt, pure and holy;', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 30, 36, 'and you shall beat some of it into powder, and put part of it before the covenant in the tent of meeting where I shall meet with you; it shall be for you most holy.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 30, 37, 'When you make incense according to this composition, you shall not make it for yourselves; it shall be regarded by you as holy to the LORD.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 30, 38, 'Whoever makes any like it to use as perfume shall be cut off from the people.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(2, 'Kel', 'Exodus', 31, 1, 'The LORD spoke to Moses:', 'en', 'NRSV-CE', 'Bezalel and Oholiab'),
(2, 'Kel', 'Exodus', 31, 2, 'See, I have called by name Bezalel son of Uri son of Hur, of the tribe of Judah:', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 31, 3, 'and I have filled him with divine spirit, with ability, intelligence, and knowledge in every kind of craft,', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 31, 4, 'to devise artistic designs, to work in gold, silver, and bronze,', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 31, 5, 'in cutting stones for setting, and in carving wood, in every kind of craft.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 31, 6, 'Moreover, I have appointed with him Oholiab son of Ahisamach, of the tribe of Dan; and I have given skill to all the skillful, so that they may make all that I have commanded you:', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 31, 7, 'the tent of meeting, and the ark of the covenant, and the mercy seat that is on it, and all the furnishings of the tent,', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 31, 8, 'the table and its utensils, and the pure lampstand with all its utensils, and the altar of incense,', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 31, 9, 'and the altar of burnt offering with all its utensils, and the basin with its stand,', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 31, 10, 'and the finely worked vestments, the holy vestments for the priest Aaron and the vestments of his sons, for their service as priests,', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 31, 11, 'and the anointing oil and the fragrant incense for the holy place. They shall do just as I have commanded you.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 31, 12, 'The LORD said to Moses:', 'en', 'NRSV-CE', 'The Sabbath Law'),
(2, 'Kel', 'Exodus', 31, 13, 'You yourself are to speak to the Israelites: "You shall keep my sabbaths, for this is a sign between me and you throughout your generations, given in order that you may know that I, the LORD, sanctify you.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 31, 14, 'You shall keep the sabbath, because it is holy for you; everyone who profanes it shall be put to death; whoever does any work on it shall be cut off from among the people.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 31, 15, 'Six days shall work be done, but the seventh day is a sabbath of solemn rest, holy to the LORD; whoever does any work on the sabbath day shall be put to death.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 31, 16, 'Therefore the Israelites shall keep the sabbath, observing the sabbath throughout their generations, as a perpetual covenant.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 31, 17, 'It is a sign forever between me and the people of Israel that in six days the LORD made heaven and earth, and on the seventh day he rested, and was refreshed."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 31, 18, 'When God finished speaking with Moses on Mount Sinai, he gave him the two tablets of the covenant, tablets of stone, written with the finger of God.', 'en', 'NRSV-CE', 'The Two Tablets of the Covenant');
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(2, 'Kel', 'Exodus', 32, 1, 'When the people saw that Moses delayed to come down from the mountain, the people gathered around Aaron, and said to him, "Come, make gods for us, who shall go before us; as for this Moses, the man who brought us up out of the land of Egypt, we do not know what has become of him."', 'en', 'NRSV-CE', 'The Golden Calf'),
(2, 'Kel', 'Exodus', 32, 2, 'Aaron said to them, "Take off the gold rings that are on the ears of your wives, your sons, and your daughters, and bring them to me."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 32, 3, 'So all the people took off the gold rings from their ears, and brought them to Aaron.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 32, 4, 'He took the gold from them, formed it in a mold, and cast an image of a calf; and they said, "These are your gods, O Israel, who brought you up out of the land of Egypt!"', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 32, 5, 'When Aaron saw this, he built an altar before it; and Aaron made proclamation and said, "Tomorrow shall be a festival to the LORD."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 32, 6, 'They rose early the next day, and offered burnt offerings and brought sacrifices of well-being; and the people sat down to eat and drink, and rose up to revel.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 32, 7, 'The LORD said to Moses, "Go down at once! Your people, whom you brought up out of the land of Egypt, have acted perversely;', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 32, 8, 'they have been quick to turn aside from the way that I commanded them; they have cast for themselves an image of a calf, and have worshiped it and sacrificed to it, and said, "These are your gods, O Israel, who brought you up out of the land of Egypt!""', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 32, 9, 'The LORD said to Moses, "I have seen this people, how stiff-necked they are.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 32, 10, 'Now let me alone, so that my wrath may burn hot against them and I may consume them; and of you I will make a great nation."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 32, 11, 'But Moses implored the LORD his God, and said, "O LORD, why does your wrath burn hot against your people, whom you brought out of the land of Egypt with great power and with a mighty hand?', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 32, 12, 'Why should the Egyptians say, "It was with evil intent that he brought them out to kill them in the mountains, and to consume them from the face of the earth"? Turn from your fierce wrath; change your mind and do not bring disaster on your people.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 32, 13, 'Remember Abraham, Isaac, and Israel, your servants, how you swore to them by your own self, saying to them, "I will multiply your descendants like the stars of heaven, and all this land that I have promised I will give to your descendants, and they shall inherit it forever.""', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 32, 14, 'And the LORD changed his mind about the disaster that he planned to bring on his people.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 32, 15, 'Then Moses turned and went down from the mountain, carrying the two tablets of the covenant in his hands, tablets that were written on both sides, written on the front and on the back.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 32, 16, 'The tablets were the work of God, and the writing was the writing of God, engraved upon the tablets.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 32, 17, 'When Joshua heard the noise of the people as they shouted, he said to Moses, "There is a noise of war in the camp."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 32, 18, 'But he said,
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(2, 'Kel', 'Exodus', 33, 1, 'The LORD said to Moses, "Go, leave this place, you and the people whom you have brought up out of the land of Egypt, and go to the land of which I swore to Abraham, Isaac, and Jacob, saying, "To your descendants I will give it."', 'en', 'NRSV-CE', 'The Command to Leave Sinai'),
(2, 'Kel', 'Exodus', 33, 2, 'I will send an angel before you, and I will drive out the Canaanites, the Amorites, the Hittites, the Perizzites, the Hivites, and the Jebusites.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 33, 3, 'Go up to a land flowing with milk and honey; but I will not go up among you, or I would consume you on the way, for you are a stiff-necked people."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 33, 4, 'When the people heard these harsh words, they mourned, and no one put on ornaments.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 33, 5, 'For the LORD had said to Moses, "Say to the Israelites, "You are a stiff-necked people; if for a single moment I should go up among you, I would consume you. So now take off your ornaments, and I will decide what to do to you.""', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 33, 6, 'Therefore the Israelites stripped themselves of their ornaments, from Mount Horeb onward.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 33, 7, 'Now Moses used to take the tent and pitch it outside the camp, far off from the camp; he called it the tent of meeting. And everyone who sought the LORD would go out to the tent of meeting, which was outside the camp.', 'en', 'NRSV-CE', 'The Tent outside the Camp'),
(2, 'Kel', 'Exodus', 33, 8, 'Whenever Moses went out to the tent, all the people would rise and stand, each of them, at the entrance of their tents and watch Moses until he had gone into the tent.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 33, 9, 'When Moses entered the tent, the pillar of cloud would descend and stand at the entrance of the tent, and the LORD would speak with Moses.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 33, 10, 'When all the people saw the pillar of cloud standing at the entrance of the tent, all the people would rise and bow down, all of them, at the entrance of their tent.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 33, 11, 'Thus the LORD used to speak to Moses face to face, as one speaks to a friend. Then he would return to the camp; but his young assistant, Joshua son of Nun, would not leave the tent.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 33, 12, 'Moses said to the LORD, "See, you have said to me, "Bring up this people"; but you have not let me know whom you will send with me. Yet you have said, "I know you by name, and you have also found favor in my sight."', 'en', 'NRSV-CE', 'Moses" Intercession'),
(2, 'Kel', 'Exodus', 33, 13, 'Now if I have found favor in your sight, show me your ways, so that I may know you and find favor in your sight. Consider too that this nation is your people."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 33, 14, 'He said, "My presence will go with you, and I will give you rest."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 33, 15, 'And he said to him, "If your presence will not go, do not carry us up from here.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 33, 16, 'For how shall it be known that I have found favor in your sight, I and your people, unless you go with us? In this way, we shall be distinct, I and your people, from every people on the face of the earth."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 33, 17, 'The LORD said to Moses, "I will do the very thing that you have asked; for you have found favor in my sight, and I know you by name."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 33, 18, 'Moses said, "Show me your glory, I pray."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 33, 19, 'And he said, "I will make all my goodness pass before you, and will proclaim before you the name, "The LORD"; and I will be gracious to whom I will be gracious, and will show mercy on whom I will show mercy.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 33, 20, 'But," he said, "you cannot see my face; for no one shall see me and live."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 33, 21, 'And the LORD continued, "See, there is a place by me where you shall stand on the rock;', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 33, 22, 'and while my glory passes by I will put you in a cleft of the rock, and I will cover you with my hand until I have passed by;', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 33, 23, 'then I will take away my hand, and you shall see my back; but my face shall not be seen."', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(2, 'Kel', 'Exodus', 34, 1, 'The LORD said to Moses, "Cut two tablets of stone like the former ones, and I will write on the tablets the words that were on the former tablets, which you broke.', 'en', 'NRSV-CE', 'Moses Makes New Tablets'),
(2, 'Kel', 'Exodus', 34, 2, 'Be ready in the morning, and come up in the morning to Mount Sinai and present yourself there to me, on the top of the mountain.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 34, 3, 'No one shall come up with you, and do not let anyone be seen throughout all the mountain; and do not let flocks or herds graze in front of that mountain."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 34, 4, 'So Moses cut two tablets of stone like the former ones; and he rose early in the morning and went up on Mount Sinai, as the LORD had commanded him, and took in his hand the two tablets of stone.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 34, 5, 'The LORD descended in the cloud and stood with him there, and proclaimed the name, "The LORD."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 34, 6, 'The LORD passed before him, and proclaimed,
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(2, 'Kel', 'Exodus', 35, 1, 'Moses assembled all the congregation of the Israelites and said to them: These are the things that the LORD has commanded you to do:', 'en', 'NRSV-CE', 'Sabbath Regulations'),
(2, 'Kel', 'Exodus', 35, 2, 'Six days shall work be done, but on the seventh day you shall have a holy sabbath of solemn rest to the LORD; whoever does any work on it shall be put to death.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 35, 3, 'You shall kindle no fire in all your dwellings on the sabbath day.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 35, 4, 'Moses said to all the congregation of the Israelites: This is the thing that the LORD has commanded:', 'en', 'NRSV-CE', 'Preparations for Making the Tabernacle'),
(2, 'Kel', 'Exodus', 35, 5, 'Take from among you an offering to the LORD; let whoever is of a generous heart bring the LORD"s offering: gold, silver, and bronze;', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 35, 6, 'blue, purple, and crimson yarns, and fine linen; goats" hair,', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 35, 7, 'tanned rams" skins, and fine leather; acacia wood,', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 35, 8, 'oil for the light, spices for the anointing oil and for the fragrant incense,', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 35, 9, 'and onyx stones and gems to be set in the ephod and the breastpiece.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 35, 10, 'All who are skillful among you shall come and make all that the LORD has commanded: the tabernacle,', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 35, 11, 'its tent and its covering, its clasps and its frames, its bars, its pillars, and its bases;', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 35, 12, 'the ark with its poles, the mercy seat, and the curtain for the screen;', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 35, 13, 'the table with its poles and all its utensils, and the bread of the Presence;', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 35, 14, 'the lampstand also for the light, with its utensils and its lamps, and the oil for the light;', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 35, 15, 'and the altar of incense, with its poles, and the anointing oil and the fragrant incense, and the screen for the entrance, the entrance of the tabernacle;', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 35, 16, 'the altar of burnt offering, with its grating of bronze, its poles, and all its utensils, the basin with its stand;', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 35, 17, 'the hangings of the court, its pillars and its bases, and the screen for the gate of the court;', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 35, 18, 'the pegs of the tabernacle and the pegs of the court, and their cords;', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 35, 19, 'the finely worked vestments for ministering in the holy place, the holy vestments for the priest Aaron, and the vestments of his sons, for their service as priests.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 35, 20, 'Then all the congregation of the Israelites withdrew from the presence of Moses.', 'en', 'NRSV-CE', 'Offerings for the Tabernacle'),
(2, 'Kel', 'Exodus', 35, 21, 'And they came, everyone whose heart was stirred, and everyone whose spirit was willing, and brought the LORD"s offering to be used for the tent of meeting, and for all its service, and for the sacred vestments.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 35, 22, 'So they came, both men and women; all who were of a willing heart brought brooches and earrings and signet rings and pendants, all sorts of gold objects, everyone bringing an offering of gold to the LORD.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 35, 23, 'And everyone who possessed blue or purple or crimson yarn or fine linen or goats" hair or tanned rams" skins or fine leather, brought them.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 35, 24, 'Everyone who could make an offering of silver or bronze brought it as the LORD"s offering; and everyone who possessed acacia wood of any use in the work, brought it.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 35, 25, 'All the skillful women spun with their hands, and brought what they had spun in blue and purple and crimson yarns and fine linen;', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 35, 26, 'all the women whose hearts moved them to use their skill spun the goats" hair.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 35, 27, 'And the leaders brought onyx stones and gems to be set in the ephod and the breastpiece,', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 35, 28, 'and spices and oil for the light, and for the anointing oil, and for the fragrant incense.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 35, 29, 'All the Israelite men and women whose hearts made them willing to bring anything for the work that the LORD had commanded by Moses to be done, brought it as a freewill offering to the LORD.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 35, 30, 'Then Moses said to the Israelites: See, the LORD has called by name Bezalel son of Uri son of Hur, of the tribe of Judah;', 'en', 'NRSV-CE', 'Bezalel and Oholiab'),
(2, 'Kel', 'Exodus', 35, 31, 'he has filled him with divine spirit, with skill, intelligence, and knowledge in every kind of craft,', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 35, 32, 'to devise artistic designs, to work in gold, silver, and bronze,', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 35, 33, 'in cutting stones for setting, and in carving wood, in every kind of craft.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 35, 34, 'And he has inspired him to teach, both him and Oholiab son of Ahisamach, of the tribe of Dan.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 35, 35, 'He has filled them with skill to do every kind of work done by an artisan or by a designer or by an embroiderer in blue, purple, and crimson yarns, and in fine linen, or by a weaver--by any sort of artisan or skilled designer.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(2, 'Kel', 'Exodus', 36, 1, 'Bezalel and Oholiab and every skillful one to whom the LORD has given skill and understanding to know how to do any work in the construction of the sanctuary shall work in accordance with all that the LORD has commanded.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 36, 2, 'Moses then called Bezalel and Oholiab and every skillful one to whom the LORD had given skill, everyone whose heart was stirred to come to do the work;', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 36, 3, 'and they received from Moses all the freewill offerings that the Israelites had brought for doing the work on the sanctuary. They still kept bringing him freewill offerings every morning,', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 36, 4, 'so that all the artisans who were doing every sort of task on the sanctuary came, each from the task being performed,', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 36, 5, 'and said to Moses, "The people are bringing much more than enough for doing the work that the LORD has commanded us to do."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 36, 6, 'So Moses gave command, and word was proclaimed throughout the camp: "No man or woman is to make anything else as an offering for the sanctuary." So the people were restrained from bringing;', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 36, 7, 'for what they had already brought was more than enough to do all the work.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 36, 8, 'All those with skill among the workers made the tabernacle with ten curtains; they were made of fine twisted linen, and blue, purple, and crimson yarns, with cherubim skillfully worked into them.', 'en', 'NRSV-CE', 'Construction of the Tabernacle'),
(2, 'Kel', 'Exodus', 36, 9, 'The length of each curtain was twenty-eight cubits, and the width of each curtain four cubits; all the curtains were of the same size.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 36, 10, 'He joined five curtains to one another, and the other five curtains he joined to one another.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 36, 11, 'He made loops of blue on the edge of the outermost curtain of the first set; likewise he made them on the edge of the outermost curtain of the second set;', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 36, 12, 'he made fifty loops on the one curtain, and he made fifty loops on the edge of the curtain that was in the second set; the loops were opposite one another.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 36, 13, 'And he made fifty clasps of gold, and joined the curtains one to the other with clasps; so the tabernacle was one whole.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 36, 14, 'He also made curtains of goats" hair for a tent over the tabernacle; he made eleven curtains.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 36, 15, 'The length of each curtain was thirty cubits, and the width of each curtain four cubits; the eleven curtains were of the same size.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 36, 16, 'He joined five curtains by themselves, and six curtains by themselves.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 36, 17, 'He made fifty loops on the edge of the outermost curtain of the one set, and fifty loops on the edge of the other connecting curtain.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 36, 18, 'He made fifty clasps of bronze to join the tent together so that it might be one whole.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 36, 19, 'And he made for the tent a covering of tanned rams" skins and an outer covering of fine leather.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 36, 20, 'Then he made the upright frames for the tabernacle of acacia wood.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 36, 21, 'Ten cubits was the length of a frame, and a cubit and a half the width of each frame.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 36, 22, 'Each frame had two pegs for fitting together; he did this for all the frames of the tabernacle.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 36, 23, 'The frames for the tabernacle he made in this way: twenty frames for the south side;', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 36, 24, 'and he made forty bases of silver under the twenty frames, two bases under the first frame for its two pegs, and two bases under the next frame for its two pegs.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 36, 25, 'For the second side of the tabernacle, on the north side, he made twenty frames', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 36, 26, 'and their forty bases of silver, two bases under the first frame and two bases under the next frame.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 36, 27, 'For the rear of the tabernacle westward he made six frames.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 36, 28, 'He made two frames for corners of the tabernacle in the rear.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 36, 29, 'They were separate beneath, but joined at the top, at the first ring; he made two of them in this way, for the two corners.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 36, 30, 'There were eight frames with their bases of silver: sixteen bases, under every frame two bases.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 36, 31, 'He made bars of acacia wood, five for the frames of the one side of the tabernacle,', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 36, 32, 'and five bars for the frames of the other side of the tabernacle, and five bars for the frames of the tabernacle at the rear westward.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 36, 33, 'He made the middle bar to pass through from end to end halfway up the frames.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 36, 34, 'And he overlaid the frames with gold, and made rings of gold for them to hold the bars, and overlaid the bars with gold.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 36, 35, 'He made the curtain of blue, purple, and crimson yarns, and fine twisted linen, with cherubim skillfully worked into it.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 36, 36, 'For it he made four pillars of acacia, and overlaid them with gold; their hooks were of gold, and he cast for them four bases of silver.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 36, 37, 'He also made a screen for the entrance to the tent, of blue, purple, and crimson yarns, and fine twisted linen, embroidered with needlework;', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 36, 38, 'and its five pillars with their hooks. He overlaid their capitals and their bases with gold, but their five bases were of bronze.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(2, 'Kel', 'Exodus', 37, 1, 'Bezalel made the ark of acacia wood; it was two and a half cubits long, a cubit and a half wide, and a cubit and a half high.', 'en', 'NRSV-CE', 'Making the Ark of the Covenant'),
(2, 'Kel', 'Exodus', 37, 2, 'He overlaid it with pure gold inside and outside, and made a molding of gold around it.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 37, 3, 'He cast for it four rings of gold for its four feet, two rings on its one side and two rings on its other side.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 37, 4, 'He made poles of acacia wood, and overlaid them with gold,', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 37, 5, 'and put the poles into the rings on the sides of the ark, to carry the ark.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 37, 6, 'He made a mercy seat of pure gold; two cubits and a half was its length, and a cubit and a half its width.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 37, 7, 'He made two cherubim of hammered gold; at the two ends of the mercy seat he made them,', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 37, 8, 'one cherub at the one end, and one cherub at the other end; of one piece with the mercy seat he made the cherubim at its two ends.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 37, 9, 'The cherubim spread out their wings above, overshadowing the mercy seat with their wings. They faced one another; the faces of the cherubim were turned toward the mercy seat.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 37, 10, 'He also made the table of acacia wood, two cubits long, one cubit wide, and a cubit and a half high.', 'en', 'NRSV-CE', 'Making the Table for the Bread of the Presence'),
(2, 'Kel', 'Exodus', 37, 11, 'He overlaid it with pure gold, and made a molding of gold around it.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 37, 12, 'He made around it a rim a handbreadth wide, and made a molding of gold around the rim.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 37, 13, 'He cast for it four rings of gold, and fastened the rings to the four corners at its four legs.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 37, 14, 'The rings that held the poles used for carrying the table were close to the rim.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 37, 15, 'He made the poles of acacia wood to carry the table, and overlaid them with gold.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 37, 16, 'And he made the vessels of pure gold that were to be on the table, its plates and dishes for incense, and its bowls and flagons with which to pour drink offerings.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 37, 17, 'He also made the lampstand of pure gold. The base and the shaft of the lampstand were made of hammered work; its cups, its calyxes, and its petals were of one piece with it.', 'en', 'NRSV-CE', 'Making the Lampstand'),
(2, 'Kel', 'Exodus', 37, 18, 'There were six branches going out of its sides, three branches of the lampstand out of one side of it and three branches of the lampstand out of the other side of it;', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 37, 19, 'three cups shaped like almond blossoms, each with calyx and petals, on one branch, and three cups shaped like almond blossoms, each with calyx and petals, on the other branch--so for the six branches going out of the lampstand.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 37, 20, 'On the lampstand itself there were four cups shaped like almond blossoms, each with its calyxes and petals.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 37, 21, 'There was a calyx of one piece with it under the first pair of branches, a calyx of one piece with it under the next pair of branches, and a calyx of one piece with it under the last pair of branches.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 37, 22, 'Their calyxes and their branches were of one piece with it, the whole of it one hammered piece of pure gold.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 37, 23, 'He made its seven lamps and its snuffers and its trays of pure gold.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 37, 24, 'He made it and all its utensils of a talent of pure gold.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 37, 25, 'He made the altar of incense of acacia wood, one cubit long, and one cubit wide; it was square, and was two cubits high; its horns were of one piece with it.', 'en', 'NRSV-CE', 'Making the Altar of Incense'),
(2, 'Kel', 'Exodus', 37, 26, 'He overlaid it with pure gold, its top, and its sides all around, and its horns; and he made for it a molding of gold all around,', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 37, 27, 'and made two golden rings for it under its molding, on two opposite sides of it, to hold the poles with which to carry it.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 37, 28, 'And he made the poles of acacia wood, and overlaid them with gold.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 37, 29, 'He made the holy anointing oil also, and the pure fragrant incense, blended as by the perfumer.', 'en', 'NRSV-CE', 'Making the Anointing Oil and the Incense');
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(2, 'Kel', 'Exodus', 38, 1, 'He made the altar of burnt offering also of acacia wood; it was five cubits long, and five cubits wide; it was square, and three cubits high.', 'en', 'NRSV-CE', 'Making the Altar of Burnt Offering'),
(2, 'Kel', 'Exodus', 38, 2, 'He made horns for it on its four corners; its horns were of one piece with it, and he overlaid it with bronze.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 38, 3, 'He made all the utensils of the altar, the pots, the shovels, the basins, the forks, and the firepans: all its utensils he made of bronze.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 38, 4, 'He made for the altar a grating, a network of bronze, under its ledge, extending halfway down.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 38, 5, 'He cast four rings on the four corners of the bronze grating to hold the poles;', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 38, 6, 'he made the poles of acacia wood, and overlaid them with bronze.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 38, 7, 'And he put the poles through the rings on the sides of the altar, to carry it with them; he made it hollow, with boards.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 38, 8, 'He made the basin of bronze with its stand of bronze, from the mirrors of the women who served at the entrance to the tent of meeting.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 38, 9, 'He made the court; for the south side the hangings of the court were of fine twisted linen, one hundred cubits long;', 'en', 'NRSV-CE', 'Making the Court of the Tabernacle'),
(2, 'Kel', 'Exodus', 38, 10, 'its twenty pillars and their twenty bases were of bronze, but the hooks of the pillars and their bands were of silver.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 38, 11, 'For the north side there were hangings one hundred cubits long; its twenty pillars and their twenty bases were of bronze, but the hooks of the pillars and their bands were of silver.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 38, 12, 'For the west side there were hangings fifty cubits long, with ten pillars and ten bases; the hooks of the pillars and their bands were of silver.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 38, 13, 'And for the front to the east, fifty cubits.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 38, 14, 'The hangings for one side of the gate were fifteen cubits, with three pillars and three bases.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 38, 15, 'And so for the other side; on each side of the gate of the court were hangings of fifteen cubits, with three pillars and three bases.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 38, 16, 'All the hangings around the court were of fine twisted linen.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 38, 17, 'The bases for the pillars were of bronze, but the hooks of the pillars and their bands were of silver; the overlaying of their capitals was also of silver, and all the pillars of the court were banded with silver.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 38, 18, 'The screen for the entrance to the court was embroidered with needlework in blue, purple, and crimson yarns and fine twisted linen. It was twenty cubits long and, along the width of it, five cubits high, corresponding to the hangings of the court.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 38, 19, 'There were four pillars; their four bases were of bronze, their hooks of silver, and the overlaying of their capitals and their bands of silver.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 38, 20, 'All the pegs for the tabernacle and for the court all around were of bronze.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 38, 21, 'These are the records of the tabernacle, the tabernacle of the covenant, which were drawn up at the commandment of Moses, the work of the Levites being under the direction of Ithamar son of the priest Aaron.', 'en', 'NRSV-CE', 'Materials of the Tabernacle'),
(2, 'Kel', 'Exodus', 38, 22, 'Bezalel son of Uri son of Hur, of the tribe of Judah, made all that the LORD commanded Moses;', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 38, 23, 'and with him was Oholiab son of Ahisamach, of the tribe of Dan, engraver, designer, and embroiderer in blue, purple, and crimson yarns, and in fine linen.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 38, 24, 'All the gold that was used for the work, in all the construction of the sanctuary, the gold from the offering, was twenty-nine talents and seven hundred thirty shekels, measured by the sanctuary shekel.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 38, 25, 'The silver from those of the congregation who were counted was one hundred talents and one thousand seven hundred seventy-five shekels, measured by the sanctuary shekel;', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 38, 26, 'a beka a head (that is, half a shekel, measured by the sanctuary shekel), for everyone who was counted in the census, from twenty years old and upward, for six hundred three thousand, five hundred fifty men.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 38, 27, 'The hundred talents of silver were for casting the bases of the sanctuary, and the bases of the curtain; one hundred bases for the hundred talents, a talent for a base.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 38, 28, 'Of the thousand seven hundred seventy-five shekels he made hooks for the pillars, and overlaid their capitals and made bands for them.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 38, 29, 'The bronze that was contributed was seventy talents, and two thousand four hundred shekels;', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 38, 30, 'with it he made the bases for the entrance of the tent of meeting, the bronze altar and the bronze grating for it and all the utensils of the altar,', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 38, 31, 'the bases all around the court, and the bases of the gate of the court, all the pegs of the tabernacle, and all the pegs around the court.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(2, 'Kel', 'Exodus', 39, 1, 'Of the blue, purple, and crimson yarns they made finely worked vestments, for ministering in the holy place; they made the sacred vestments for Aaron; as the LORD had commanded Moses.', 'en', 'NRSV-CE', 'Making the Vestments for the Priesthood'),
(2, 'Kel', 'Exodus', 39, 2, 'He made the ephod of gold, of blue, purple, and crimson yarns, and of fine twisted linen.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 39, 3, 'Gold leaf was hammered out and cut into threads to work into the blue, purple, and crimson yarns and into the fine twisted linen, in skilled design.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 39, 4, 'They made for the ephod shoulder-pieces, joined to it at its two edges.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 39, 5, 'The decorated band on it was of the same materials and workmanship, of gold, of blue, purple, and crimson yarns, and of fine twisted linen; as the LORD had commanded Moses.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 39, 6, 'The onyx stones were prepared, enclosed in settings of gold filigree and engraved like the engravings of a signet, according to the names of the sons of Israel.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 39, 7, 'He set them on the shoulder-pieces of the ephod, to be stones of remembrance for the sons of Israel; as the LORD had commanded Moses.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 39, 8, 'He made the breastpiece, in skilled work, like the work of the ephod, of gold, of blue, purple, and crimson yarns, and of fine twisted linen.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 39, 9, 'It was square; the breastpiece was made double, a span in length and a span in width when doubled.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 39, 10, 'They set in it four rows of stones. A row of carnelian, chrysolite, and emerald was the first row;', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 39, 11, 'and the second row, a turquoise, a sapphire, and a moonstone;', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 39, 12, 'and the third row, a jacinth, an agate, and an amethyst;', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 39, 13, 'and the fourth row, a beryl, an onyx, and a jasper; they were enclosed in settings of gold filigree.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 39, 14, 'There were twelve stones with names corresponding to the names of the sons of Israel; they were like signets, each engraved with its name, for the twelve tribes.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 39, 15, 'They made on the breastpiece chains of pure gold, twisted like cords;', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 39, 16, 'and they made two settings of gold filigree and two gold rings, and put the two rings on the two edges of the breastpiece;', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 39, 17, 'and they put the two cords of gold in the two rings at the edges of the breastpiece.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 39, 18, 'Two ends of the two cords they had attached to the two settings of filigree; in this way they attached it in front to the shoulder-pieces of the ephod.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 39, 19, 'Then they made two rings of gold, and put them at the two ends of the breastpiece, on its inside edge next to the ephod.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 39, 20, 'They made two rings of gold, and attached them in front to the lower part of the two shoulder-pieces of the ephod, at its joining above the decorated band of the ephod.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 39, 21, 'They bound the breastpiece by its rings to the rings of the ephod with a blue cord, so that it should lie on the decorated band of the ephod, and that the breastpiece should not come loose from the ephod; as the LORD had commanded Moses.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 39, 22, 'He also made the robe of the ephod woven all of blue yarn;', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 39, 23, 'and the opening of the robe in the middle of it was like the opening in a coat of mail, with a binding around the opening, so that it might not be torn.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 39, 24, 'On the lower hem of the robe they made pomegranates of blue, purple, and crimson yarns, and of fine twisted linen.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 39, 25, 'They also made bells of pure gold, and put the bells between the pomegranates on the lower hem of the robe all around, between the pomegranates;', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 39, 26, 'a bell and a pomegranate, a bell and a pomegranate all around on the lower hem of the robe for ministering; as the LORD had commanded Moses.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 39, 27, 'They also made the tunics, woven of fine linen, for Aaron and his sons,', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 39, 28, 'and the turban of fine linen, and the headdresses of fine linen, and the linen undergarments of fine twisted linen,', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 39, 29, 'and the sash of fine twisted linen, and of blue, purple, and crimson yarns, embroidered with needlework; as the LORD had commanded Moses.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 39, 30, 'They made the rosette of the holy diadem of pure gold, and wrote on it an inscription, like the engraving of a signet, "Holy to the LORD."', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 39, 31, 'They tied to it a blue cord, to fasten it on the turban above; as the LORD had commanded Moses.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 39, 32, 'In this way all the work of the tabernacle of the tent of meeting was finished; the Israelites had done everything just as the LORD had commanded Moses.', 'en', 'NRSV-CE', 'The Work Completed'),
(2, 'Kel', 'Exodus', 39, 33, 'Then they brought the tabernacle to Moses, the tent and all its utensils, its hooks, its frames, its bars, its pillars, and its bases;', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 39, 34, 'the covering of tanned rams" skins and the covering of fine leather, and the curtain for the screen;', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 39, 35, 'the ark of the covenant with its poles and the mercy seat;', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 39, 36, 'the table with all its utensils, and the bread of the Presence;', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 39, 37, 'the pure lampstand with its lamps set on it and all its utensils, and the oil for the light;', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 39, 38, 'the golden altar, the anointing oil and the fragrant incense, and the screen for the entrance of the tent;', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 39, 39, 'the bronze altar, and its grating of bronze, its poles, and all its utensils; the basin with its stand;', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 39, 40, 'the hangings of the court, its pillars, and its bases, and the screen for the gate of the court, its cords, and its pegs; and all the utensils for the service of the tabernacle, for the tent of meeting;', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 39, 41, 'the finely worked vestments for ministering in the holy place, the sacred vestments for the priest Aaron, and the vestments of his sons to serve as priests.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 39, 42, 'The Israelites had done all of the work just as the LORD had commanded Moses.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 39, 43, 'When Moses saw that they had done all the work just as the LORD had commanded, he blessed them.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(2, 'Kel', 'Exodus', 40, 1, 'The LORD spoke to Moses:', 'en', 'NRSV-CE', 'The Tabernacle Erected and Its Equipment Installed'),
(2, 'Kel', 'Exodus', 40, 2, 'On the first day of the first month you shall set up the tabernacle of the tent of meeting.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 40, 3, 'You shall put in it the ark of the covenant, and you shall screen the ark with the curtain.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 40, 4, 'You shall bring in the table, and arrange its setting; and you shall bring in the lampstand, and set up its lamps.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 40, 5, 'You shall put the golden altar for incense before the ark of the covenant, and set up the screen for the entrance of the tabernacle.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 40, 6, 'You shall set the altar of burnt offering before the entrance of the tabernacle of the tent of meeting,', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 40, 7, 'and place the basin between the tent of meeting and the altar, and put water in it.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 40, 8, 'You shall set up the court all around, and hang up the screen for the gate of the court.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 40, 9, 'Then you shall take the anointing oil, and anoint the tabernacle and all that is in it, and consecrate it and all its furniture, so that it shall become holy.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 40, 10, 'You shall also anoint the altar of burnt offering and all its utensils, and consecrate the altar, so that the altar shall be most holy.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 40, 11, 'You shall also anoint the basin with its stand, and consecrate it.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 40, 12, 'Then you shall bring Aaron and his sons to the entrance of the tent of meeting, and shall wash them with water,', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 40, 13, 'and put on Aaron the sacred vestments, and you shall anoint him and consecrate him, so that he may serve me as priest.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 40, 14, 'You shall bring his sons also and put tunics on them,', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 40, 15, 'and anoint them, as you anointed their father, that they may serve me as priests: and their anointing shall admit them to a perpetual priesthood throughout all generations to come.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 40, 16, 'Moses did everything just as the LORD had commanded him.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 40, 17, 'In the first month in the second year, on the first day of the month, the tabernacle was set up.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 40, 18, 'Moses set up the tabernacle; he laid its bases, and set up its frames, and put in its poles, and raised up its pillars;', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 40, 19, 'and he spread the tent over the tabernacle, and put the covering of the tent over it; as the LORD had commanded Moses.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 40, 20, 'He took the covenant and put it into the ark, and put the poles on the ark, and set the mercy seat above the ark;', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 40, 21, 'and he brought the ark into the tabernacle, and set up the curtain for screening, and screened the ark of the covenant; as the LORD had commanded Moses.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 40, 22, 'He put the table in the tent of meeting, on the north side of the tabernacle, outside the curtain,', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 40, 23, 'and set the bread in order on it before the LORD; as the LORD had commanded Moses.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 40, 24, 'He put the lampstand in the tent of meeting, opposite the table on the south side of the tabernacle,', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 40, 25, 'and set up the lamps before the LORD; as the LORD had commanded Moses.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 40, 26, 'He put the golden altar in the tent of meeting before the curtain,', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 40, 27, 'and offered fragrant incense on it; as the LORD had commanded Moses.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 40, 28, 'He also put in place the screen for the entrance of the tabernacle.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 40, 29, 'He set the altar of burnt offering at the entrance of the tabernacle of the tent of meeting, and offered on it the burnt offering and the grain offering as the LORD had commanded Moses.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 40, 30, 'He set the basin between the tent of meeting and the altar, and put water in it for washing,', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 40, 31, 'with which Moses and Aaron and his sons washed their hands and their feet.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 40, 32, 'When they went into the tent of meeting, and when they approached the altar, they washed; as the LORD had commanded Moses.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 40, 33, 'He set up the court around the tabernacle and the altar, and put up the screen at the gate of the court. So Moses finished the work.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 40, 34, 'Then the cloud covered the tent of meeting, and the glory of the LORD filled the tabernacle.', 'en', 'NRSV-CE', 'The Cloud and the Glory'),
(2, 'Kel', 'Exodus', 40, 35, 'Moses was not able to enter the tent of meeting because the cloud settled upon it, and the glory of the LORD filled the tabernacle.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 40, 36, 'Whenever the cloud was taken up from the tabernacle, the Israelites would set out on each stage of their journey;', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 40, 37, 'but if the cloud was not taken up, then they did not set out until the day that it was taken up.', 'en', 'NRSV-CE', NULL),
(2, 'Kel', 'Exodus', 40, 38, 'For the cloud of the LORD was on the tabernacle by day, and fire was in the cloud by night, before the eyes of all the house of Israel at each stage of their journey.', 'en', 'NRSV-CE', NULL);
